module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wclk,
    input wrstn,
    input rclk,
    input rrstn,
    input winc,
    input rinc,
    input [WIDTH-1:0] wdata,
    output wfull,
    output rempty,
    output [WIDTH-1:0] rdata
);

localparam DEPTH_BITS = $clog2(DEPTH);
localparam FULL_MASK = ( (1 << (DEPTH_BITS-1)) | (1 << (DEPTH_BITS-2)) );


reg [DEPTH_BITS-1:0] wptr_bin;
wire [DEPTH_BITS-1:0] wptr_gray = wptr_bin ^ (wptr_bin >> 1);
wire [DEPTH_BITS-1:0] waddr = wptr_bin[DEPTH_BITS-2:0];
wire wen = winc && !wfull;


reg [DEPTH_BITS-1:0] rptr_bin;
wire [DEPTH_BITS-1:0] rptr_gray = rptr_bin ^ (rptr_bin >> 1);
wire [DEPTH_BITS-1:0] raddr = rptr_bin[DEPTH_BITS-2:0];
wire ren = rinc && !rempty;


reg [DEPTH_BITS-1:0] rptr_gray_sync1, rptr_gray_sync;
always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        rptr_gray_sync1 <= 0;
        rptr_gray_sync <= 0;
    end else begin
        rptr_gray_sync1 <= rptr_gray;
        rptr_gray_sync <= rptr_gray_sync1;
    end
end

reg [DEPTH_BITS-1:0] wptr_gray_sync1, wptr_gray_sync;
always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        wptr_gray_sync1 <= 0;
        wptr_gray_sync <= 0;
    end else begin
        wptr_gray_sync1 <= wptr_gray;
        wptr_gray_sync <= wptr_gray_sync1;
    end
end


assign wfull = (wptr_gray == (rptr_gray_sync ^ FULL_MASK));
assign rempty = (rptr_gray == wptr_gray_sync);


dual_port_RAM #(
    .DEPTH(DEPTH),
    .WIDTH(WIDTH)
) ram (
    .wclk(wclk),
    .wenc(wen),
    .waddr(waddr),
    .wdata(wdata),
    .rclk(rclk),
    .renc(ren),
    .raddr(raddr),
    .rdata(rdata)
);


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        wptr_bin <= 0;
    end else if (wen) begin
        wptr_bin <= wptr_bin + 1;
    end
end

always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        rptr_bin <= 0;
    end else if (ren) begin
        rptr_bin <= rptr_bin + 1;
    end
end

endmodule


module dual_port_RAM #(
    parameter DEPTH = 16,
    parameter WIDTH = 8
) (
    input wclk,
    input wenc,
    input [$clog2(DEPTH)-1:0] waddr,
    input [WIDTH-1:0] wdata,
    input rclk,
    input renc,
    input [$clog2(DEPTH)-1:0] raddr,
    output reg [WIDTH-1:0] rdata
);

reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];


always @(posedge wclk) begin
    if (wenc) RAM_MEM[waddr] <= wdata;
end


always @(posedge rclk) begin
    if (renc) rdata <= RAM_MEM[raddr];
end

endmodule

