module LIFObuffer (
    input Clk,
    input Rst,
    input EN,
    input RW,
    input [3:0] dataIn,
    output EMPTY,
    output FULL,
    output reg [3:0] dataOut
);

reg [2:0] SP;
reg [3:0] stack_mem [0:3];
integer i;

assign EMPTY = (SP == 3'd4);
assign FULL = (SP == 3'd0);

always @(posedge Clk) begin
    if (Rst) begin
        SP <= 3'd4;
        dataOut <= 4'b0;
        for (i = 0;
 i < 4;
 i = i + 1)
            stack_mem[i] <= 4'b0;
    end
    else if (EN) begin
        if (!FULL && !EMPTY) begin
            if (RW) begin 
                dataOut <= stack_mem[SP];
                SP <= SP + 3'd1;
            end
            else begin 
                stack_mem[SP - 3'd1] <= dataIn;
                SP <= SP - 3'd1;
            end
        end
        else if (RW && !EMPTY) begin 
            dataOut <= stack_mem[SP];
            SP <= SP + 3'd1;
        end
        else if (!RW && !FULL) begin 
            stack_mem[SP - 3'd1] <= dataIn;
            SP <= SP - 3'd1;
        end
    end
end

endmodule

