module traffic_light(
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);

parameter idle = 2'b00;
parameter s1_red = 2'b01;
parameter s2_yellow = 2'b10;
parameter s3_green = 2'b11;

reg [1:0] state, next_state;
reg [7:0] cnt;
reg p_red, p_yellow, p_green;


always @(*) begin
    case (state)
        idle:    next_state = s1_red;
        s1_red:  next_state = (cnt == 10) ? s3_green : s1_red;
        s3_green: next_state = (cnt == 60) ? s2_yellow : s3_green;
        s2_yellow: next_state = (cnt == 5) ? s1_red : s2_yellow;
        default: next_state = idle;
    endcase
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        cnt <= 10;
        state <= s1_red;
    end else begin
        state <= next_state;

        if (pass_request && green)         cnt <= 10;
        else if (!green && p_green)        cnt <= 60;
        else if (!yellow && p_yellow)      cnt <= 5;
        else if (!red && p_red)            cnt <= 10;
        else                                cnt <= cnt - 1;
    end
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        p_red <= 0;
        p_yellow <= 0;
        p_green <= 0;
    end else begin
        p_red <= (next_state == s1_red);
        p_yellow <= (next_state == s2_yellow);
        p_green <= (next_state == s3_green);
    end
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        red <= 0;
        yellow <= 0;
        green <= 0;
    end else begin
        red <= p_red;
        yellow <= p_yellow;
        green <= p_green;
    end
end

assign clock = cnt;

endmodule

