module alu (
    input [31:0] a, b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output reg carry,
    output negative,
    output reg overflow,
    output flag
);

    parameter ADD  = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB  = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND  = 6'b100100;
    parameter OR   = 6'b100101;
    parameter XOR  = 6'b100110;
    parameter NOR  = 6'b100111;
    parameter SLT  = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL  = 6'b000000;
    parameter SRL  = 6'b000010;
    parameter SRA  = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI  = 6'b001111;

    reg [32:0] res;

    assign zero = (r == 32'b0);
    assign negative = r[31];
    assign flag = (aluc == SLT || aluc == SLTU) ? 1'b1 : 1'bz;

    always @(*) begin
        case (aluc)
            ADD: begin
                res = a + b;
                overflow = (a[31] == b[31]) && (res[31] != a[31]);
                carry = res[32];
            end
            ADDU: begin
                res = a + b;
                overflow = 1'b0;
                carry = res[32];
            end
            SUB: begin
                res = a - b;
                overflow = (a[31] != b[31]) && (res[31] != a[31]);
                carry = res[32];
            end
            SUBU: begin
                res = a - b;
                overflow = 1'b0;
                carry = res[32];
            end
            AND: begin
                res = a & b;
                overflow = 1'b0;
                carry = 1'b0;
            end
            OR: begin
                res = a | b;
                overflow = 1'b0;
                carry = 1'b0;
            end
            XOR: begin
                res = a ^ b;
                overflow = 1'b0;
                carry = 1'b0;
            end
            NOR: begin
                res = ~(a | b);
                overflow = 1'b0;
                carry = 1'b0;
            end
            SLT: begin
