module fixed_point_adder #(
    parameter Q = 3,
    parameter N = 8
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

    reg [N-1:0] res;
    wire [N-1:0] abs_a = a[N-1] ? (~a + 1) : a;
    wire [N-1:0] abs_b = b[N-1] ? (~b + 1) : b;
    wire sign_a = a[N-1];
    wire sign_b = b[N-1];
    reg [N-1:0] sum;
    reg sign;
    wire signed [N-1:0] a_signed = a;
    wire signed [N-1:0] b_signed = b;
    wire signed [N:0] diff_signed = a_signed - b_signed;
    wire [N-1:0] magnitude_diff = diff_signed[N-1] ? (-diff_signed) : diff_signed;
    wire sign_diff = diff_signed[N-1];

    always @(*) begin
        if (sign_a == sign_b) begin
            sum = abs_a + abs_b;
            sign = sign_a;
        end else begin
            sum = magnitude_diff;
            sign = sign_diff;
        end

        res = {sign, sum[N-2:0]};

        c = res;
    end

endmodule

