    wire [N-1:0] abs_b = sign_b ? (~b + 1) : b;
    wire [N:0] sum_abs = abs_a + abs_b;
    wire [N-1:0] sum_abs_trim = sum_abs[N-1:0];
    wire [N-1:0] res_same_sign = a - b;
    wire sign_diff = (abs_a >= abs_b) ? sign_a : sign_b;

    always @(*) begin
        if (same_sign) begin
            res = res_same_sign;
        end else begin
            res = sum_abs_trim == 0 ? 0 : {sign_diff, sum_abs_trim[N-2:0]};
        end
    end

    assign c = res;

