module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [9:0] a_exponent, b_exponent, z_exponent;
    reg [23:0] a_mantissa, b_mantissa;
    reg [49:0] product;
    reg guard_bit, round_bit, sticky;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'd0;
            a_sign <= 1'b0;
            b_sign <= 1'b0;
            a_exponent <= 10'd0;
            b_exponent <= 10'd0;
            a_mantissa <= 24'd0;
            b_mantissa <= 24'd0;
            product <= 50'd0;
            guard_bit <= 1'b0;
            round_bit <= 1'b0;
            sticky <= 1'b0;
        end else begin
            case (counter)
                3'd0: begin  
                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= (a[30:23] == 8'd0) ? {1'b0, a[22:0]} : {1'b1, a[22:0]};
                    b_mantissa <= (b[30:23] == 8'd0) ? {1'b0, b[22:0]} : {1'b1, b[22:0]};
                    counter <= 3'd1;
                end
                3'd1: begin  
                    if ((a_exponent[7] && |a_mantissa) || (b_exponent[7] && |b_mantissa)) begin  
                        z_sign <= a_sign ^ b_sign;
                        z_exponent <= 10'hff;
                        z <= {z_sign, 8'hff, 23'h1};
                        counter <= 3'd0;
                    end else if ((a_exponent == 10'hff && a_mantissa == 0) || 
                                 (b_exponent == 10'hff && b_mantissa == 0)) begin  
                        if ((a_exponent == 10'hff && a_mantissa == 0) && 
                            (b_exponent == 10'hff || b_mantissa == 0) || 
                            (b_exponent == 10'hff && b_mantissa == 0) && 
                            a_exponent == 10'hff) begin
                            z_sign <= a_sign ^ b_sign;
                            z_exponent <= 10'hff;
                            z <= {z_sign, 8'hff, 23'd0};
                            counter <= 3'd0;
                        end else begin
                            counter <= 3'd2;
                        end
                    end else if (a_exponent == 10'd0 && a_mantissa == 0 && 
                                 b_exponent == 10'd0 && b_mantissa == 0) begin  
                        z_sign <= a_sign ^ b_sign;
                        z <= 32'd0;
                        counter <= 3'd0;
                    end else begin
                        product <= a_mantissa * b_mantissa;
                        counter <= 3'd2;
                    end
                end
                3'd2: begin  
                    if (product[47:46] >= 2) begin
                        product <= product >> 1;
                        z_exponent <= a_exponent + b_exponent - 10'd127 + 1;
                    end else begin
                        z_exponent <= a_exponent + b_exponent - 10'd127;
                    end
                    counter <= 3'd3;
                end
                3'd3: begin  
                    guard_bit <= product[46];
                    round_bit <= product[45];
                    sticky <= |product[44:0];
                    if (guard_bit && (round_bit || sticky)) begin
                        if (product[47]) product <= product + 1;
                    end else if (guard_bit && !round_bit && !sticky) begin
                        if (product[47]) product <= product + 1;
                    end
                    counter <= 3'd4;
                end
                3'd4: begin  
                    if (z_exponent > 10'd254) begin
                        z <= {z_sign, 8'hff, 23'd0};
                    end else if (z_exponent == 10'd0) begin
                        z <= {z_sign, 31'd0};
                    end else begin
                        z <= {z_sign, z_exponent[7:0], product[46:23]};
                    end
                    counter <= 3'd0;
                end
                default: counter <= 3'd0;
            endcase
        end
    end

endmodule

