    input rclk,
    input rrstn,
    input rinc,

    output wfull,
    output rempty,
    output [WIDTH-1:0] rdata
);

    reg [3:0] waddr_bin, raddr_bin;
    wire [3:0] wgray, rgray;
    reg [3:0] rgray_syn1, rgray_syn;
    reg [3:0] wgray_syn1, wgray_syn;


    dual_port_RAM #(
        .DEPTH(DEPTH),
        .WIDTH(WIDTH)
    ) ram (
        .wclk(wclk),
        .wenc(winc && !wfull),
        .waddr(waddr_bin[2:0]), 
        .wdata(wdata),
        .rclk(rclk),
        .renc(rinc && !rempty),
        .raddr(raddr_bin[2:0]),
        .rdata(rdata)
    );


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            waddr_bin <= 4'b0;
        end else if (winc && !wfull) begin
            waddr_bin <= waddr_bin + 1;
        end
    end
    assign wgray = waddr_bin ^ (waddr_bin >> 1);


    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            raddr_bin <= 4'b0;
        end else if (rinc && !rempty) begin
            raddr_bin <= raddr_bin + 1;
        end
    end
    assign rgray = raddr_bin ^ (raddr_bin >> 1);



    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            rgray_syn1 <= 4'b0;
            rgray_syn <= 4'b0;
        end else begin
            rgray_syn1 <= rgray;
            rgray_syn <= rgray_syn1;
