            wgray_syn1 <= wgray;
            wgray_syn <= wgray_syn1;
        end
    end


    assign rempty = (rgray == wgray_syn);
    assign wfull = (wgray[3] != rgray_syn[3]) && (wgray[2] != rgray_syn[2]) && (wgray[1:0] == rgray_syn[1:0]);

