module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

    reg [1:0] state_reg, state_next;
    localparam S0 = 2'b00,
               S1 = 2'b01,
               S2 = 2'b10;


    always @* begin
        case (state_reg)
            S0: state_next = (data_in) ? S0 : S1;
            S1: state_next = (data_in) ? S2 : S0;
            S2: state_next = S0;

            default: state_next = S0;
        endcase
    end


    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            state_reg <= S0;
            data_out <= 1'b0;
        end else begin
            state_reg <= state_next;

            data_out <= (state_reg == S2) && (~data_in);
        end
    end

endmodule

