module edge_detect (
    input clk,
    input rst_n,
    input a,
    output rise,
    output down
);

reg a_prev;
reg rise_ff;
reg down_ff;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        a_prev <= 1'b0;
        rise_ff <= 1'b0;
        down_ff <= 1'b0;
    end else begin
        a_prev <= a;

        if (a_prev == 1'b0 && a == 1'b1) begin
            rise_ff <= 1'b1;
        end

        if (a_prev == 1'b1 && a == 1'b0) begin
            down_ff <= 1'b1;
        end
    end
end

assign rise = rise_ff;
assign down = down_ff;

endmodule

