module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [7:0] abs_dividend, abs_divisor;
reg [15:0] SR;
reg [3:0] cnt;
reg start_cnt;
reg [7:0] quotient;
reg [7:0] remainder;
reg operation_sign;

wire [8:0] temp_remainder;
wire carry_out;

assign temp_remainder = SR[15:8] + abs_divisor;
assign carry_out = ~temp_remainder[8];

always @(posedge clk) begin
    if (rst) begin
        res_valid <= 0;
        result <= 0;
        abs_dividend <= 0;
        abs_divisor <= 0;
        SR <= 0;
        cnt <= 0;
        start_cnt <= 0;
        quotient <= 0;
        remainder <= 0;
        operation_sign <= 0;
    end else begin
        if (opn_valid && !res_valid) begin
            operation_sign <= sign;
            if (sign) begin
                abs_dividend <= dividend[7] ? -dividend : dividend;
                abs_divisor <= divisor[7] ? -divisor : divisor;
            end else begin
                abs_dividend <= dividend;
                abs_divisor <= divisor;
            end
            SR <= {abs_dividend, 8'b0} << 1;
            cnt <= 1;
            start_cnt <= 1;
            res_valid <= 0;
            quotient <= 0;
        end else if (start_cnt) begin
            if (cnt == 8) begin
                start_cnt <= 0;
                remainder <= SR[15:8];
                quotient <= SR[7:0];
                res_valid <= 1;
                result <= {remainder, quotient};
            end else begin
                SR <= {carry_out ? temp_remainder[7:0] : SR[15:8], SR[14:1], carry_out};
                quotient <= {quotient[6:0], carry_out};
                cnt <= cnt + 1;
            end
        end
        if (res_valid && opn_valid) begin
            res_valid <= 0;
        end
    end
end

endmodule

