    if (!rst_n) begin
        done_r <= 1'b0;
    end else begin
        if (i == 5'd16) begin
            done_r <= 1'b1;
        end else if (i == 5'd17) begin
            done_r <= 1'b0;
        end else begin
            done_r <= 1'b0;
        end
    end
