    if (!rst_n) begin
        areg <= 16'b0;
        breg <= 16'b0;
        yout_r <= 32'b0;
    end else begin
        if (start) begin
            if (i == 5'd0) begin
                areg <= ain;
                breg <= bin;
            end
            if (i >= 5'd1 && i <= 5'd16) begin
                if (areg[i-1]) begin
                    yout_r <= yout_r + (breg << (i-1));
                end
            end
        end
    end
end

