module fixed_point_adder #(
    parameter Q = 4,
    parameter N = 8
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

    reg [N-1:0] abs_a, abs_b;
    reg [N-1:0] res;

    always @(*) begin

        abs_a = a[N-1] ? (~a + 1) : a;
        abs_b = b[N-1] ? (~b + 1) : b;

        if (a[N-1] == b[N-1]) begin

            res = abs_a + abs_b;
        end else begin
            if (abs_a > abs_b) begin

                res = abs_a - abs_b;
            end else begin

                res = abs_b - abs_a;
            end

            res[N-1] = 1'b0;
        end


        c = res;
    end

endmodule

