module fixed_point_subtractor #(
    parameter Q = 4,
    parameter N = 8
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

    reg [N-1:0] res;

    always @(*) begin
        reg sign_a = a[N-1];
        reg sign_b = b[N-1];

        if (sign_a == sign_b) begin

            res = a - b;
        end else begin
            if (sign_a == 1'b0) begin

                reg [N-1:0] abs_b = ~b + 1;
                reg [N-1:0] sum = a + abs_b;
                if (sum == 0)
                    res = 0;
                else if (a > abs_b)
                    res = sum;
                else
                    res = ~sum + 1;
            end else begin

                reg [N-1:0] abs_a = ~a + 1;
                reg [N-1:0] sum = abs_a + b;
                if (sum == 0)
                    res = 0;
                else if (abs_a > b)
                    res = ~sum + 1;
                else
                    res = sum;
            end
        end


        if (res == 0)
            res = 0;
    end

    assign c = res;

endmodule

