reg [8:0] exponent_sum;
reg [7:0] adjusted_exponent;
reg a_is_zero, b_is_zero;
reg a_is_inf, b_is_inf;
reg a_is_nan, b_is_nan;
reg [23:0] rounded_mantissa;

always @(posedge clk) begin
    if (rst) begin
        counter <= 3'b0;
        z <= 32'b0;
        a_mantissa <= 24'b0;
        b_mantissa <= 24'b0;
        a_exponent <= 8'b0;
        b_exponent <= 8'b0;
        a_sign <= 1'b0;
        b_sign <= 1'b0;
        product <= 48'b0;
        guard_bit <= 1'b0;
        round_bit <= 1'b0;
        sticky <= 1'b0;
        exponent_sum <= 9'b0;
        adjusted_exponent <= 8'b0;
        rounded_mantissa <= 24'b0;
    end else begin
        case (counter)
            3'b000: begin 
                a_sign <= a[31];
                b_sign <= b[31];
                a_exponent <= a[30:23];
                b_exponent <= b[30:23];
                a_mantissa <= {1'b1, a[22:0]};
                b_mantissa <= {1'b1, b[22:0]};
                a_is_zero <= (a == 32'b0) || (a_exponent == 8'b0 && a_mantissa == 24'b0);
                b_is_zero <= (b == 32'b0) || (b_exponent == 8'b0 && b_mantissa == 24'b0);
                a_is_inf <= (a_exponent == 8'hff) && (a_mantissa == 24'b0);
                b_is_inf <= (b_exponent == 8'hff) && (b_mantissa == 24'b0);
                a_is_nan <= (a_exponent == 8'hff) && (a_mantissa != 24'b0);
                b_is_nan <= (b_exponent == 8'hff) && (b_mantissa != 24'b0);
                counter <= 3'b001;
            end
            3'b001: begin 
                product <= a_mantissa * b_mantissa;
                counter <= 3'b010;
            end
            3'b010: begin 
                exponent_sum <= a_exponent + b_exponent;

                if (product[47:46] >= 2'b10) begin
                    product <= product >> 1;
                    exponent_sum <= exponent_sum + 9'b1;
                end

                guard_bit <= product[23];
                round_bit <= product[22];
                sticky <= |product[21:0];

                z_mantissa <= product[47:24];
                adjusted_exponent <= exponent_sum[7:0];
                counter <= 3'b011;
            end
            3'b011: begin 

                if (guard_bit && (round_bit || sticky)) begin
                    rounded_mantissa <= z_mantissa + 24'b1;
                end else begin
                    rounded_mantissa <= z_mantissa;
                end

                if (rounded_mantissa[23]) begin
                    rounded_mantissa <= rounded_mantissa >> 1;
                    adjusted_exponent <= adjusted_exponent + 1;
                end
                counter <= 3'b100;
            end
            3'b100: begin 

                if (a_is_nan || b_is_nan) begin
                    z <= {1'b0, 8'hff, 23'h1};
                end else if (a_is_inf || b_is_inf) begin
                    if (a_is_zero || b_is_zero) begin
                        z <= {1'b0, 8'hff, 23'h1};
                    end else begin
                        z <= {a_sign ^ b_sign, 8'hff, 23'b0};
                    end
                end else if (a_is_zero || b_is_zero) begin
                    z <= {a_sign ^ b_sign, 23'b0, 1'b0};
                end else begin
                    z <= {a_sign ^ b_sign, adjusted_exponent, rounded_mantissa[22:0]};
                end
                counter <= 3'b000;
            end
            default: counter <= 3'b000;
        endcase
    end
