integer i;

always @(posedge Clk) begin
    if (Rst) begin
        SP <= 3'd4;
        for (i = 0;
 i < 4;
 i = i + 1) begin
            stack_mem[i] <= 4'b0;
        end
        dataOut <= 4'b0;
    end else if (EN) begin
        if (RW) begin 
            if (SP != 3'd4) begin
                dataOut <= stack_mem[SP];
                stack_mem[SP] <= 4'b0;
                SP <= SP + 1;
            end
        end else begin 
            if (SP != 3'd0) begin
                stack_mem[SP - 1] <= dataIn;
                SP <= SP - 1;
            end
        end
    end
end

always @(*) begin
    EMPTY = (SP == 3'd4);
    FULL = (SP == 3'd0);
end

