module serial2parallel (
    input clk,
    input rst_n,
    input din_serial,
    input din_valid,
    output reg [7:0] dout_parallel,
    output reg dout_valid
);

reg [3:0] cnt;
reg [7:0] data_reg;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        cnt <= 4'd0;
        data_reg <= 8'd0;
        dout_parallel <= 8'd0;
        dout_valid <= 1'd0;
    end else begin
        dout_valid <= 1'd0;
        reg [3:0] next_cnt = cnt;
        reg [7:0] next_data_reg = data_reg;

        if (din_valid) begin
            next_cnt = cnt + 4'd1;
            next_data_reg = {din_serial, data_reg[7:1]};
        end

        if (cnt == 4'd7 && din_valid) begin
            dout_parallel <= next_data_reg;
            dout_valid <= 1'd1;
            next_cnt = 4'd0;
        end

        cnt <= next_cnt;
        data_reg <= next_data_reg;
    end
end

endmodule

