module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [15:0] SR;
reg [3:0] cnt;
reg start_cnt;
reg [7:0] dividend_abs, divisor_abs;
reg [8:0] NEG_DIVISOR;
reg [15:0] result_reg;
reg sign_dividend, sign_divisor;

always @(*) begin
    dividend_abs = sign ? (dividend[7] ? -dividend : dividend) : dividend;
    divisor_abs = sign ? (divisor[7] ? -divisor : divisor) : divisor;
    NEG_DIVISOR = -{1'b0, divisor_abs};
end

always @(posedge clk) begin
    if (rst) begin
        res_valid <= 0;
        result <= 0;
        SR <= 0;
        cnt <= 0;
        start_cnt <= 0;
        dividend_abs <= 0;
        divisor_abs <= 0;
        NEG_DIVISOR <= 0;
        result_reg <= 0;
        sign_dividend <= 0;
        sign_divisor <= 0;
    end else begin
        if (opn_valid && !res_valid) begin
            dividend_abs <= sign ? (dividend[7] ? -dividend : dividend) : dividend;
            divisor_abs <= sign ? (divisor[7] ? -divisor : divisor) : divisor;
            sign_dividend <= sign && dividend[7];
            sign_divisor <= sign && divisor[7];
            SR <= {dividend_abs, 1'b0} << 1;
            NEG_DIVISOR <= -{1'b0, divisor_abs};
            cnt <= 1;
            start_cnt <= 1;
            res_valid <= 0;
            result_reg <= 0;
        end else if (start_cnt) begin
            if (cnt < 8) begin
                reg [8:0] sub_res = SR[15:7] - NEG_DIVISOR;
                if (sub_res[8] == 0) begin
                    SR[15:7] <= sub_res[7:0];
                    SR[6:0] <= {1'b1, SR[6:1]};
                end else begin
                    SR[6:0] <= {1'b0, SR[6:1]};
                end
                SR <= SR << 1;
                cnt <= cnt + 1;
            end else begin
                start_cnt <= 0;
                res_valid <= 1;
                result_reg <= {SR[15:8], SR[7:0]};
            end
        end
        if (opn_valid && res_valid) begin
            res_valid <= 0;
        end
    end
end

assign result = result_reg;

endmodule

