  assign G[1] = A[1] & B[1];
  assign P[1] = A[1] ^ B[1];

  assign C[2] = G[1] | (P[1] & C[1]);
  assign S[2] = A[2] ^ B[2] ^ C[2];
  assign G[2] = A[2] & B[2];
