module fixed_point_subtractor #(
    parameter Q = 4,
    parameter N = 8
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

    reg [N-1:0] res;
    reg [N-2:0] mag_diff;
    reg new_sign;

    always @(*) begin
        if (a[N-1] == b[N-1]) begin
            if (a[N-2:0] > b[N-2:0]) begin
                mag_diff = a[N-2:0] - b[N-2:0];
                new_sign = a[N-1];
            end else if (b[N-2:0] > a[N-2:0]) begin
                mag_diff = b[N-2:0] - a[N-2:0];
                new_sign = ~a[N-1];
            end else begin
                mag_diff = 0;
                new_sign = 1'b0;
            end
        end else begin
            if (a[N-1] == 1'b0) begin 
                if (a[N-2:0] >= b[N-2:0]) begin
                    mag_diff = a[N-2:0] - b[N-2:0];
                    new_sign = 1'b0;
                end else begin
                    mag_diff = b[N-2:0] - a[N-2:0];
                    new_sign = 1'b1;
                end
            end else begin 
                if (a[N-2:0] >= b[N-2:0]) begin
                    mag_diff = a[N-2:0] - b[N-2:0];
                    new_sign = 1'b1;
                end else begin
                    mag_diff = b[N-2:0] - a[N-2:0];
                    new_sign = 1'b0;
                end
            end
        end

        if (mag_diff == 0) begin
            res = {1'b0, {(N-2){1'b0}}};
        end else begin
            res = {new_sign, mag_diff};
        end
    end

    assign c = res;

endmodule

