module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg [31:0] a_reg, b_reg, z_reg;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent, z_exponent;
    reg [22:0] a_mantissa, b_mantissa, z_mantissa;
    reg [48:0] product;
    reg guard_bit, round_bit, sticky;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'b0;
        end else begin
            case (counter)
                3'b000: begin
                    a_reg <= a;
                    b_reg <= b;
                    z <= 32'b0;
                    counter <= 3'b001;
                end
                3'b001: begin

                    a_sign <= a_reg[31];
                    b_sign <= b_reg[31];
                    z_sign <= a_reg[31] ^ b_reg[31];


                    if (a_reg[30:23] == 8'hff || b_reg[30:23] == 8'hff) begin
                        if ((a_reg[30:23] == 8'hff && |a_reg[22:0]) || 
                            (b_reg[30:23] == 8'hff && |b_reg[22:0])) begin
                            z <= 32'h7fc00000;

                        end else if ((a_reg[30:23] == 8'hff) ^ (b_reg[30:23] == 8'hff)) begin
                            z <= {z_sign, 8'hff, 23'd0};

                        end else begin
                            z <= {z_sign, 8'd0, 23'd0};

                        end
                        counter <= 3'b111;
                    end else if (a_reg[30:23] == 8'd0 && |a_reg[22:0]) begin

                        if (b_reg[30:23] == 8'd0 && |b_reg[22:0]) begin
                            z <= {z_sign, 8'd0, 23'd0};

                        end else begin
                            z <= {z_sign, b_reg[30:23] - 8'd1, b_reg[22:0]};

                        end
                        counter <= 3'b111;
                    end else if (b_reg[30:23] == 8'd0 && |b_reg[22:0]) begin

                        if (a_reg[30:23] == 8'd0 && |a_reg[22:0]) begin
                            z <= {z_sign, 8'd0, 23'd0};

                        end else begin
                            z <= {z_sign, a_reg[30:23] - 8'd1, a_reg[22:0]};

                        end
                        counter <= 3'b111;
                    end else begin

                        a_mantissa <= (a_reg[30:23] == 8'd0) ? {1'b0, a_reg[22:0]} : {1'b1, a_reg[22:0]};
                        b_mantissa <= (b_reg[30:23] == 8'd0) ? {1'b0, b_reg[22:0]} : {1'b1, b_reg[22:0]};
                        product <= a_mantissa * b_mantissa;
                        a_exponent <= a_reg[30:23];
                        b_exponent <= b_reg[30:23];
                        counter <= 3'b010;
                    end
                end
                3'b010: begin

                    if (product[48]) begin
                        product = product >> 1;
                        z_exponent <= a_exponent + b_exponent - 8'd127 + 8'd1;
                    end else if (product[47]) begin
                        product = product >> 1;
                        z_exponent <= a_exponent + b_exponent - 8'd127 + 8'd1;
                    end else begin
                        z_exponent <= a_exponent + b_exponent - 8'd127;
                    end

                    guard_bit <= product[22];
                    round_bit <= product[21];
                    sticky <= |product[20:0];
                    z_mantissa <= product[46:24];
                    counter <= 3'b011;
                end
                3'b011: begin

                    if (guard_bit && (round_bit || sticky)) begin
                        z_mantissa <= z_mantissa + 1;
                        if (z_mantissa == 23'h7fffff) begin
                            z_mantissa <= 23'd0;
                            z_exponent <= z_exponent + 8'd1;
                        end
                    end

                    if (z_exponent >= 8'hff) begin
                        z <= {z_sign, 8'hff, 23'd0};

                    end else if (z_exponent <= 8'd0) begin
                        z <= {z_sign, 31'd0};

                    end else begin
                        z <= {z_sign, z_exponent, z_mantissa};
                    end
                    counter <= 3'b000;
                end
                default: counter <= 3'b000;
            endcase
        end
    end

endmodule

