    output wfull,
    input rclk,
    input rrstn,
    input rinc,
    output rempty,
    output [WIDTH-1:0] rdata
);

    localparam ADDR_WIDTH = $clog2(DEPTH);

    wire wen, ren;
    reg [ADDR_WIDTH-1:0] waddr_bin, raddr_bin;

    dual_port_RAM #(
        .WIDTH(WIDTH),
        .DEPTH(DEPTH)
    ) ram (
        .wclk(wclk),
        .wenc(wen),
        .waddr(waddr_bin),
        .wdata(wdata),
        .rclk(rclk),
        .renc(ren),
        .raddr(raddr_bin),
        .rdata(rdata)
    );

    reg [ADDR_WIDTH-1:0] wptr_gray, rptr_gray;
    reg [ADDR_WIDTH-1:0] wptr_gray_sync1, wptr_gray_sync2;
    reg [ADDR_WIDTH-1:0] rptr_gray_sync1, rptr_gray_sync2;

    wire [ADDR_WIDTH-1:0] wptr_bin_sync = gray2bin(rptr_gray_sync2);
    wire [ADDR_WIDTH-1:0] rptr_bin_sync = gray2bin(wptr_gray_sync2);

    assign wfull = (waddr_bin[ADDR_WIDTH-1] != rptr_bin_sync[ADDR_WIDTH-1]) &&
                   (waddr_bin[ADDR_WIDTH-2:0] == rptr_bin_sync[ADDR_WIDTH-2:0]);
    assign rempty = (raddr_bin == wptr_bin_sync);
    assign wen = winc && !wfull;
    assign ren = rinc && !rempty;

    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) waddr_bin <= 0;
        else if (wen) waddr_bin <= waddr_bin + 1;
    end

    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) raddr_bin <= 0;
        else if (ren) raddr_bin <= raddr_bin + 1;
    end

    function [ADDR_WIDTH-1:0] bin2gray(input [ADDR_WIDTH-1:0] bin);
        bin2gray = bin ^ (bin >> 1);
    endfunction

    function [ADDR_WIDTH-1:0] gray2bin(input [ADDR_WIDTH-1:0] gray);
        reg [ADDR_WIDTH-1:0] bin;
        integer i;
        begin
            bin[ADDR_WIDTH-1] = gray[ADDR_WIDTH-1];
            for (i = ADDR_WIDTH-2;
 i >= 0;
 i = i - 1)
                bin[i] = bin[i+1] ^ gray[i];
            gray2bin = bin;
        end
    endfunction

    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            rptr_gray_sync1 <= 0;
            rptr_gray_sync2 <= 0;
        end else begin
            rptr_gray_sync1 <= rptr_gray;
            rptr_gray_sync2 <= rptr_gray_sync1;
        end
    end

    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            wptr_gray_sync1 <= 0;
            wptr_gray_sync2 <= 0;
        end else begin
            wptr_gray_sync1 <= wptr_gray;
            wptr_gray_sync2 <= wptr_gray_sync1;
        end
    end

    assign wptr_gray = bin2gray(waddr_bin);
    assign rptr_gray = bin2gray(raddr_bin);

