    input clk,
    input pass_request,
    output [7:0] clock,
    output red,
    output yellow,
    output green
);


localparam [1:0] idle = 2'b00,
                 s1_red = 2'b01,
                 s2_yellow = 2'b10,
                 s3_green = 2'b11;


