module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [7:0] abs_dividend, abs_divisor;
    reg [7:0] div_sign, divisor_sign;
    reg [15:0] SR;
    reg [3:0] cnt;
    reg start_cnt;
    reg [7:0] NEG_DIVISOR;
    reg [1:0] state;

    localparam IDLE = 2'b00;
    localparam RUN = 2'b01;
    localparam ADJUST = 2'b10;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            state <= IDLE;
            cnt <= 0;
            start_cnt <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (opn_valid && !res_valid) begin

                        abs_dividend <= sign ? (dividend[7] ? -dividend : dividend) : dividend;
                        div_sign <= sign ? {8{dividend[7]}} : 8'b0;
                        abs_divisor <= sign ? (divisor[7] ? -divisor : divisor) : divisor;
                        divisor_sign <= sign ? {8{divisor[7]}} : 8'b0;
                        NEG_DIVISOR <= -(sign ? (divisor[7] ? -divisor : divisor) : divisor);

                        SR <= {abs_dividend, 8'b0} << 1;
                        cnt <= 1;
                        start_cnt <= 1;
                        state <= RUN;
                        res_valid <= 0;
                    end
                end
                RUN: begin
                    if (start_cnt) begin
                        if (cnt == 8) begin

                            start_cnt <= 0;
                            cnt <= 0;
                            state <= ADJUST;
                        end else begin

                            if (SR[15:8] >= NEG_DIVISOR) begin
                                SR[15:8] <= SR[15:8] - NEG_DIVISOR;
                                SR <= {SR[14:8], 1'b1, SR[7:0] << 1};
                            end else begin
                                SR <= {SR[14:8], 1'b0, SR[7:0] << 1};
                            end
                            cnt <= cnt + 1;
                        end
                    end
                end
                ADJUST: begin

                    reg [7:0] quo = SR[7:0];
                    reg [7:0] rem = SR[15:8];
                    if (sign) begin
                        quo = (div_sign[0] ^ divisor_sign[0]) ? -quo : quo;
                        rem = div_sign[0] ? -rem : rem;
                    end
                    result <= {rem, quo};
                    res_valid <= 1;
                    state <= IDLE;
                end
                default: state <= IDLE;
            endcase
        end
    end

endmodule

