module div_16bit (
    input  [15:0] A,
    input  [7:0]  B,
    output [15:0] result,
    output [15:0] odd
);

    reg [15:0] a_reg;
    reg [7:0]  b_reg;
    reg [15:0] quotient;
    reg [7:0]  remainder;


    always @(*) begin
        a_reg = A;
        b_reg = B;
    end

    always @(*) begin
        integer i;
        reg [15:0] dividend;
        reg [7:0]  rem;

        dividend = a_reg;
        rem = 8'b0;

        for (i = 15;
 i >= 0;
 i = i - 1) begin
            rem = (rem << 1) | ((dividend >> i) & 1'b1);
            if (rem >= b_reg) begin
                rem = rem - b_reg;
                quotient[i] = 1'b1;
            end
        end

        result = quotient;
        odd = {8'b0, rem};
    end

endmodule

