                        a_pipe[i] <= a_pipe[i-1];
                        b_pipe[i] <= b_pipe[i-1];
                    end
                end
            end
        end
    endgenerate

    generate
        for (i=0;
 i<8;
 i=i+1) begin : PARTIAL
