            sum2_0 <= 16'b0;
            sum2_1 <= 16'b0;
            sum3 <= 16'b0;
        end else begin
            sum1_0 <= temp[0] + temp[1];
            sum1_1 <= temp[2] + temp[3];
            sum1_2 <= temp[4] + temp[5];
            sum1_3 <= temp[6] + temp[7];

            sum2_0 <= sum1_0 + sum1_1;
            sum2_1 <= sum1_2 + sum1_3;

            sum3 <= sum2_0 + sum2_1;
        end
    end


    reg [15:0] mul_out_reg;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            mul_out_reg <= 16'b0;
        end else if (mul_en_out) begin
            mul_out_reg <= sum3;
