module accu (
    input clk,
    input rst_n,
    input [7:0] data_in,
    input valid_in,
    output reg [9:0] data_out,
    output reg valid_out
);

reg [9:0] sum_reg;
reg [2:0] count_reg;

wire [9:0] next_sum = valid_in ? sum_reg + data_in : sum_reg;
wire [2:0] next_count = valid_in ? count_reg + 1 : count_reg;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        sum_reg <= 10'b0;
        count_reg <= 3'b0;
        data_out <= 10'b0;
        valid_out <= 1'b0;
    end else begin
        if (next_count == 4) begin
            data_out <= next_sum;
            valid_out <= 1'b1;
            sum_reg <= 10'b0;
            count_reg <= 3'b0;
        end else begin
            sum_reg <= next_sum;
            count_reg <= next_count;
            valid_out <= 1'b0;
        end
    end
end

endmodule

