module fixed_point_adder #(
    parameter Q = 3,
    parameter N = 8
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);

reg [N-1:0] res;
wire sign_a = a[N-1];
wire sign_b = b[N-1];
wire [N-2:0] mag_a = a[N-2:0];
wire [N-2:0] mag_b = b[N-2:0];
reg [N-1:0] sum;
reg res_sign;
reg [N-1:0] res_abs;

always @(*) begin
    if (sign_a == sign_b) begin
        sum = {1'b0, mag_a} + {1'b0, mag_b};

        res_sign = sum[N-1];

        res_abs = sum[N-2:0];

    end else begin
        if (mag_a > mag_b) begin
            res_sign = sign_a;
            res_abs = mag_a - mag_b;
        end else if (mag_b > mag_a) begin
            res_sign = sign_b;
            res_abs = mag_b - mag_a;
        end else begin
            res_sign = 0;
            res_abs = 0;
        end
    end
    res = {res_sign, res_abs};
end

assign c = res;

endmodule

