module fixed_point_subtractor #(
    parameter Q = 8,
    parameter N = 16
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);

    reg [N-1:0] res;
    wire sign_a = a[N-1];
    wire sign_b = b[N-1];
    wire same_sign = (sign_a == sign_b);


    wire [N-1:0] a_abs = (sign_a) ? (~a + 1) : a;
    wire [N-1:0] b_abs = (sign_b) ? (~b + 1) : b;

    wire [N-1:0] sum_abs = a_abs + b_abs;
    wire a_gt_b = ($signed(a) > $signed(b));

    always @(*) begin
        if (same_sign) begin
            res = a - b;
        end else begin
            res = sum_abs;
            res[N-1] = a_gt_b ? 1'b0 : 1'b1;
        end


        if (res == 0) begin
            res[N-1] = 1'b0;
        end

        c = res;
    end

endmodule

