module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

reg [2:0] counter;
reg a_sign, b_sign;
reg [7:0] a_exponent, b_exponent;
reg [23:0] a_mantissa, b_mantissa;
reg [47:0] product;
reg guard, round, sticky;
reg [7:0] z_exponent;
reg [22:0] z_mantissa;

always @(posedge clk) begin
    if (rst) begin
        counter <= 3'b0;
        z <= 32'b0;
    end else begin
        case (counter)
            3'b000: begin

                a_sign <= a[31];
                b_sign <= b[31];
                a_exponent <= a[30:23];
                b_exponent <= b[30:23];
                a_mantissa <= (a[30:23] != 0) ? {1'b1, a[22:0]} : {1'b0, a[22:0]};
                b_mantissa <= (b[30:23] != 0) ? {1'b1, b[22:0]} : {1'b0, b[22:0]};
                counter <= counter + 1;
            end
            3'b001: begin

                if (a[30:23] == 8'hff && a[22:0] != 0) || (b[30:23] == 8'hff && b[22:0] != 0)) begin

                    z <= {1'b0, 8'hff, 23'h1};
                end else if ((a[30:23] == 8'hff && a[22:0] == 0) || (b[30:23] == 8'hff && b[22:0] == 0)) begin

                    if ((a[30:23] == 8'hff && a[22:0] == 0) && (b[30:23] == 8'hff && b[22:0] == 0)) begin

                        z <= {a_sign ^ b_sign, 8'hff, 23'b0};
                    end else if ((a[30:23] == 8'hff && a[22:0] == 0)) begin

                        z <= {a_sign ^ b_sign, 8'hff, 23'b0};
                    end else begin

                        z <= {a_sign ^ b_sign, 8'hff, 23'b0};
                    end
                end else if (a[30:23] == 0 && a_mantissa == 0 && b[30:23] == 0 && b_mantissa == 0) begin

                    z <= {a_sign ^ b_sign, 8'b0, 23'b0};
                end else if (a[30:23] == 0 && a_mantissa == 0) begin

                    z <= {a_sign ^ b_sign, 8'b0, 23'b0};
                end else if (b[30:23] == 0 && b_mantissa == 0) begin

                    z <= {a_sign ^ b_sign, 8'b0, 23'b0};
                end else begin

                    product <= a_mantissa * b_mantissa;
                    counter <= counter + 1;
                end
            end
            3'b010: begin

                if (product[47:46] >= 2'd2) begin
                    product <= product >> 1;
                    z_exponent <= a_exponent + b_exponent - 8'd127 + 8'd1;
                end else begin
                    z_exponent <= a_exponent + b_exponent - 8'd127;
                end

                z_mantissa <= product[46:24];


                guard <= product[23];
                round <= product[22];
                sticky <= |product[21:0];
                counter <= counter + 1;
            end
            3'b011: begin

                reg round_up;
                round_up = (guard && (round || sticky)) || (guard && !round && z_mantissa[0]);
                if (round_up) begin
                    z_mantissa = z_mantissa + 1;
                    if (z_mantissa == 23'h7fffff) begin
                        z_exponent = z_exponent + 1;
                        z_mantissa = 23'b0;
                    end
                end

                if (z_exponent >= 8'hff) begin
                    z <= {a_sign ^ b_sign, 8'hff, 23'b0};
                end else if (z_exponent == 0) begin
                    z <= {a_sign ^ b_sign, 8'b0, z_mantissa};
                end else begin
                    z <= {a_sign ^ b_sign, z_exponent, z_mantissa};
                end
                counter <= 3'b000;
            end
            default: counter <= 3'b000;
        endcase
    end
