module fsm (
    input IN,
    input CLK,
    input RST,
    output reg MATCH
);

parameter S0 = 3'b000;
parameter S1 = 3'b001;
parameter S2 = 3'b010;
parameter S3 = 3'b011;
parameter S4 = 3'b100;
parameter S5 = 3'b101;

reg [2:0] state_reg, state_next;


always @(posedge CLK or posedge RST) begin
    if (RST)
        state_reg <= S0;
    else
        state_reg <= state_next;
end


always @(*) begin
    case (state_reg)
        S0: state_next = IN ? S1 : S0;
        S1: state_next = IN ? S1 : S2;
        S2: state_next = IN ? S1 : S3;
        S3: state_next = IN ? S4 : S0;
        S4: state_next = IN ? S5 : S0;
        S5: state_next = IN ? S1 : S0;
        default: state_next = S0;
    endcase
end


always @(*) begin
    if (RST)
        MATCH = 1'b0;
    else
        MATCH = (state_reg == S5) && IN;
end

