module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);


    parameter idle = 2'b00;
    parameter s1_red = 2'b01;
    parameter s2_yellow = 2'b10;
    parameter s3_green = 2'b11;

    reg [1:0] state;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
        end else begin
            case (state)
                idle: state <= s1_red;
                s1_red: state <= (cnt == 3) ? s3_green : s1_red;
                s3_green: state <= (cnt == 3) ? s2_yellow : s3_green;
                s2_yellow: state <= (cnt == 3) ? s1_red : s2_yellow;
                default: state <= idle;
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 10;
        end else begin
            if (state == s3_green && pass_request && green)
                cnt <= (cnt > 10) ? 10 : cnt;
            else case (state)
                s1_red: cnt <= 60;
                s3_green: cnt <= 60;
                s2_yellow: cnt <= 5;
                default: cnt <= 10;
            endcase
            if (cnt != 0)
                cnt <= cnt - 1;
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            {p_red, p_yellow, p_green} <= 3'b0;
        end else begin
            {p_red, p_yellow, p_green} <= 3'b0;
            if (state != idle) begin
                case (state)
                    s1_red: p_red <= 1;
                    s2_yellow: p_yellow <= 1;
                    s3_green: p_green <= 1;
                    default: ;
                endcase
            end
        end
    end

    assign clock = cnt;
    assign {red, yellow, green} = {p_red, p_yellow, p_green};

endmodule

