always @(*) begin
    a_reg = A;
    b_reg = B;
end

always @(*) begin
    reg [7:0] rem = 8'b0;
    reg [15:0] res = 16'b0;
    integer i;

    for (i = 15;
 i >= 0;
 i = i - 1) begin
        rem = {rem[6:0], a_reg[i]};
        if (rem >= b_reg) begin
            res[i] = 1'b1;
            rem = rem - b_reg;
        end else begin
            res[i] = 1'b0;
        end
    end
    result = res;
    odd = {8'b0, rem};
end

endmodule

