    assign carry[1] = G_bits[0] | (P_bits[0] & Cin);

    cla_1bit cla1 (A[1], B[1], carry[1], S[1], G_bits[1], P_bits[1]);
    assign carry[2] = G_bits[1] | (P_bits[1] & carry[1]);

