module accu (
    input clk,
    input rst_n,
    input [7:0] data_in,
    input valid_in,
    output reg valid_out,
    output reg [9:0] data_out
);

reg [1:0] count;
reg [9:0] sum_accumulator;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        sum_accumulator <= 10'b0;
        count <= 2'b0;
        data_out <= 10'b0;
        valid_out <= 1'b0;
    end else begin

        if (valid_in) begin
            sum_accumulator <= sum_accumulator + data_in;
            count <= count + 1;
        end else begin
            sum_accumulator <= sum_accumulator;
            count <= count;
        end


        if (valid_in && (count == 2'b11)) begin
            data_out <= sum_accumulator + data_in;
            valid_out <= 1'b1;
        end else begin
            data_out <= data_out;
            valid_out <= 1'b0;
        end
    end
end

endmodule

