module fixed_point_adder #(
    parameter Q = 8,  
    parameter N = 16   
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

    reg [N-2:0] mag_a, mag_b;
    reg sign_a, sign_b;
    reg [N-1:0] res;

    always @(*) begin
        sign_a = a[N-1];
        sign_b = b[N-1];
        mag_a = a[N-2:0];
        mag_b = b[N-2:0];

        if (sign_a == sign_b) begin

            res = {sign_a, (mag_a + mag_b)[N-2:0]};
        end else begin

            if (mag_a > mag_b) begin
                res = {1'b0, mag_a - mag_b};
            end else if (mag_b > mag_a) begin
                res = {1'b1, mag_b - mag_a};
            end else begin
                res = {1'b0, {(N-2){1'b0}}};

            end
        end
    end

    assign c = res;

endmodule

