module fixed_point_subtractor #(
    parameter Q = 4,  
    parameter N = 8   
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

    reg [N-1:0] res;

    always @(*) begin
        reg [N-1:0] a_abs, b_abs;
        reg a_neg, b_neg;
        reg [N-2:0] a_mag, b_mag;

        a_neg = a[N-1];
        b_neg = b[N-1];
        a_mag = a[N-2:0];
        b_mag = b[N-2:0];


        a_abs = a_neg ? (~a + 1) : a;
        b_abs = b_neg ? (~b + 1) : b;

        if (a[N-1] == b[N-1]) begin

            res = a_abs - b_abs;
            res[N-1] = a[N-1];

        end else begin

            if (a_abs >= b_abs) begin
                res = a_abs - b_abs;
                res[N-1] = 1'b0;

            end else begin
                res = b_abs - a_abs;
                res[N-1] = 1'b1;

            end
        end


        if (res == 0) begin
            res[N-1] = 1'b0;
        end

        c = res;
    end

endmodule

