module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

reg [2:0] counter;
reg a_sign, b_sign;
reg [7:0] a_exponent, b_exponent;
reg [22:0] a_mantissa, b_mantissa;
reg [47:0] product;
reg [47:0] product_shifted;
reg guard, round, sticky;
reg [7:0] exp_initial, exp_adjust, exp_adjust_round;
reg [7:0] final_exponent;
reg [22:0] rounded_mantissa, mantissa;
reg sign;

wire a_is_nan = (a_exponent == 8'hFF) && (a_mantissa != 0);
wire b_is_nan = (b_exponent == 8'hFF) && (b_mantissa != 0);
wire a_is_inf = (a_exponent == 8'hFF) && (a_mantissa == 0);
wire b_is_inf = (b_exponent == 8'hFF) && (b_mantissa == 0);
wire a_is_zero = (a_exponent == 0) && (a_mantissa == 0);
wire b_is_zero = (b_exponent == 0) && (b_mantissa == 0);

always @(posedge clk) begin
    if (rst) begin
        counter <= 3'b0;
        z <= 32'b0;
        exp_initial <= 8'd0;
        exp_adjust <= 8'd0;
        exp_adjust_round <= 8'd0;
        final_exponent <= 8'd0;
        rounded_mantissa <= 23'd0;
        mantissa <= 23'd0;
        sign <= 1'b0;
    end else begin
        case (counter)
            3'b000: begin 
                a_sign <= a[31];
                b_sign <= b[31];
                a_exponent <= a[30:23];
                b_exponent <= b[30:23];
                a_mantissa <= (a[30:23] != 0) ? {1'b1, a[22:0]} : {1'b0, a[22:0]};
                b_mantissa <= (b[30:23] != 0) ? {1'b1, b[22:0]} : {1'b0, b[22:0]};
                counter <= 3'b001;
            end
            3'b001: begin 
                if (a_is_nan || b_is_nan) begin
                    z <= 32'h7FC00000;

                end else if ((a_is_inf && b_is_zero) || (b_is_inf && a_is_zero)) begin
                    z <= 32'h7FC00000;

                end else if (a_is_inf || b_is_inf) begin
                    z <= {a_sign ^ b_sign, 8'hFF, 23'd0};

                end else if (a_is_zero || b_is_zero) begin
                    z <= {a_sign ^ b_sign, 31'd0};

                end else begin
                    exp_initial <= a_exponent + b_exponent - 8'd127;
                    counter <= 3'b010;
                end
            end
            3'b010: begin 
                product <= {a_mantissa, 24'd0} * {b_mantissa, 24'd0};

                counter <= 3'b011;
            end
            3'b011: begin 
                product_shifted <= product;
                exp_adjust <= 8'd0;
                if (product[47]) begin
                    product_shifted <= product >> 1;
                    exp_adjust <= 8'd1;
                end
                counter <= 3'b100;
            end
            3'b100: begin 
                guard <= product_shifted[23];
                round <= product_shifted[22];
                sticky <= |product_shifted[21:0];
                exp_adjust_round <= 8'd0;
                rounded_mantissa <= product_shifted[46:24];
                if (guard) begin
                    if (round || sticky) begin
                        exp_adjust_round <= 8'd1;
                        rounded_mantissa <= product_shifted[46:24] + 23'd1;
                    end else begin
                        rounded_mantissa <= product_shifted[46:24];
                    end
                end
                counter <= 3'b101;
            end
            3'b101: begin 
                sign <= a_sign ^ b_sign;
                final_exponent <= exp_initial + exp_adjust + exp_adjust_round;
                if (rounded_mantissa[23]) begin 
                    final_exponent <= final_exponent + 8'd1;
                    mantissa <= rounded_mantissa[22:0] + 23'd1;
                end else begin
                    mantissa <= rounded_mantissa[22:0];
                end
                if (final_exponent[8]) begin 
                    z <= {sign, 8'hFF, 23'd0};
                end else if (final_exponent == 8'd0) begin 
                    z <= {sign, 23'd0, mantissa[22:1]};
                end else begin
                    z <= {sign, final_exponent[7:0], mantissa};
                end
                counter <= 3'b000;
            end
        endcase
    end
end

endmodule

