module LIFObuffer (
    input wire [3:0] dataIn,
    input wire RW,
    input wire EN,
    input wire Rst,
    input wire Clk,
    output wire EMPTY,
    output wire FULL,
    output wire [3:0] dataOut
);

reg [3:0] stack_mem [0:3];
reg [2:0] SP;

reg [3:0] dataOut_reg;

assign EMPTY = (SP == 4);
assign FULL = (SP == 0);
assign dataOut = dataOut_reg;

always @(posedge Clk) begin
    if (Rst) begin

        stack_mem[0] <= 4'b0;
        stack_mem[1] <= 4'b0;
        stack_mem[2] <= 4'b0;
        stack_mem[3] <= 4'b0;
        SP <= 3'd4;
        dataOut_reg <= 4'b0;
    end else if (EN) begin
        if (!FULL && !RW) begin  
            stack_mem[SP - 1] <= dataIn;
            SP <= SP - 1;
        end else if (!EMPTY && RW) begin  
            dataOut_reg <= stack_mem[SP - 1];
            stack_mem[SP - 1] <= 4'b0;
            SP <= SP + 1;
        end
    end
end

endmodule

