module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output data_out
);

    reg [1:0] state;
    parameter IDLE = 2'b00;
    parameter S0 = 2'b01;
    parameter S1 = 2'b10;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            state <= IDLE;
        end else begin
            case (state)
                IDLE: state <= (data_in) ? IDLE : S0;
                S0:   state <= (data_in) ? S1 : IDLE;
                S1:   state <= IDLE;
                default: state <= IDLE;
            endcase
        end
    end

    assign data_out = (state == S1) && !data_in;

endmodule

