module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output [7:0] clock,
    output red,
    output yellow,
    output green
);

    parameter idle = 2'b00;
    parameter s1_red = 2'b01;
    parameter s2_yellow = 2'b10;
    parameter s3_green = 2'b11;

    reg [7:0] cnt;
    reg [1:0] state;
    reg p_red, p_yellow, p_green;

    wire [1:0] next_state;


    always @(*) begin
        case (state)
            idle: begin
                p_red = 0;
                p_yellow = 0;
                p_green = 0;
                next_state = s1_red;
            end
            s1_red: begin
                p_red = 1;
                p_yellow = 0;
                p_green = 0;
                next_state = (cnt == 0) ? s3_green : s1_red;
            end
            s2_yellow: begin
                p_red = 0;
                p_yellow = 1;
                p_green = 0;
                next_state = (cnt == 0) ? s1_red : s2_yellow;
            end
            s3_green: begin
                p_red = 0;
                p_yellow = 0;
                p_green = 1;
                next_state = (cnt == 0) ? s2_yellow : s3_green;
            end
            default: begin
                p_red = 0;
                p_yellow = 0;
                p_green = 0;
                next_state = idle;
            end
        endcase
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            state <= idle;
        else
            state <= next_state;
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            cnt <= 8'd10;
        else begin
            if (pass_request && p_green)
                cnt <= 8'd10;
            else if (!p_red && p_green)
                cnt <= 8'd60;
            else if (!p_yellow && p_yellow)
                cnt <= 8'd5;
            else if (!p_red && p_red)
                cnt <= 8'd10;
            else
                cnt <= cnt - 1;
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            red <= 0;
            yellow <= 0;
            green <= 0;
        end else begin
            red <= p_red;
            yellow <= p_yellow;
            green <= p_green;
        end
    end

    assign clock = cnt;

endmodule

