module cla_16bit (
    input [16:1] A,
    input [16:1] B,
    input carry_in,
    output [16:1] S,
    output P,
    output G,
    output carry_out
);
    wire [16:1] P_bits, G_bits;
    wire [16:1] carry;

    assign carry[1] = carry_in;

    genvar i;
    generate
        for (i = 1;
 i <= 16;
 i = i + 1) begin : cla_gen
            assign P_bits[i] = A[i] ^ B[i];
            assign G_bits[i] = A[i] & B[i];
            assign carry[i] = G_bits[i] | (P_bits[i] & carry[i-1]);
            assign S[i] = P_bits[i] ^ carry[i];
        end
    endgenerate

    assign P = &P_bits;
    wire [16:1] G_partial;
    assign G_partial[1] = G_bits[1];
    genvar j;
    generate
        for (j = 2;
 j <= 16;
 j = j + 1) begin : g_partial
            assign G_partial[j] = G_bits[j] | (P_bits[j] & G_partial[j-1]);
        end
    endgenerate
    assign G = G_partial[16];
    assign carry_out = G | (P & carry_in);
endmodule

