module accu (
    input clk,
    input rst_n,
    input [7:0] data_in,
    input valid_in,
    output reg valid_out,
    output [9:0] data_out
);

reg [9:0] sum;
reg [2:0] count;
reg [9:0] data_out_reg;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        sum <= 10'b0;
        count <= 3'b0;
        valid_out <= 1'b0;
        data_out_reg <= 10'b0;
    end else begin
        valid_out <= 1'b0;
        data_out_reg <= 10'b0;

        if (valid_in) begin
            sum <= sum + data_in;
            count <= count + 1;
        end

        if (valid_in && (count == 3'd3)) begin
            data_out_reg <= sum + data_in;
            valid_out <= 1'b1;
            sum <= 10'b0;
            count <= 3'b0;
        end
    end
end

assign data_out = data_out_reg;

endmodule

