module fixed_point_adder #(
    parameter Q = 3,   
    parameter N = 4    
) (
    input  [N-1:0] a,
    input  [N-1:0] b,
    output [N-1:0] c
);

reg [N-1:0] res;

always @(*) begin
    reg sign_a, sign_b;
    reg [N-1:0] a_mag, b_mag;
    reg [N-2:0] difference_mag;
    reg sign_result;
    reg [N-2:0] magnitude;

    sign_a = a[N-1];
    sign_b = b[N-1];


    a_mag = sign_a ? (~a + 1) : a;
    b_mag = sign_b ? (~b + 1) : b;


    if (sign_a == sign_b) begin
        reg [N-1:0] sum;
        sum = a_mag + b_mag;
        res = {sign_a, sum[N-2:0]};
    end

    else begin
        if (a_mag > b_mag) begin
            difference_mag = a_mag - b_mag;
            sign_result = sign_a;
        end else if (b_mag > a_mag) begin
            difference_mag = b_mag - a_mag;
            sign_result = sign_b;
        end else begin
            difference_mag = 0;
            sign_result = 0;
        end


        if (sign_result) begin
            magnitude = ~difference_mag + 1;
        end else begin
            magnitude = difference_mag;
        end

        res = {sign_result, magnitude};
    end
end

assign c = res;

endmodule

