wire sign_a = a[N-1];
wire sign_b = b[N-1];

always @(*) begin
    reg [N-1:0] a_mag, b_mag;
    reg [N:0] sum_abs;

    reg sign_res;
    reg [N-1:0] temp_res;

    if (sign_a == sign_b) begin

        temp_res = a - b;
        sign_res = sign_a;
