        a_mag = sign_a ? (-a) : a;
        b_mag = sign_b ? (-b) : b;
        sum_abs = a_mag + b_mag;
        sign_res = a_mag > b_mag ? sign_a : ~sign_a;
        temp_res = {sign_res, sum_abs[N-1:0]};
    end


    if (temp_res == 0) begin
        res = {1'b0, temp_res[N-2:0]};
    end else begin
        res = temp_res;
    end

    c = res;
end

endmodule

