module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

reg [2:0] counter;
reg a_sign, b_sign, z_sign;
reg [7:0] a_exponent, b_exponent, z_exponent;
reg [22:0] a_mantissa, b_mantissa;
reg [49:0] product;
reg guard_bit, round_bit, sticky;
reg [22:0] z_mantissa;
reg [7:0] adjusted_exponent;

wire a_is_nan = (a_exponent == 8'hFF) && (a_mantissa != 23'b0);
wire b_is_nan = (b_exponent == 8'hFF) && (b_mantissa != 23'b0);
wire a_is_inf = (a_exponent == 8'hFF) && (a_mantissa == 23'b0);
wire b_is_inf = (b_exponent == 8'hFF) && (b_mantissa == 23'b0);
wire a_is_zero = (a_exponent == 8'h00) && (a_mantissa == 23'b0);
wire b_is_zero = (b_exponent == 8'h00) && (b_mantissa == 23'b0);

always @(posedge clk) begin
    if (rst) begin
        counter <= 3'b0;
        z <= 32'b0;
    end else begin
        case (counter)
            3'b000: begin

                a_sign <= a[31];
                b_sign <= b[31];
                a_exponent <= a[30:23];
                b_exponent <= b[30:23];
                a_mantissa <= (a_exponent == 8'h00) ? a[22:0] : {1'b0, a[22:0]};
                b_mantissa <= (b_exponent == 8'h00) ? b[22:0] : {1'b0, b[22:0]};
                counter <= 3'b001;
            end
            3'b001: begin

                if (a_is_nan || b_is_nan) begin
                    z_exponent <= 8'hFF;
                    z_mantissa <= 23'h000001;

                    z_sign <= a_sign ^ b_sign;
                    counter <= 3'b111;
                end else if (a_is_inf || b_is_inf) begin
                    if (a_is_zero || b_is_zero) begin
                        z_exponent <= 8'hFF;
                        z_mantissa <= 23'b0;

                        z_sign <= a_sign ^ b_sign;
                        counter <= 3'b111;
                    end else begin
                        z_exponent <= 8'hFF;
                        z_mantissa <= 23'b0;
                        z_sign <= a_sign ^ b_sign;
                        counter <= 3'b111;
                    end
                end else if (a_is_zero || b_is_zero) begin
                    z_exponent <= 8'h00;
                    z_mantissa <= 23'b0;
                    z_sign <= a_sign ^ b_sign;
                    counter <= 3'b111;
                end else begin
                    counter <= 3'b010;
                end
            end
            3'b010: begin

                product <= {1'b1, a_mantissa} * {1'b1, b_mantissa};
                counter <= 3'b011;
            end
            3'b011: begin

                if (product[47]) begin
                    product <= product >> 1;
                    adjusted_exponent <= a_exponent + b_exponent - 8'd127;
                end else begin
                    adjusted_exponent <= a_exponent + b_exponent - 8'd126;
                end
                counter <= 3'b100;
            end
            3'b100: begin

                guard_bit <= product[23];
                round_bit <= product[22];
                sticky <= |product[21:0];
                z_mantissa <= product[22:0] + (guard_bit & (round_bit | sticky));
                if (guard_bit & round_bit & sticky) begin
                    z_mantissa <= z_mantissa + 1;
                end
                if (z_mantissa[22]) begin
                    z_mantissa <= z_mantissa >> 1;
                    adjusted_exponent <= adjusted_exponent + 1;
                end
                counter <= 3'b101;
            end
            3'b101: begin

                if (adjusted_exponent >= 8'hFF) begin
                    z_exponent <= 8'hFF;
                    z_mantissa <= 23'b0;
                end else if (adjusted_exponent <= 8'h00) begin
                    z_exponent <= 8'h00;
                    z_mantissa <= 23'b0;
                end else begin
                    z_exponent <= adjusted_exponent;
                end
                counter <= 3'b110;
            end
            3'b110: begin

                z <= {z_sign, z_exponent, z_mantissa};
                counter <= 3'b000;
            end
            default: counter <= 3'b000;
        endcase
    end
end

endmodule

