module LIFObuffer (
    input Clk,
    input Rst,
    input EN,
    input RW,
    input [3:0] dataIn,
    output reg EMPTY,
    output reg FULL,
    output reg [3:0] dataOut
);

reg [3:0] stack_mem [0:3];

reg [2:0] SP;


integer i;

always @(posedge Clk) begin
    if (Rst) begin

        for (i = 0;
 i < 4;
 i = i + 1)
            stack_mem[i] <= 4'b0;
        SP <= 3'd4;
        dataOut <= 4'b0;
    end else if (EN) begin
        if (!RW) begin 
            if (SP != 3'd0) begin
                stack_mem[SP - 1] <= dataIn;
                SP <= SP - 1;
            end
        end else begin 
            if (SP != 3'd4) begin
                dataOut <= stack_mem[SP];
                stack_mem[SP] <= 4'b0;
                SP <= SP + 1;
            end
        end
    end
end


always @(*) begin
    EMPTY = (SP == 3'd4);
    FULL = (SP == 3'd0);
end

endmodule

