module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output [7:0] clock,
    output red,
    output yellow,
    output green
);

parameter idle = 0;
parameter s1_red = 1;
parameter s2_yellow = 2;
parameter s3_green = 3;

reg [7:0] cnt;
reg [1:0] state;
reg p_red, p_yellow, p_green;
reg red_reg, yellow_reg, green_reg;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= idle;
    end else begin
        case (state)
            idle: state <= s1_red;
            s1_red: if (cnt == 0) state <= s3_green;
            s2_yellow: if (cnt == 0) state <= s1_red;
            s3_green: if (cnt == 0) state <= s2_yellow;
            default: state <= idle;
        endcase
    end
end

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        cnt <= 10;
    end else begin
        if (pass_request && green_reg) begin
            cnt <= 10;
        end else if (!green_reg && p_green) begin
            cnt <= 60;
        end else if (!yellow_reg && p_yellow) begin
            cnt <= 5;
        end else if (!red_reg && p_red) begin
            cnt <= 10;
        end else begin
            cnt <= cnt - 1;
        end
    end
end

assign clock = cnt;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        {p_red, p_yellow, p_green} <= 3'b0;
    end else begin
        p_red <= red_reg;
        p_yellow <= yellow_reg;
        p_green <= green_reg;
    end
end

always @(*) begin
    case (state)
        idle: {red_reg, yellow_reg, green_reg} = 3'b000;
        s1_red: {red_reg, yellow_reg, green_reg} = 3'b100;
        s2_yellow: {red_reg, yellow_reg, green_reg} = 3'b010;
        s3_green: {red_reg, yellow_reg, green_reg} = 3'b001;
        default: {red_reg, yellow_reg, green_reg} = 3'b000;
    endcase
end

assign red = red_reg;
assign yellow = yellow_reg;
assign green = green_reg;

endmodule

