                    stored_first <= 1'b1;
                end else begin
                    temp_data <= {data_lock, data_in};
                    temp_valid <= 1'b1;
                end
            end

            if (temp_valid) begin
                data_out <= temp_data;
                valid_out <= 1'b1;
                temp_valid <= 1'b0;
            end else begin
                valid_out <= 1'b0;
            end
        end
    end

