module alu (
    input [31:0] a, b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output reg carry,
    output negative,
    output reg overflow,
    output reg flag
);

    parameter ADD  = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB  = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND  = 6'b100100;
    parameter OR   = 6'b100101;
    parameter XOR  = 6'b100110;
    parameter NOR  = 6'b100111;
    parameter SLT  = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL  = 6'b000000;
    parameter SRL  = 6'b000010;
    parameter SRA  = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI  = 6'b001111;

    reg [32:0] res;

    assign zero = (r == 32'b0);
    assign negative = res[31];

    always @(*) begin
        res = 33'b0;
        carry = 1'b0;
        overflow = 1'b0;

        case (aluc)
            ADD: begin
                res = {a[31], a} + {b[31], b};
                overflow = (a[31] == b[31]) && (res[31] != a[31]);
                carry = res[32];
            end
            ADDU: begin
                res = {1'b0, a} + {1'b0, b};
                carry = res[32];
            end
            SUB: begin
                res = {a[31], a} - {b[31], b};
                overflow = (a[31] != b[31]) && (res[31] != a[31]);
                carry = res[32];
            end
            SUBU: begin
                res = {1'b0, a} - {1'b0, b};
                carry = res[32];
            end
            AND: res = {33'b0, a & b};
            OR:  res = {33'b0, a | b};
            XOR: res = {33'b0, a ^ b};
            NOR: res = {33'b0, ~(a | b)};
            SLT: res = {33'b0, ($signed(a) < $signed(b)) ? 1'b1 : 1'b0};
            SLTU: res = {33'b0, (a < b) ? 1'b1 : 1'b0};
            SLL: res = {33'b0, b << a[4:0]};
            SRL: res = {33'b0, b >> a[4:0]};
            SRA: res = {33'b0, $signed(b) >>> a[4:0]};
            SLLV: res = {33'b0, b << a[4:0]};
            SRLV: res = {33'b0, b >> a[4:0]};
            SRAV: res = {33'b0, $signed(b) >>> a[4:0]};
            LUI: res = {a[31:16], 16'b0};
            default: res = 33'bz;
        endcase

        r = res[31:0];
        flag = (aluc == SLT || aluc == SLTU) ? 1'b1 : 1'bz;
    end

endmodule

