module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [7:0] dividend_reg, divisor_reg;
    reg [7:0] abs_dividend, abs_divisor;
    reg [8:0] NEG_DIVISOR;
    reg [16:0] SR;
    reg [3:0] cnt;
    reg start_cnt;
    reg sign_quotient, sign_remainder;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 1'b0;
            result <= 16'b0;
            dividend_reg <= 8'b0;
            divisor_reg <= 8'b0;
            abs_dividend <= 8'b0;
            abs_divisor <= 8'b0;
            NEG_DIVISOR <= 9'b0;
            SR <= 17'b0;
            cnt <= 4'b0;
            start_cnt <= 1'b0;
            sign_quotient <= 1'b0;
            sign_remainder <= 1'b0;
        end else begin
            if (opn_valid && !res_valid) begin
                dividend_reg <= dividend;
                divisor_reg <= divisor;
                abs_dividend <= sign ? (dividend[7] ? -dividend : dividend) : dividend;
                abs_divisor <= sign ? (divisor[7] ? -divisor : divisor) : divisor;
                NEG_DIVISOR <= sign ? -({1'b0, (divisor[7] ? -divisor : divisor)}) : -({1'b0, divisor});
                SR <= {abs_dividend, 8'b0} << 1;
                sign_quotient <= (sign && (dividend[7] ^ divisor[7]));
                sign_remainder <= sign && dividend[7];
                start_cnt <= 1'b1;
                cnt <= 4'b0;
                res_valid <= 1'b0;
            end else if (start_cnt) begin
                if (cnt < 8) begin
                    wire [8:0] remainder_upper = SR[16:8];
                    wire [8:0] divisor_ext = {NEG_DIVISOR[8], NEG_DIVISOR[7:0]};
                    wire [8:0] sub_result = remainder_upper - divisor_ext;
                    wire carry_out = ~sub_result[8];

                    if (carry_out) begin
                        SR <= {sub_result[7:0], SR[7:1], 1'b1};
                    end else begin
                        SR <= {remainder_upper - divisor_ext, SR[7:1], 1'b0};
                    end
                    cnt <= cnt + 1;
                end else begin
                    start_cnt <= 1'b0;
                    cnt <= 4'b0;
                    if (sign) begin
                        reg [7:0] quotient = SR[7:0];
                        reg [7:0] remainder = SR[15:8];
                        if (sign_quotient) quotient <= -quotient;
                        if (sign_remainder) remainder <= -remainder;
                        result <= {remainder, quotient};
                    end else begin
                        result <= {8'b0, SR[7:0]};
                    end
                    res_valid <= 1'b1;
                end
            end else begin
                res_valid <= 1'b0;
            end
        end
    end

endmodule

