 i >= 0;
 i = i - 1) begin
        remainder = {remainder[14:0], dividend[i]};
        dividend = {dividend[i-1:0]};

        if (remainder >= {8'b0, b_reg}) begin
            res[i] = 1'b1;
            remainder = remainder - {8'b0, b_reg};
