module cla_16bit (
    input [15:0] A,
    input [15:0] B,
    input C_in,
    output [15:0] S,
    output GG,
    output PP
);

wire [15:0] G, P;
wire [16:0] C;

assign C[0] = C_in;

genvar i;
generate
    for (i = 0;
 i < 16;
 i = i + 1) begin : bit_loop
        assign G[i] = A[i] & B[i];
        assign P[i] = A[i] ^ B[i];
        assign C[i+1] = G[i] | (P[i] & C[i]);
        assign S[i] = P[i] ^ C[i];
    end
endgenerate

assign PP = &P;



wire [15:0] GG_terms;
assign GG_terms[15] = G[15];
genvar j;
generate
    for (j = 14;
 j >= 0;
 j = j - 1) begin : gg_loop
        assign GG_terms[j] = G[j] | (P[j] & GG_terms[j+1]);
    end
endgenerate
assign GG = GG_terms[0];

endmodule

