wire sign_b = b[N-1];

wire signed [N-1:0] a_signed = a;
wire signed [N-1:0] b_signed = b;

reg [N-1:0] res;

always @(*) begin
    if (sign_a == sign_b) begin

        res = a_signed + b_signed;
    end else begin

        if (a_signed > b_signed) begin
            res = a_signed - b_signed;
        end else if (b_signed > a_signed) begin
            res = b_signed - a_signed;
        end else begin

            res = 0;
        end
    end
end

assign c = res;

endmodule

