module fixed_point_subtractor #(
    parameter Q = 4,
    parameter N = 8
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output wire [N-1:0] c
);

    reg [N-1:0] res;
    reg sign_a, sign_b, same_sign;
    reg [N-1:0] abs_a, abs_b;
    reg [N-1:0] sum;
    reg result_sign;

    always @(*) begin
        sign_a = a[N-1];
        sign_b = b[N-1];
        same_sign = (sign_a == sign_b);

        if (same_sign) begin
            res = a - b;

            if (res == 0) begin
                result_sign = 1'b0;
            end else begin
                result_sign = sign_a;
            end
        end else begin

            abs_a = sign_a ? (~a + 1) : a;
            abs_b = sign_b ? (~b + 1) : b;

            sum = abs_a + abs_b;


            if (abs_a > abs_b) begin
                result_sign = 1'b0;

            end else if (abs_b > abs_a) begin
                result_sign = 1'b1;

            end else begin
                result_sign = 1'b0;

            end

            res = sum;
            res[N-1] = result_sign;


            if (sum == 0) begin
                result_sign = 1'b0;
                res = 0;
            end
        end


        if (same_sign && res == 0) begin
            res[N-1] = 1'b0;
        end

        c = res;
    end

endmodule

