module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

reg [2:0] counter;
reg a_sign, b_sign, z_sign;
reg [7:0] a_exponent, b_exponent, z_exponent;
reg [23:0] a_mantissa, b_mantissa, z_mantissa;
reg [49:0] product;
reg guard, round, sticky;
reg overflow, underflow;

wire a_is_nan = (a_exponent == 8'hff) && (a_mantissa != 24'd0);
wire a_is_inf = (a_exponent == 8'hff) && (a_mantissa == 24'd0);
wire a_is_zero = (a_exponent == 8'd0) && (a_mantissa == 24'd0);
wire b_is_nan = (b_exponent == 8'hff) && (b_mantissa != 24'd0);
wire b_is_inf = (b_exponent == 8'hff) && (b_mantissa == 24'd0);
wire b_is_zero = (b_exponent == 8'd0) && (b_mantissa == 24'd0);

always @(posedge clk) begin
    if (rst) begin
        counter <= 3'b000;
        z <= 32'd0;
    end else begin
        case (counter)
            3'b000: begin 
                a_sign <= a[31];
                b_sign <= b[31];
                a_exponent <= a[30:23];
                b_exponent <= b[30:23];
                a_mantissa <= (a[30:23] != 0) ? {1'b1, a[22:0]} : {1'b0, a[22:0]};
                b_mantissa <= (b[30:23] != 0) ? {1'b1, b[22:0]} : {1'b0, b[22:0]};
                counter <= 3'b001;
            end
            3'b001: begin 
                if (a_is_nan || b_is_nan) begin
                    z_sign <= a_sign ^ b_sign;
                    z_exponent <= 8'hff;
                    z_mantissa <= 24'h000001;
                end else if (a_is_inf || b_is_inf) begin
                    if ((a_is_inf && !b_is_zero) || (b_is_inf && !a_is_zero)) begin
                        z_sign <= a_sign ^ b_sign;
                        z_exponent <= 8'hff;
                        z_mantissa <= 24'd0;
                    end else begin
                        z_exponent <= 8'd0;
                        z_mantissa <= 24'd0;
                    end
                end else if (a_is_zero || b_is_zero) begin
                    z_exponent <= 8'd0;
                    z_mantissa <= 24'd0;
                end else begin
                    product <= a_mantissa * b_mantissa;
                    counter <= 3'b010;
                end
            end
            3'b010: begin 

                if (product[49]) begin
                    z_exponent <= a_exponent + b_exponent - 8'd127 + 9'd1;
                    z_mantissa <= product[48:25];
                end else begin
                    z_exponent <= a_exponent + b_exponent - 8'd127;
                    z_mantissa <= product[47:24];
                end
                counter <= 3'b011;
            end
            3'b011: begin 

                guard = product[24];
                round = product[23];
                sticky = |product[22:0];

                if ((round && (guard || sticky)) || (round && !guard)) begin
                    if (z_mantissa[0]) begin
                        z_mantissa <= z_mantissa + 1;
                    end else begin
                        z_mantissa <= z_mantissa + 1;
                    end
                end
                counter <= 3'b100;
            end
            3'b100: begin 
                if (z_mantissa[24]) begin
                    z_exponent <= z_exponent + 1;
                    z_mantissa <= z_mantissa >> 1;
                end
                counter <= 3'b101;
            end
            3'b101: begin 
                if (z_exponent >= 8'hfe) begin
                    z_exponent <= 8'hff;
                    z_mantissa <= 24'd0;
                end else if (z_exponent == 0) begin
                    z_exponent <= 0;
                    z_mantissa <= z_mantissa >> 1;
                end
                counter <= 3'b110;
            end
            3'b110: begin 
                z <= {a_sign ^ b_sign, z_exponent, z_mantissa};
                counter <= 3'b000;
            end
            default: counter <= 3'b000;
        endcase
    end
end

endmodule

