module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);


    localparam S0 = 2'b00;
    localparam S1 = 2'b01;
    localparam S2 = 2'b10;

    reg [1:0] state, next_state;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= S0;
            data_out <= 1'b0;
        end else begin
            state <= next_state;

            data_out <= (next_state == S0 && state == S2) ? 1'b1 : 1'b0;
        end
    end


    always @(*) begin
        case (state)
            S0: begin
                next_state = (data_in == 1'b0) ? S1 : S0;
            end
            S1: begin
                next_state = (data_in == 1'b1) ? S2 : S0;
            end
            S2: begin
                next_state = (data_in == 1'b0) ? S0 : S0;

            end
            default: begin
                next_state = S0;
            end
        endcase
    end

endmodule

