module radix2_div (
    clk,
    rst,
    sign,
    dividend,
    divisor,
    opn_valid,
    res_valid,
    result
);

input clk, rst, sign;
input [7:0] dividend, divisor;
input opn_valid;
output reg res_valid;
output [15:0] result;

reg [7:0] dividend_reg, divisor_reg;
reg sign_reg;
reg [15:0] SR;
reg [3:0] cnt;
reg start_cnt;
reg [7:0] divisor_abs;
reg [7:0] NEG_DIVISOR;

wire [15:0] remainder_quotient = {remainder, quotient};

always @(posedge clk) begin
    if (rst) begin
        res_valid <= 1'b0;
        dividend_reg <= 8'b0;
        divisor_reg <= 8'b0;
        sign_reg <= 1'b0;
        SR <= 16'b0;
        cnt <= 4'b0;
        start_cnt <= 1'b0;
        quotient <= 8'b0;
        remainder <= 8'b0;
        divisor_abs <= 8'b0;
        NEG_DIVISOR <= 8'b0;
    end else begin
        if (res_valid) begin
            res_valid <= 1'b0;
        end

        if (opn_valid && !res_valid) begin

            dividend_reg <= dividend;
            divisor_reg <= divisor;
            sign_reg <= sign;

            divisor_abs <= sign ? (divisor[7] ? -divisor : divisor) : divisor;
            divisor_abs <= sign ? (divisor[7] ? -divisor : divisor) : divisor;

            NEG_DIVISOR <= -divisor_abs;


            SR <= { (sign ? (dividend[7] ? -dividend : dividend) : dividend), 8'b0 } << 1;

            cnt <= 4'd1;
            start_cnt <= 1'b1;
            res_valid <= 1'b0;
            quotient <= 8'b0;
            remainder <= 8'b0;
        end else if (start_cnt && cnt <= 8) begin
            if (cnt == 8) begin

                start_cnt <= 1'b0;

                if (sign_reg) begin

                    if (dividend_reg[7] ^ divisor_reg[7]) begin
                        quotient <= ~quotient;
                    end

                    if (dividend_reg[7]) begin
                        remainder <= -remainder;
                    end
                end
                res_valid <= 1'b1;
            end else begin

                wire [8:0] sub_result = {1'b0, SR[15:8]} + {1'b0, divisor_abs};
                reg [7:0] new_remainder;
                reg new_qbit;

                if (sub_result[8] == 1'b0) begin
                    new_remainder = sub_result[7:0];
                    new_qbit = 1'b1;
                end else begin
                    new_remainder = SR[15:8];
                    new_qbit = 1'b0;
                end

                SR <= {new_remainder, (SR[7:0] << 1) | new_qbit};
                quotient <= (quotient << 1) | new_qbit;
                remainder <= new_remainder;
                cnt <= cnt + 1;
            end
        end
    end
end

endmodule

