module accu (
    input clk,
    input rst_n,
    input [7:0] data_in,
    input valid_in,
    output reg valid_out,
    output [9:0] data_out
);

reg [9:0] sum_reg;
reg [1:0] counter;
reg valid_out_reg;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        sum_reg <= 10'b0;
        counter <= 2'b0;
        valid_out_reg <= 1'b0;
    end else begin
        valid_out_reg <= 1'b0;
        if (valid_in) begin
            sum_reg <= sum_reg + data_in;
            counter <= counter + 1;
            if (counter == 2'b11) begin
                valid_out_reg <= 1'b1;
            end
        end
    end
end

assign data_out = sum_reg + data_in;
assign valid_out = valid_out_reg;

endmodule

