module fixed_point_adder #(
    parameter Q = 2,
    parameter N = 8
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output wire [N-1:0] c
);

reg [N-1:0] res;

wire a_sign = a[N-1];
wire b_sign = b[N-1];
wire same_sign = (a_sign == b_sign);

wire [N-1:0] abs_a = a_sign ? (-a) : a;
wire [N-1:0] abs_b = b_sign ? (-b) : b;

wire [N-1:0] sum_abs = abs_a + abs_b;
wire [N-1:0] diff_abs = abs_a - abs_b;
wire diff_sign = (abs_a > abs_b) ? 1'b0 : 1'b1;

wire [N-1:0] result = same_sign ? {a_sign, sum_abs[N-2:0]} : {diff_sign, diff_abs[N-2:0]};

always @(*) begin
    res = result;
end

assign c = res;

endmodule

