module fixed_point_subtractor #(
    parameter Q = 8,
    parameter N = 16
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output wire [N-1:0] c
);

    reg [N-1:0] res;
    wire res_is_zero;

    wire sign_a = a[N-1];
    wire sign_b = b[N-1];
    wire same_sign = (sign_a == sign_b);

    wire [N-1:0] a_abs = sign_a ? (~a + 1) : a;
    wire [N-1:0] b_abs = sign_b ? (~b + 1) : b;

    always @(*) begin
        if (same_sign) begin
            res = a - b;
            res[N-1] = sign_a;
        end else begin
            if (sign_a) begin 
                if (a_abs > b_abs) begin
                    res = b_abs - a_abs;
                    res[N-1] = 1'b1;
                end else begin
                    res = a_abs - b_abs;
                    res[N-1] = 1'b0;
                end
            end else begin 
                if (a_abs > b_abs) begin
                    res = a_abs - b_abs;
                    res[N-1] = 1'b0;
                end else begin
                    res = b_abs - a_abs;
                    res[N-1] = 1'b1;
                end
            end
        end
    end

    assign res_is_zero = (res == 0);
    assign c = res_is_zero ? {1'b0, res[N-2:0]} : res;

endmodule

