    localparam SPECIAL = 1;
    localparam MANTISSA = 2;
    localparam NORMALIZE = 3;
    localparam ROUND = 4;
    localparam ADJUST = 5;
    localparam OUTPUT = 6;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'd0;
            a_reg <= 32'd0;
            b_reg <= 32'd0;
            a_sign <= 1'b0;
