                    b_mantissa <= (b[22:0] == 23'd0) ? 23'd1 : {1'b1, b[22:0]};
                    counter <= SPECIAL;
                end
                SPECIAL: begin
                    if (a_exponent == 8'hFF || b_exponent == 8'hFF) begin
                        special_case <= 1;
                    end else if (a_exponent == 8'h00 || b_exponent == 8'h00) begin
                        special_case <= 2;
