module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red, yellow, green
);

    parameter idle = 2'b00,
              s3_green = 2'b01,
              s2_yellow = 2'b10,
              s1_red = 2'b11;

    reg [1:0] state, next_state;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) state <= idle;
        else state <= next_state;
    end


    always @(*) begin
        case (state)
            idle:       next_state = s3_green;
            s3_green:   next_state = (cnt == 0) ? s2_yellow : s3_green;
            s2_yellow:  next_state = (cnt == 0) ? s1_red : s2_yellow;
            s1_red:     next_state = (cnt == 0) ? s3_green : s1_red;
            default:    next_state = idle;
        endcase
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 8'd59;

        end else begin
            if (pass_request && green)
                cnt <= 8'd10;

            else if (!green && p_green)
                cnt <= 8'd59;

            else if (!yellow && p_yellow)
                cnt <= 8'd4;

            else if (!red && p_red)
                cnt <= 8'd9;

            else
                cnt <= cnt - 1;
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            p_red <= 1'b0;
            p_yellow <= 1'b0;
            p_green <= 1'b0;
        end else begin
            p_red <= red;
            p_yellow <= yellow;
            p_green <= green;
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            red <= 1'b0;
            yellow <= 1'b0;
            green <= 1'b0;
        end else begin
            case (state)
                s3_green: green <= 1'b1;
                s2_yellow: yellow <= 1'b1;
                s1_red: red <= 1'b1;
                default: begin
                    red <= 1'b0;
                    yellow <= 1'b0;
                    green <= 1'b0;
                end
            endcase
        end
    end

    assign clock = cnt;

endmodule

