module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [15:0] sr_reg;
reg [2:0] cnt_reg;
reg start_cnt_reg;
reg [7:0] dividend_reg, divisor_reg;
reg [7:0] neg_divisor_reg;
reg sign_reg;

always @(posedge clk) begin
    if (rst) begin
        res_valid <= 1'b0;
        sr_reg <= 16'b0;
        cnt_reg <= 3'b0;
        start_cnt_reg <= 1'b0;
        dividend_reg <= 8'b0;
        divisor_reg <= 8'b0;
        neg_divisor_reg <= 8'b0;
        sign_reg <= 1'b0;
    end else begin
        if (opn_valid && !res_valid) begin

            reg [7:0] dividend_abs, divisor_abs;
            sign_reg <= sign;
            if (sign) begin
                dividend_abs = dividend[7] ? -dividend : dividend;
                divisor_abs = divisor[7] ? -divisor : divisor;
            end else begin
                dividend_abs = dividend;
                divisor_abs = divisor;
            end
            neg_divisor_reg <= -divisor_abs;

            sr_reg <= {dividend_abs, 1'b0} << 1;

            cnt_reg <= 3'b1;
            start_cnt_reg <= 1'b1;
            dividend_reg <= dividend;
            divisor_reg <= divisor;
        end else if (start_cnt_reg) begin
            if (cnt_reg == 3'd8) begin

                start_cnt_reg <= 1'b0;
                cnt_reg <= 3'b0;
                result <= {sr_reg[15:8], sr_reg[7:0]};

                res_valid <= 1'b1;
            end else begin

                reg [8:0] remainder = sr_reg[15:7];
                reg [7:0] divisor_val = neg_divisor_reg;
                reg [8:0] sub_result;
                reg carry_out;
                reg [15:0] new_sr;
                sub_result = remainder - divisor_val;
                carry_out = ~sub_result[8];

                if (carry_out) begin

                    new_sr = {sub_result, sr_reg[6:0] | 1'b1};
                end else begin

                    new_sr = {remainder, sr_reg[6:0]};
                end
                sr_reg <= new_sr;
                cnt_reg <= cnt_reg + 1;
            end
        end else begin
            res_valid <= 1'b0;
        end
    end
end

endmodule

