module cla_16bit (
    input [16:1] A,
    input [16:1] B,
    input C_in,
    output [16:1] S,
    output G,
    output P,
    output C_out
);

    wire [17:1] C;
    assign C[1] = C_in;

    wire [16:1] G_bits, P_bits;
    assign G_bits = A & B;
    assign P_bits = A | B;

    generate
        genvar i;
        for (i = 1;
 i <= 16;
 i = i + 1) begin : cla_gen
            assign C[i+1] = G_bits[i] | (P_bits[i] & C[i]);
            assign S[i] = A[i] ^ B[i] ^ C[i];
        end
    endgenerate

    wire [16:1] group_G_terms;
    assign group_G_terms[16] = G_bits[16];
    genvar j;
    for (j = 15;
 j >= 1;
 j = j - 1) begin : group_G_terms_gen
        assign group_G_terms[j] = G_bits[j] & (&P_bits[j+1 : 16]);
    end
    assign G = |group_G_terms;
    assign P = &P_bits;
    assign C_out = G | (P & C_in);

endmodule

