module accu (
    input clk,
    input rst_n,
    input [7:0] data_in,
    input valid_in,
    output reg valid_out,
    output reg [9:0] data_out
);

reg [1:0] counter;
reg [7:0] buffer [0:3];

wire [9:0] sum = buffer[0] + buffer[1] + buffer[2] + buffer[3];


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        counter <= 2'b00;
    end else if (valid_in) begin
        if (counter == 2'b11) begin
            counter <= 2'b00;
        end else begin
            counter <= counter + 1;
        end
    end
end


integer i;
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        for (i = 0;
 i < 4;
 i = i + 1)
            buffer[i] <= 8'b0;
    end else if (valid_in) begin
        buffer[counter] <= data_in;
    end
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        data_out <= 10'b0;
        valid_out <= 1'b0;
    end else begin
        if (valid_in && counter == 2'b11) begin
            data_out <= sum;
            valid_out <= 1'b1;
        end else begin
            data_out <= 10'b0;
            valid_out <= 1'b0;
        end
    end
end

endmodule

