module fixed_point_adder #(
    parameter Q = 1,
    parameter N = 4
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

    reg [N-1:0] res;

    always @(*) begin
        reg sign_a = a[N-1];
        reg sign_b = b[N-1];
        reg [N-1:0] abs_a, abs_b;
        reg [N-1:0] sum_abs;
        reg [N-1:0] sub_result;
        reg sign;

        if (sign_a == sign_b) begin

            abs_a = sign_a ? (~a + 1) : a;
            abs_b = sign_b ? (~b + 1) : b;
            sum_abs = abs_a + abs_b;
            res = {sign_a, sum_abs[N-2:0]};
        end else begin

            abs_a = sign_a ? (~a + 1) : a;
            abs_b = sign_b ? (~b + 1) : b;
            if (abs_a > abs_b) begin
                sub_result = abs_a - abs_b;
                sign = 0;
            end else if (abs_b > abs_a) begin
                sub_result = abs_b - abs_a;
                sign = 1;
            end else begin
                sub_result = 0;
