    reg sign_res;

    if (signs_same) begin
        res_mag = mag_sub_mag;
        sign_res = sign_a;
    end else begin
        res_mag = mag_a_plus_mag_b;
        if (a_greater_than_b) begin
            sign_res = sign_a;
        end else begin
            sign_res = sign_b;
        end
    end


    if (res_mag == 0) begin
        sign_res = 0;
    end

    res = {sign_res, res_mag};
end

assign c = res;

endmodule

