module barrel_shifter (
    input [7:0] in,
    input [2:0] ctrl,
    output [7:0] out
);
    wire [7:0] stage1_out, stage2_out;

    mux2X1 mux_stage1 (
        .a({in[3:0], in[7:4]}),
        .b(in),
        .sel(ctrl[2]),
        .out(stage1_out)
    );

    mux2X1 mux_stage2 (
        .a({stage1_out[1:0], stage1_out[7:2]}),
        .b(stage1_out),
        .sel(ctrl[1]),
        .out(stage2_out)
    );

    mux2X1 mux_stage3 (
        .a({stage2_out[0], stage2_out[7:1]}),
        .b(stage2_out),
        .sel(ctrl[0]),
        .out(out)
    );
endmodule

