module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wclk,
    input rclk,
    input wrstn,
    input rrstn,
    input winc,
    input rinc,
    input [WIDTH-1:0] wdata,
    output wfull,
    output rempty,
    output [WIDTH-1:0] rdata
);


    dual_port_RAM #(
        .WIDTH(WIDTH),
        .DEPTH(DEPTH)
    ) ram (
        .wclk(wclk),
        .wenc(wenc),
        .waddr(waddr_bin),
        .wdata(wdata),
        .rclk(rclk),
        .renc(renc),
        .raddr(raddr_bin),
        .rdata(rdata)
    );


    reg [3:0] waddr_bin;
    always @(posedge wclk or negedge wrstn) begin
        if (~wrstn) waddr_bin <= 4'b0;
        else if (winc && !wfull) waddr_bin <= waddr_bin + 1;
    end
    wire [3:0] wptr = waddr_bin ^ (waddr_bin >> 1);


    reg [3:0] raddr_bin;
    always @(posedge rclk or negedge rrstn) begin
        if (~rrstn) raddr_bin <= 4'b0;
        else if (rinc && !rempty) raddr_bin <= raddr_bin + 1;
    end
    wire [3:0] rptr = raddr_bin ^ (raddr_bin >> 1);


    reg [3:0] rptr_buff1, rptr_buff2;
    always @(posedge wclk or negedge wrstn) begin
        if (~wrstn) {rptr_buff1, rptr_buff2} <= 8'b0;
        else {rptr_buff1, rptr_buff2} <= {rptr, rptr_buff1};
    end


    reg [3:0] wptr_buff1, wptr_buff2;
    always @(posedge rclk or negedge rrstn) begin
        if (~rrstn) {wptr_buff1, wptr_buff2} <= 8'b0;
        else {wptr_buff1, wptr_buff2} <= {wptr, wptr_buff1};
    end


    assign rempty = (rptr == wptr_buff2);
    assign wfull = (wptr[3] != rptr_buff2[3]) && (wptr[2] != rptr_buff2[2]) && (wptr[1:0] == rptr_buff2[1:0]);


    wire wenc = winc && !wfull;
    wire renc = rinc && !rempty;

endmodule


module dual_port_RAM #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wclk,
    input wenc,
    input [$clog2(DEPTH)-1:0] waddr,
    input [WIDTH-1:0] wdata,
    input rclk,
    input renc,
    input [$clog2(DEPTH)-1:0] raddr,
    output reg [WIDTH-1:0] rdata
);

    reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];


    always @(posedge wclk) begin
        if (wenc) RAM_MEM[waddr] <= wdata;
    end


    always @(posedge rclk) begin
        if (renc) rdata <= RAM_MEM[raddr];
    end

endmodule

