module parallel2serial (
    input clk,
    input rst_n,
    input [3:0] d,
    output valid_out,
    output dout
);

    reg [1:0] cnt;
    reg [3:0] data;
    reg valid;

    always @(posedge clk) begin
        if (!rst_n) begin
            cnt <= 2'b0;
            data <= 4'b0;
            valid <= 1'b0;
        end else begin
            if (cnt == 2'd3) begin
                data <= d;
                cnt <= 2'b0;
                valid <= 1'b1;
            end else begin
                data <= data << 1;
                cnt <= cnt + 1;
                valid <= 1'b0;
            end
        end
    end

    assign dout = data[3];
    assign valid_out = valid;

endmodule

