module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

    reg [1:0] state, next_state;

    parameter IDLE = 2'b00,
              S1 = 2'b01,
              S2 = 2'b10;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            state <= IDLE;
            data_out <= 1'b0;
        end else begin
            state <= next_state;
            data_out <= (state == S2) && (data_in == 1'b0) ? 1'b1 : 1'b0;
        end
    end

    always @(*) begin
        case (state)
            IDLE: next_state = (data_in == 1'b0) ? S1 : IDLE;
            S1:   next_state = (data_in == 1'b1) ? S2 : IDLE;
            S2:   next_state = (data_in == 1'b0) ? IDLE : S1;
            default: next_state = IDLE;
        endcase
    end

endmodule

