module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output [7:0] clock,
    output red,
    output yellow,
    output green
);


parameter idle = 2'b00;
parameter s1_red = 2'b01;
parameter s2_yellow = 2'b10;
parameter s3_green = 2'b11;


reg [7:0] cnt;
reg [1:0] state;
reg p_red, p_yellow, p_green;


assign clock = cnt;
assign red = p_red;
assign yellow = p_yellow;
assign green = p_green;


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= idle;
        cnt <= 8'd10;
    end else begin
        case (state)
            idle: state <= s1_red;
            s1_red: cnt <= (cnt == 3) ? s3_green : cnt - 1;
            s3_green: cnt <= (cnt == 3) ? s2_yellow : cnt - 1;
            s2_yellow: cnt <= (cnt == 3) ? s1_red : cnt - 1;
            default: state <= idle;
        endcase
    end
end


always @(*) begin
    if (!rst_n) begin
        cnt = 8'd10;
    end else if (pass_request && green) begin
        cnt = 8'd10;
    end else if (!green && p_green) begin
        cnt = 8'd60;
    end else if (!yellow && p_yellow) begin
        cnt = 8'd5;
    end else if (!red && p_red) begin
        cnt = 8'd10;
    end else begin
        cnt = cnt - 1;
    end
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        p_red <= 0;
        p_yellow <= 0;
        p_green <= 0;
    end else begin
        p_red <= red;
        p_yellow <= yellow;
        p_green <= green;
    end
end

endmodule

