module alu(
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output reg carry,
    output negative,
    output reg overflow,
    output reg flag
);


    localparam ADD  = 6'b100000;
    localparam ADDU = 6'b100001;
    localparam SUB  = 6'b100010;
    localparam SUBU = 6'b100011;
    localparam AND  = 6'b100100;
    localparam OR   = 6'b100101;
    localparam XOR  = 6'b100110;
    localparam NOR  = 6'b100111;
    localparam SLT  = 6'b101010;
    localparam SLTU = 6'b101011;
    localparam SLL  = 6'b000000;
    localparam SRL  = 6'b000010;
    localparam SRA  = 6'b000011;
    localparam SLLV = 6'b000100;
    localparam SRLV = 6'b000110;
    localparam SRAV = 6'b000111;
    localparam LUI  = 6'b001111;


    reg [32:0] res;



    always @(*) begin
        case (aluc)
            ADD:  res = {1'b0, a} + {1'b0, b};
            ADDU: res = {1'b0, a} + {1'b0, b};
            SUB:  res = {1'b0, a} - {1'b0, b};
            SUBU: res = {1'b0, a} - {1'b0, b};
            AND:  res = {1'b0, a & b};
            OR:   res = {1'b0, a | b};
            XOR:  res = {1'b0, a ^ b};
            NOR:  res = {1'b0, ~(a | b)};
            SLT:  res = {1'b0, ($signed(a) < $signed(b)) ? 1'b1 : 1'b0};
            SLTU: res = {1'b0, (a < b) ? 1'b1 : 1'b0};
            SLL:  res = {1'b0, b << a[4:0]};
            SRL:  res = {1'b0, b >> a[4:0]};
            SRA:  res = {1'b0, $signed(b) >>> a[4:0]};
            SLLV: res = {1'b0, b << a[4:0]};
            SRLV: res = {1'b0, b >> a[4:0]};
            SRAV: res = {1'b0, $signed(b) >>> a[4:0]};
            LUI:  res = {1'b0, a[31:16], 16'b0};
            default: res = 33'bz;

        endcase
    end


    assign r = res[31:0];
    assign zero = (r == 32'b0) ? 1'b1 : 1'b0;
    assign negative = r[31];


    always @(*) begin
        case (aluc)
            ADD, SUB: begin

                overflow = ($signed(a) == $signed(b)) && (res[31] != a[31]);
            end
            default: overflow = 1'b0;
        endcase
    end

    always @(*) begin
        case (aluc)
            ADD, ADDU, SUB, SUBU: carry = res[32];
            default: carry = 1'b0;
        endcase
    end

    always @(*) begin
        case (aluc)
            SLT: flag = ($signed(a) < $signed(b)) ? 1'b1 : 1'b0;
            SLTU: flag = (a < b) ? 1'b1 : 1'b0;
            default: flag = 1'b0;
        endcase
    end

endmodule

