module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [15:0] SR;
    reg [3:0] cnt;
    reg [7:0] saved_dividend, saved_divisor;
    reg [7:0] abs_dividend, abs_divisor;
    reg [7:0] NEG_DIVISOR;
    reg start_cnt;
    reg sign_reg;
    reg state;


    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            state <= 0;
            cnt <= 0;
            start_cnt <= 0;
            SR <= 0;
            result <= 0;
            saved_dividend <= 0;
            saved_divisor <= 0;
            sign_reg <= 0;
        end else begin
            case (state)
                0: begin 
                    if (opn_valid && !res_valid) begin

                        saved_dividend <= dividend;
                        saved_divisor <= divisor;
                        sign_reg <= sign;
                        abs_dividend <= sign ? (dividend[7] ? -dividend : dividend) : dividend;
                        abs_divisor <= sign ? (divisor[7] ? -divisor : divisor) : divisor;
                        NEG_DIVISOR <= -abs_divisor;

                        SR <= {abs_dividend, 8'b0} << 1;
                        cnt <= 1;
                        start_cnt <= 1;
                        state <= 1;
                        res_valid <= 0;
                    end
                end
                1: begin 
                    if (start_cnt) begin
                        if (cnt == 8) begin

                            state <= 0;
                            start_cnt <= 0;
                            cnt <= 0;
                            res_valid <= 1;

                            result <= {saved_dividend[7] ? -SR[15:8] : SR[15:8],
                                      (sign_reg ? (saved_dividend[7] ^ saved_divisor[7]) : 1'b0) ? -SR[7:0] : SR[7:0]};
                        end else begin

                            reg [8:0] remainder_part = SR[15:7];
                            reg [8:0] sub_result = remainder_part - NEG_DIVISOR;
                            reg carry_out = !sub_result[8];

                            reg [15:0] mux_result;

                            if (carry_out) begin
                                mux_result = {sub_result[7:0], SR[6:0], 1'b1};
                            end else begin
                                mux_result = {remainder_part, SR[6:0], 1'b0};
                            end

                            SR <= mux_result;
                            cnt <= cnt + 1;
                        end
                    end
                end
            endcase
        end
    end
endmodule

