module fixed_point_adder #(
    parameter Q = 4,  
    parameter N = 8   
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

    reg [N-1:0] res;
    assign c = res;

    wire sign_a = a[N-1];
    wire sign_b = b[N-1];
    wire same_sign = (sign_a == sign_b);

    wire [N-1:0] abs_a = sign_a ? (~a + 1) : a;
    wire [N-1:0] abs_b = sign_b ? (~b + 1) : b;

    wire a_gt_b = (abs_a > abs_b);
    wire b_gt_a = (abs_b > abs_a);

    always @(*) begin
        if (same_sign) begin
            res = a + b;
        end else begin
            if (a_gt_b) begin
                res = {sign_a, (abs_a - abs_b)[N-2:0]};
            end else if (b_gt_a) begin
                res = {sign_b, (abs_b - abs_a)[N-2:0]};
            end else begin
                res = {1'b0, {(N-1){1'b0}}};
            end
        end
    end

endmodule

