    if (same_sign) begin

        res = a - b;
        res[N-1] = a[N-1];
    end else begin

        res = sum_mag;
        res[N-1] = sum_sign;
    end


    if (res == 0)
        res = {N{1'b0}};
end

assign c = res;

endmodule

