module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg [8:0] a_exponent, b_exponent, z_exponent;
    reg a_sign, b_sign, z_sign;
    reg [22:0] a_mantissa, b_mantissa, z_mantissa;
    reg [47:0] product;
    reg guard_bit, round_bit, sticky;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'd0;
            z <= 32'd0;
            a_exponent <= 9'd0;
            b_exponent <= 9'd0;
            a_sign <= 1'b0;
            b_sign <= 1'b0;
            z_exponent <= 9'd0;
            a_mantissa <= 23'd0;
            b_mantissa <= 23'd0;
            product <= 48'd0;
        end else begin
            case (counter)
                3'd0: begin

                    a_sign <= a[31];
                    a_exponent <= {1'b0, a[30:23]};
                    a_mantissa <= (a[30:23] != 8'd0) ? {1'b1, a[22:0]} : {1'b0, a[22:0]};

                    b_sign <= b[31];
                    b_exponent <= {1'b0, b[30:23]};
                    b_mantissa <= (b[30:23] != 8'd0) ? {1'b1, b[22:0]} : {1'b0, b[22:0]};

                    product <= 48'd0;
                    counter <= 3'd1;
                end
                3'd1: begin

                    if ((a[30:23] == 8'hff && a[22:0] != 0) || (b[30:23] == 8'hff && b[22:0] != 0)) begin
                        z <= (a[30:23] == 8'hff && a[22:0] != 0) ? {a_sign, 8'hff, a[22:0]} :
                             (b[30:23] == 8'hff && b[22:0] != 0) ? {b_sign, 8'hff, b[22:0]} :
                             (a[30:23] == 8'hff && b[30:23] == 8'hff) ? {1'b0, 8'hff, 23'h1} : 32'd0;
                        counter <= 3'd5;
                    end else if ((a[30:23] == 8'hff && a[22:0] == 0) || (b[30:23] == 8'hff && b[22:0] == 0)) begin
                        z <= (a[30:23] == 8'hff) ? {a_sign, 8'hff, 23'd0} : {b_sign, 8'hff, 23'd0};
                        counter <= 3'd5;
                    end else begin
                        product <= a_mantissa * b_mantissa;
                        counter <= 3'd2;
                    end
                end
                3'd2: begin

                    if (product[47:46] >= 2) begin
                        product <= product >> 1;
                        z_exponent <= a_exponent + b_exponent - 9'd127 + 9'd1;
                    end else begin
                        z_exponent <= a_exponent + b_exponent - 9'd127;
                    end
                    z_mantissa <= product[46:24];
                    counter <= 3'd3;
                end
                3'd3: begin

                    guard_bit <= product[23];
                    round_bit <= product[22];
                    sticky <= |product[21:0];

                    if (guard_bit && (round_bit || sticky)) begin
                        if (z_mantissa == 23'd0) begin
                            z_exponent <= z_exponent + 1;
                        end else begin
                            z_mantissa <= z_mantissa + 1;
                        end
                    end
                    counter <= 3'd4;
                end
                3'd4: begin

                    if (z_exponent[8]) begin
                        z <= {z_sign, 8'hff, 23'd0};
                    end else if (z_exponent < 9'd1) begin
                        z <= {z_sign, 8'd0, z_mantissa[22:0]};
                    end else begin
                        z <= {z_sign, z_exponent[7:0], z_mantissa};
                    end
                    counter <= 3'd5;
                end
                default: counter <= 3'd0;
            endcase
        end
    end

