    wire [3:0] wptr_gray = bin2gray(wptr_bin);
    wire wen = winc && !wfull;

    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) wptr_bin <= 0;
        else wptr_bin <= wptr_bin + wen;
    end


    reg [3:0] rptr_bin;
    wire [3:0] rptr_gray = bin2gray(rptr_bin);
    wire ren = rinc && !rempty;

    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) rptr_bin <= 0;
        else rptr_bin <= rptr_bin + ren;
    end


    reg [3:0] rptr_sync1, rptr_sync2;
    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            rptr_sync1 <= 0;
            rptr_sync2 <= 0;
