    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            wptr_sync1 <= 0;
            wptr_sync2 <= 0;
        end else begin
            wptr_sync1 <= wptr_bin;
            wptr_sync2 <= wptr_sync1;
        end
    end


    wire [3:0] rptr_bin_sync = gray2bin(rptr_sync2);
    wire [3:0] wptr_bin_sync = gray2bin(wptr_sync2);


    assign waddr_ram = wptr_bin_sync[2:0];
