module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output [7:0] clock,
    output red,
    output yellow,
    output green
);

parameter idle = 2'b00;
parameter s1_red = 2'b01;
parameter s2_yellow = 2'b10;
parameter s3_green = 2'b11;

reg [7:0] cnt;
reg [1:0] state;
reg p_red, p_yellow, p_green;

assign clock = cnt;
assign red = p_red;
assign yellow = p_yellow;
assign green = p_green;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) state <= idle;
    else begin
        case (state)
            idle: state <= s1_red;
            s1_red: state <= (cnt == 3) ? s3_green : s1_red;
            s3_green: state <= (cnt == 60) ? s2_yellow : s3_green;
            s2_yellow: state <= (cnt == 5) ? s1_red : s2_yellow;
            default: state <= idle;
        endcase
    end
end

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) cnt <= 10;
    else begin
        if (pass_request && green) cnt <= 10;
        else if (!green && p_green) cnt <= 60;
        else if (!yellow && p_yellow) cnt <= 5;
        else if (!red && p_red) cnt <= 10;
        else cnt <= cnt - 1;
    end
end

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        {p_red, p_yellow, p_green} <= 0;
        {red, yellow, green} <= 0;
    end
    else begin
        {p_red, p_yellow, p_green} <= {red, yellow, green};
        case (state)
            s1_red: {red, yellow, green} <= {1'b1, 1'b0, 1'b0};
            s3_green: {red, yellow, green} <= {1'b0, 1'b0, 1'b1};
            s2_yellow: {red, yellow, green} <= {1'b0, 1'b1, 1'b0};
            default: {red, yellow, green} <= {1'b0, 1'b0, 1'b0};
        endcase
    end
end

