module alu (
    input [31:0] a, b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero, carry, negative, overflow, flag
);


    parameter ADD  = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB  = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND  = 6'b100100;
    parameter OR   = 6'b100101;
    parameter XOR  = 6'b100110;
    parameter NOR  = 6'b100111;
    parameter SLT  = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL  = 6'b000000;
    parameter SRL  = 6'b000010;
    parameter SRA  = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI  = 6'b001111;

    reg [32:0] res;


    always @(*) begin
        case (aluc)
            ADD:  res = {1'b0, $signed(a) + $signed(b)};
            ADDU: res = {1'b0, a + b};
            SUB:  res = {1'b0, $signed(a) - $signed(b)};
            SUBU: res = {1'b0, a - b};
            AND:  res = {32'b0, a & b};
            OR:   res = {32'b0, a | b};
            XOR:  res = {32'b0, a ^ b};
            NOR:  res = {32'b0, ~(a | b)};
            SLT:  res = {32'b0, ($signed(a) < $signed(b)) ? 1'b1 : 1'b0};
            SLTU: res = {32'b0, (a < b) ? 1'b1 : 1'b0};
            SLL:  res = {32'b0, a << b[4:0]};
            SRL:  res = {32'b0, a >> b[4:0]};
            SRA:  res = {32'b0, $signed(a) >>> b[4:0]};
            SLLV: res = {32'b0, a << b[4:0]};
            SRLV: res = {32'b0, a >> b[4:0]};
            SRAV: res = {32'b0, $signed(a) >>> b[4:0]};
            LUI:  res = {a[31:16], 16'b0};
            default: res = 33'bz;

        endcase
    end


    assign r = res[31:0];
    assign zero = (r == 32'b0);
    assign negative = r[31];
    assign carry = (aluc == ADD || aluc == SUB) ? res[32] : 1'b0;
    assign overflow = (aluc == ADD || aluc == SUB) ? 
                        (($signed(a[31]) == $signed(b[31])) && (res[31] != a[31])) : 
                        1'b0;
    assign flag = (aluc == SLT || aluc == SLTU) ? r[0] : 1'b0;

endmodule

