module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [3:0] cnt;
reg start_cnt;
reg [7:0] abs_dividend;
reg [7:0] abs_divisor;
reg [15:0] SR;

reg [7:0] quotient;
reg [7:0] remainder;
reg [7:0] neg_divisor;

localparam IDLE = 1'b0;
localparam PROCESSING = 1'b1;
reg state;

always @(posedge clk) begin
    if (rst) begin
        res_valid <= 0;
        state <= IDLE;
        cnt <= 0;
        start_cnt <= 0;
        result <= 0;
        SR <= 0;
        quotient <= 0;
        remainder <= 0;
        abs_dividend <= 0;
        abs_divisor <= 0;
        neg_divisor <= 0;
    end else begin
        case (state)
            IDLE: begin
                if (opn_valid && !res_valid) begin

                    abs_dividend <= sign ? (dividend[7] ? -dividend : dividend) : dividend;
                    abs_divisor <= sign ? (divisor[7] ? -divisor : divisor) : divisor;

                    SR <= {abs_dividend, 1'b0, 7'b0};

                    neg_divisor <= ~abs_divisor + 1;

                    cnt <= 4'd1;
                    start_cnt <= 1'b1;
                    state <= PROCESSING;
                    res_valid <= 1'b0;
                end
            end
            PROCESSING: begin
                if (start_cnt) begin

                    reg [8:0] remainder_part = SR[15:7];

                    reg [8:0] sub_result = remainder_part - neg_divisor;
                    reg carry = ~sub_result[8];


                    if (carry) begin
                        remainder_part = sub_result;
                        quotient <= {quotient[6:0], 1'b1};

                    end else begin
                        quotient <= {quotient[6:0], 1'b0};
                    end


                    SR <= {remainder_part, quotient} << 1;
                    SR[15:8] = remainder_part;

                    cnt <= cnt + 1;
                    if (cnt == 4'd8) begin
                        start_cnt <= 0;
                        state <= IDLE;
                        res_valid <= 1'b1;
                        remainder = remainder_part;
                        quotient = {quotient[6:0], 1'b0};



                        if (sign) begin
                            remainder = dividend[7] ? -remainder : remainder;
                            quotient = (dividend[7] ^ divisor[7]) ? -quotient : quotient;
                        end

                        result <= {remainder, quotient};
                    end
                end
            end
        endcase
    end
end

always @(posedge clk) begin
    if (rst) res_valid <= 0;
    else if (state == IDLE) res_valid <= 0;
end

endmodule

