module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);

reg [15:0] a_reg, b_reg;


always @(*) begin
    a_reg = A;
    b_reg = B;
end


always @(*) begin
    result = 16'b0;
    odd = 16'b0;
    if (b_reg == 8'b0) begin
        result = 16'bx;
        odd = 16'bx;
    end else begin
        reg [15:0] rem = 16'b0;
        reg [15:0] quotient = 16'b0;
        integer i;

        for (i = 15;
 i >= 0;
 i = i - 1) begin
            rem = (rem << 1) | ((a_reg >> i) & 1);

            if (rem[15:8] >= b_reg) begin
                rem[15:8] = rem[15:8] - b_reg;

                quotient[i] = 1'b1;

            end else begin
                quotient[i] = 1'b0;
            end
        end

        result = quotient;
        odd = rem;
    end
end

endmodule

