module fixed_point_adder #(
    parameter Q = 4,
    parameter N = 8
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output wire [N-1:0] c
);

    wire sign_a = a[N-1];
    wire sign_b = b[N-1];
    wire [N-1:0] abs_a = sign_a ? (~a + 1) : a;
    wire [N-1:0] abs_b = sign_b ? (~b + 1) : b;
    wire [N-1:0] sum = a + b;
    wire overflow = (sign_a == sign_b) && (sum[N-1] != sign_a);

    assign c = overflow ? {1'b1, {(N-1){1'b0}}} : sum;

endmodule

