reg [N-1:0] res;
reg [N-1:0] abs_a, abs_b;
reg [N-1:0] res_mag;
reg res_sign;

always @* begin
    if (a[N-1] == b[N-1]) begin

        res = a - b;
        res[N-1] = a[N-1];
    end else begin

        abs_a = a[N-1] ? (~a + 1) : a;
        abs_b = b[N-1] ? (~b + 1) : b;
        if (abs_a > abs_b) begin
            res_mag = abs_a - abs_b;
            res_sign = 1'b0;
        end else if (abs_a < abs_b) begin
            res_mag = abs_b - abs_a;
            res_sign = 1'b1;
        end else begin
            res_mag = 0;
            res_sign = 1'b0;
        end
        res = {res_sign, res_mag};
    end


    if (res == 0)
        res[N-1] = 1'b0;

    c = res;
end

endmodule

