                3'd4: begin

                    {sticky, round_bit} <= {product[1:0]};
                    guard_bit <= product[0];
                    counter <= counter + 1;
                end
                3'd5: begin

                    if (guard_bit && (round_bit || sticky)) begin
                        product[49:26] <= product[49:26] + 1;
                        if (product[49:26] == 24'h1000000) begin 
                            z_exponent <= z_exponent + 1;
                        end
