module sub_64bit (
    input [63:0] A,
    input [63:0] B,
    output [63:0] result,
    output overflow
);

    assign result = A - B;

    wire a_sign = A[63];
    wire b_sign = B[63];
    wire result_sign = result[63];

    wire positive_overflow = (~a_sign) & b_sign & result_sign;
    wire negative_overflow = a_sign & (~b_sign) & ~result_sign;

    assign overflow = positive_overflow | negative_overflow;

endmodule

