wire [3:0] wptr_gray, wptr_gray_reg;
reg [3:0] rptr_syn_1, rptr_syn;



assign wptr_gray = (wptr_bin >> 1) ^ wptr_bin;


always @(posedge wclk) begin
    if (!wrstn) {rptr_syn_1, rptr_syn} <= 8'b0;
    else {rptr_syn_1, rptr_syn} <= {rptr_gray_reg, rptr_syn_1};
end


always @(posedge wclk) begin
    if (!wrstn) wptr_bin <= 4'b0;
    else if (winc && !wfull) wptr_bin <= wptr_bin + 1;
end

assign waddr = wptr_bin[3:0];

assign wen = winc && !wfull;


reg [3:0] rptr_bin;

reg [3:0] rptr_gray_reg, wptr_syn_1, wptr_syn;



assign rptr_gray = (rptr_bin >> 1) ^ rptr_bin;


always @(posedge rclk) begin
    if (!rrstn) {wptr_syn_1, wptr_syn} <= 8'b0;
    else {wptr_syn_1, wptr_syn} <= {wptr_gray_reg, wptr_syn_1};
end


always @(posedge rclk) begin
    if (!rrstn) rptr_bin <= 4'b0;
    else if (rinc && !rempty) rptr_bin <= rptr_bin + 1;
end

assign raddr = rptr_bin[3:0];

assign ren = rinc && !rempty;


always @(posedge rclk) if (!rrstn) rptr_gray_reg <= 4'b0;
always @(posedge wclk) if (!wrstn) wptr_gray_reg <= 4'b0;


assign rempty = (rptr_gray == wptr_syn);
assign wfull = (wptr_gray == {~rptr_syn[3:2], rptr_syn[1:0]}) && 
