module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);


    parameter IDLE = 2'b00;
    parameter STATE1 = 2'b01;
    parameter STATE2 = 2'b10;

    reg [1:0] state;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            state <= IDLE;
            data_out <= 1'b0;
        end else begin
            case (state)
                IDLE: begin
                    data_out <= 1'b0;
                    if (data_in == 1'b0)
                        state <= STATE1;
                    else
                        state <= IDLE;
                end
                STATE1: begin
                    data_out <= 1'b0;
                    if (data_in == 1'b1)
                        state <= STATE2;
                    else
                        state <= IDLE;
                end
                STATE2: begin
                    if (data_in == 1'b0) begin
                        data_out <= 1'b1;
                        state <= IDLE;
                    end else begin
                        data_out <= 1'b0;
                        state <= IDLE;
                    end
                end
                default: begin
                    state <= IDLE;
                    data_out <= 1'b0;
                end
            endcase
        end
    end

endmodule

