module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);

    localparam idle = 2'd0;
    localparam s1_red = 2'd1;
    localparam s2_yellow = 2'd2;
    localparam s3_green = 2'd3;

    reg [1:0] state, next_state;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;
    reg p_red_prev, p_yellow_prev, p_green_prev;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
        end else begin
            state <= next_state;
        end
    end


    always @(*) begin
        case (state)
            idle: next_state = s1_red;
            s1_red: next_state = (cnt == 0) ? s3_green : s1_red;
            s2_yellow: next_state = (cnt == 0) ? s1_red : s2_yellow;
            s3_green: next_state = (cnt == 0) ? s2_yellow : s3_green;
            default: next_state = idle;
        endcase
    end


    always @(*) begin
        case (state)
            idle: begin
                p_red = 0;
                p_yellow = 0;
                p_green = 0;
            end
            s1_red: begin
                p_red = 1;
                p_yellow = 0;
                p_green = 0;
            end
            s2_yellow: begin
                p_red = 0;
                p_yellow = 1;
                p_green = 0;
            end
            s3_green: begin
                p_red = 0;
                p_yellow = 0;
                p_green = 1;
            end
            default: begin
                p_red = 0;
                p_yellow = 0;
                p_green = 0;
            end
        endcase
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            p_red_prev <= 0;
            p_yellow_prev <= 0;
            p_green_prev <= 0;
        end else begin
            p_red_prev <= p_red;
            p_yellow_prev <= p_yellow;
            p_green_prev <= p_green;
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 10;
        end else begin
            if (pass_request && p_green) begin
                cnt <= 10;
            end else if (!p_green && p_green_prev) begin
                cnt <= 60;
            end else if (!p_yellow && p_yellow_prev) begin
                cnt <= 5;
            end else if (!p_red && p_red_prev) begin
                cnt <= 10;
            end else begin
                cnt <= cnt - 1;
            end
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            red <= 0;
            yellow <= 0;
            green <= 0;
        end else begin
            red <= p_red;
            yellow <= p_yellow;
            green <= p_green;
        end
    end


    assign clock = cnt;

endmodule

