module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output reg carry,
    output negative,
    output reg overflow,
    output flag
);


    localparam ADD  = 6'b100000;
    localparam ADDU = 6'b100001;
    localparam SUB  = 6'b100010;
    localparam SUBU = 6'b100011;
    localparam AND  = 6'b100100;
    localparam OR   = 6'b100101;
    localparam XOR  = 6'b100110;
    localparam NOR  = 6'b100111;
    localparam SLT  = 6'b101010;
    localparam SLTU = 6'b101011;
    localparam SLL  = 6'b000000;
    localparam SRL  = 6'b000010;
    localparam SRA  = 6'b000011;
    localparam SLLV = 6'b000100;
    localparam SRLV = 6'b000110;
    localparam SRAV = 6'b000111;
    localparam LUI  = 6'b001111;

    reg [31:0] r_temp;
    reg carry_temp, overflow_temp;

    always @* begin
        case (aluc)
            ADD: begin
                {carry_temp, r_temp} = {1'b0, a} + {1'b0, b};
                overflow_temp = (a[31] == b[31]) && (r_temp[31] != a[31]);
            end
            ADDU: begin
                {carry_temp, r_temp} = {1'b0, a} + {1'b0, b};
                overflow_temp = 1'b0;
            end
            SUB: begin
                {carry_temp, r_temp} = {1'b0, a} - {1'b0, b};
                overflow_temp = (a[31] != b[31]) && (r_temp[31] != a[31]);
            end
            SUBU: begin
                {carry_temp, r_temp} = {1'b0, a} - {1'b0, b};
                overflow_temp = 1'b0;
            end
            AND: begin
                r_temp = a & b;
                carry_temp = 1'b0;
                overflow_temp = 1'b0;
            end
            OR: begin
                r_temp = a | b;
                carry_temp = 1'b0;
                overflow_temp = 1'b0;
            end
            XOR: begin
                r_temp = a ^ b;
                carry_temp = 1'b0;
                overflow_temp = 1'b0;
            end
            NOR: begin
                r_temp = ~(a | b);
                carry_temp = 1'b0;
                overflow_temp = 1'b0;
            end
            SLT: begin
                r_temp = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;
                carry_temp = 1'b0;
                overflow_temp = 1'b0;
            end
            SLTU: begin
                r_temp = (a < b) ? 32'd1 : 32'd0;
                carry_temp = 1'b0;
                overflow_temp = 1'b0;
            end
            SLL: begin
                r_temp = b << a[4:0];
                carry_temp = 1'b0;
                overflow_temp = 1'b0;
            end
            SRL: begin
                r_temp = b >> a[4:0];
                carry_temp = 1'b0;
                overflow_temp = 1'b0;
            end
            SRA: begin
                r_temp = $signed(b) >>> a[4:0];
                carry_temp = 1'b0;
                overflow_temp = 1'b0;
            end
            SLLV: begin
                r_temp = b << a[4:0];
                carry_temp = 1'b0;
                overflow_temp = 1'b0;
            end
            SRLV: begin
                r_temp = b >> a[4:0];
                carry_temp = 1'b0;
                overflow_temp = 1'b0;
            end
            SRAV: begin
                r_temp = $signed(b) >>> a[4:0];
                carry_temp = 1'b0;
                overflow_temp = 1'b0;
            end
            LUI: begin
                r_temp = {a[15:0], 16'b0};
                carry_temp = 1'b0;
                overflow_temp = 1'b0;
            end
            default: begin
                r_temp = 32'bz;
                carry_temp = 1'b0;
                overflow_temp = 1'b0;
            end
        endcase
    end

    assign r = r_temp;
    assign carry = carry_temp;
    assign overflow = overflow_temp;
    assign zero = (r == 32'b0);
    assign negative = r[31];
    assign flag = (aluc == SLT || aluc == SLTU) ? (r == 32'd1) : 1'b0;

endmodule

