module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [7:0] abs_dividend;
    reg [7:0] abs_divisor;
    reg [15:0] SR;
    reg [7:0] NEG_DIVISOR;
    reg [3:0] cnt;
    reg start_cnt;
    reg q_sign;
    reg r_sign;
    reg [7:0] quotient;
    reg [7:0] remainder;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            SR <= 16'b0;
            cnt <= 0;
            start_cnt <= 0;
            abs_dividend <= 0;
            abs_divisor <= 0;
            NEG_DIVISOR <= 0;
            q_sign <= 0;
            r_sign <= 0;
            quotient <= 0;
            remainder <= 0;
        end else begin
            if (opn_valid && !res_valid) begin
                if (sign) begin
                    q_sign <= dividend[7] ^ divisor[7];
                    r_sign <= dividend[7];
                    abs_dividend <= dividend[7] ? -dividend : dividend;
                    abs_divisor <= divisor[7] ? -divisor : divisor;
                end else begin
                    q_sign <= 0;
                    r_sign <= 0;
                    abs_dividend <= dividend;
                    abs_divisor <= divisor;
                end
                NEG_DIVISOR <= -abs_divisor;
                SR <= {abs_dividend, 1'b0} << 1;

                cnt <= 1;
                start_cnt <= 1;
                res_valid <= 0;
            end else if (start_cnt) begin
                if (cnt == 8) begin
                    cnt <= 0;
                    start_cnt <= 0;

                    if (SR[15:8] >= NEG_DIVISOR) begin
                        remainder <= SR[15:8] - NEG_DIVISOR;
                        quotient <= {quotient[6:0], 1'b1};
                    end else begin
                        remainder <= SR[15:8];
                        quotient <= {quotient[6:0], 1'b0};
                    end

                    if (sign) begin
                        if (q_sign) quotient <= ~quotient + 1;
                        if (r_sign) remainder <= ~remainder + 1;
                    end
                    result <= {remainder, quotient};
                    res_valid <= 1;
                end else begin
                    cnt <= cnt + 1;

                    if (SR[15:8] >= NEG_DIVISOR) begin
                        remainder <= SR[15:8] - NEG_DIVISOR;
                        quotient <= {quotient[6:0], 1'b1};
                    end else begin
                        remainder <= SR[15:8];
                        quotient <= {quotient[6:0], 1'b0};
                    end
                    SR <= {remainder << 1, SR[7:0] >> 7};

                end
            end else begin
                res_valid <= 0;
            end
        end
    end

endmodule

