module comparator_4bit (
    input [3:0] A,
    input [3:0] B,
    output A_greater,
    output A_equal,
    output A_less
);

wire [4:0] sub_result = {1'b0, A} - {1'b0, B};
wire borrow = sub_result[4];
wire nonzero = |sub_result[3:0];

assign A_greater = ~borrow & nonzero;
assign A_equal = (sub_result == 5'b0);
assign A_less = borrow;

