module multi_pipe_4bit (
    input clk,
    input rst_n,
    input [3:0] mul_a,
    input [3:0] mul_b,
    output reg [7:0] mul_out
);

parameter size = 4;

wire [7:0] extended_mul_a = {4'b0, mul_a};

wire [7:0] partial_products [0:size-1];

generate
genvar i;
for (i=0;
 i<size;
 i=i+1) begin : gen_partial
    assign partial_products[i] = extended_mul_a << i;
end
endgenerate

reg [7:0] stage1_partial_products [0:size-1];
integer j;


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        for (j=0;
 j<size;
 j=j+1) begin
            stage1_partial_products[j] <= 8'b0;
        end
    end else begin
        for (j=0;
 j<size;
 j=j+1) begin
            stage1_partial_products[j] <= partial_products[j];
        end
    end
end


wire [7:0] sum = stage1_partial_products[0] + stage1_partial_products[1] + 
                 stage1_partial_products[2] + stage1_partial_products[3];

reg [7:0] stage2_sum;


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        stage2_sum <= 8'b0;
        mul_out <= 8'b0;
    end else begin
        stage2_sum <= sum;
        mul_out <= stage2_sum;
    end
end

