module fixed_point_adder #(
    parameter Q = 4,
    parameter N = 8
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

    reg [N-1:0] res;

    always @(*) begin
        wire a_sign = a[N-1];
        wire b_sign = b[N-1];

        if (a_sign == b_sign) begin
            res = a + b;
        end else begin
            wire [N-1:0] a_mag = a_sign ? (~a + 1) : a;
            wire [N-1:0] b_mag = b_sign ? (~b + 1) : b;

            reg [N-1:0] diff;
            reg res_sign;

            if (a_mag > b_mag) begin
                diff = a_mag - b_mag;
                res_sign = a_sign;
            end else if (b_mag > a_mag) begin
                diff = b_mag - a_mag;
                res_sign = b_sign;
            end else begin
                diff = 0;
                res_sign = 0;
            end

            res = {res_sign, diff[N-2:0]};
        end
    end

    assign c = res;

endmodule

