module fixed_point_subtractor #(
    parameter Q = 4,
    parameter N = 8
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

reg [N-1:0] res;
reg sign_res;

always @(*) begin
    reg sign_a = a[N-1];
    reg sign_b = b[N-1];
    reg [N-1:0] abs_a, abs_b, sum;

    if (sign_a == sign_b) begin

        res = a - b;
        sign_res = sign_a;
    end else begin

        abs_a = sign_a ? (~a + 1) : a;
        abs_b = sign_b ? (~b + 1) : b;
        sum = abs_a + abs_b;

        if (abs_a > abs_b)
            sign_res = ~sign_a;
        else
            sign_res = ~sign_b;

        res = sum;
    end


    c = res == 0 ? {1'b0, {(N-1){1'b0}}} : {sign_res, res[N-2:0]};
end

endmodule

