reg [23:0] actual_a_mantissa, actual_b_mantissa;
reg [48:0] product;

reg guard_bit, round_bit, sticky_bit;
reg [9:0] z_exponent;
reg z_sign;
reg [22:0] z_mantissa;

always @(posedge clk) begin
    if (rst) begin
        counter <= 3'd0;
        z <= 32'd0;
    end else begin
        case (counter)
            0: begin

                a_sign <= a[31];
                b_sign <= b[31];
                a_exponent <= a[30:23];
                b_exponent <= b[30:23];
                a_mantissa <= a[22:0];
                b_mantissa <= b[22:0];


                if (a[30:23] == 8'hff && a[22:0] != 0) begin 
                    z <= {a[31], 8'hff, 23'h1};
                    counter <= 3'd0;
                end else if (b[30:23] == 8'hff && b[22:0] != 0) begin 
                    z <= {b[31], 8'hff, 23'h1};
                    counter <= 3'd0;
                end else if (a[30:23] == 8'hff && a[22:0] == 0) begin 
                    if (b[22:0] == 0) begin 
                        z <= {a[31] ^ b[31], 8'hff, 23'd0};
                    end else begin
                        z <= {a[31], 8'hff, 23'd0};
                    end
                    counter <= 3'd0;
                end else if (b[30:23] == 8'hff && b[22:0] == 0) begin 
                    z <= {a[31], 8'hff, 23'd0};
                    counter <= 3'd0;
                end else if (a[30:23] == 0 && a[22:0] == 0 && b[30:23] == 0 && b[22:0] == 0) begin 
                    z <= {a[31] ^ b[31], 31'd0};
                    counter <= 3'd0;
                end else begin
                    counter <= 3'd1;
                end
            end
            1: begin

                actual_a_mantissa <= (a_exponent == 0) ? {1'b0, a_mantissa} : {1'b1, a_mantissa};
                actual_b_mantissa <= (b_exponent == 0) ? {1'b0, b_mantissa} : {1'b1, b_mantissa};
                product <= actual_a_mantissa * actual_b_mantissa;
                counter <= 3'd2;
            end
            2: begin

                if (product[47]) begin
                    product <= product >> 1;
                    z_exponent <= (a_exponent - 127) + (b_exponent - 127) + 1;
                end else begin
                    z_exponent <= (a_exponent - 127) + (b_exponent - 127);
                end

                z_mantissa <= product[46:24];
                guard_bit <= product[23];
                round_bit <= product[22];
                sticky_bit <= |product[21:0];
                counter <= 3'd3;
            end
            3: begin

                if (guard_bit && (round_bit || sticky_bit || z_mantissa[0])) begin
                    z_mantissa <= z_mantissa + 1;

                    if (z_mantissa == 23'h7fffff) begin 
                        z_exponent <= z_exponent + 1;
                        z_mantissa <= 23'd0;
                    end
                end
                counter <= 3'd4;
            end
            4: begin

                if (z_exponent >= 255) begin
                    z <= {z_sign, 8'hff, 23'd0};

                end else if (z_exponent <= 0) begin
                    z <= {z_sign, 31'd0};

                end else begin
                    z <= {z_sign, z_exponent[7:0], z_mantissa};
