    assign FULL = (SP == 3'd0);

    integer i;

    always @(posedge Clk) begin
        if (Rst) begin
            for (i = 0;
 i < 4;
 i = i + 1) begin
                stack_mem[i] <= 4'b0;
            end
            SP <= 3'd4;
        end else if (EN) begin
            if (!FULL) begin
                if (!RW) begin 
                    stack_mem[SP-1] <= dataIn;
                    SP <= SP - 1;
                end else begin 
                    dataOut <= stack_mem[SP];
                    stack_mem[SP] <= 4'b0;
                    SP <= SP + 1;
                end
            end
        end
    end

endmodule

