module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

reg [1:0] state_reg;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        state_reg <= 2'b00;
        data_out <= 1'b0;
    end else begin
        case (state_reg)
            2'b00: begin 
                if (data_in == 1'b0) begin
                    state_reg <= 2'b01;
                    data_out <= 1'b0;
                end else begin
                    state_reg <= 2'b00;
                    data_out <= 1'b0;
                end
            end
            2'b01: begin 
                if (data_in == 1'b1) begin
                    state_reg <= 2'b10;
                    data_out <= 1'b0;
                end else begin
                    state_reg <= 2'b00;
                    data_out <= 1'b0;
                end
            end
            2'b10: begin 
                if (data_in == 1'b0) begin
                    data_out <= 1'b1;
                    state_reg <= 2'b00;
                end else begin
                    data_out <= 1'b0;
                    state_reg <= 2'b00;
                end
            end
            default: begin
                state_reg <= 2'b00;
                data_out <= 1'b0;
            end
        endcase
    end
end

endmodule

