module alu (
    input [31:0] a, b,
    input [5:0] aluc,
    output [31:0] r,
    output zero,
    output carry,
    output negative,
    output overflow,
    output flag
);

parameter ADD  = 6'b100000;
parameter ADDU = 6'b100001;
parameter SUB  = 6'b100010;
parameter SUBU = 6'b100011;
parameter AND  = 6'b100100;
parameter OR   = 6'b100101;
parameter XOR  = 6'b100110;
parameter NOR  = 6'b100111;
parameter SLT  = 6'b101010;
parameter SLTU = 6'b101011;
parameter SLL  = 6'b000000;
parameter SRL  = 6'b000010;
parameter SRA  = 6'b000011;
parameter SLLV = 6'b000100;
parameter SRLV = 6'b000110;
parameter SRAV = 6'b000111;
parameter LUI  = 6'b001111;

reg [32:0] res;
reg overflow_reg, carry_reg, flag_reg;
reg [31:0] r_reg;

assign r = r_reg;
assign zero = (r_reg == 32'b0);
assign negative = r_reg[31];
assign overflow = overflow_reg;
assign carry = carry_reg;
assign flag = flag_reg;

always @(*) begin
    case (aluc)
        ADD: begin
            res = {1'b0, a} + {1'b0, b};
            carry_reg = res[32];
            overflow_reg = (a[31] == b[31]) && (res[31] != a[31]);
        end
        SUB: begin
            res = {1'b0, a} - {1'b0, b};
            carry_reg = res[32];
            overflow_reg = (a[31] != b[31]) && (res[31] != a[31]);
        end
        ADDU: begin
            res = {1'b0, a} + {1'b0, b};
            carry_reg = res[32];
            overflow_reg = 1'b0;
        end
        SUBU: begin
            res = {1'b0, a} - {1'b0, b};
            carry_reg = res[32];
            overflow_reg = 1'b0;
        end
        AND: begin
            res = {33'b0, a & b};
            carry_reg = 1'b0;
            overflow_reg = 1'b0;
        end
        OR: begin
            res = {33'b0, a | b};
            carry_reg = 1'b0;
            overflow_reg = 1'b0;
        end
        XOR: begin
            res = {33'b0, a ^ b};
            carry_reg = 1'b0;
            overflow_reg = 1'b0;
        end
        NOR: begin
            res = {33'b0, ~(a | b)};
            carry_reg = 1'b0;
            overflow_reg = 1'b0;
        end
        SLT: begin
            res = {33'b0, ($signed(a) < $signed(b)) ? 32'b1 : 32'b0};
            carry_reg = 1'b0;
            overflow_reg = 1'b0;
        end
        SLTU: begin
            res = {33'b0, (a < b) ? 32'b1 : 32'b0};
            carry_reg = 1'b0;
            overflow_reg = 1'b0;
        end
        SLL: begin
            res = {33'b0, a} << a[4:0];
            carry_reg = 1'b0;
            overflow_reg = 1'b0;
        end
        SRL: begin
            res = {33'b0, a} >> a[4:0];
            carry_reg = 1'b0;
            overflow_reg = 1'b0;
        end
        SRA: begin
            res = { {32{a[31]}}, a } >>> a[4:0];
            carry_reg = 1'b0;
            overflow_reg = 1'b0;
        end
        SLLV: begin
            res = {33'b0, a} << a[4:0];
            carry_reg = 1'b0;
            overflow_reg = 1'b0;
        end
        SRLV: begin
            res = {33'b0, a} >> a[4:0];
            carry_reg = 1'b0;
            overflow_reg = 1'b0;
        end
        SRAV: begin
            res = { {32{a[31]}}, a } >>> a[4:0];
            carry_reg = 1'b0;
            overflow_reg = 1'b0;
        end
        LUI: begin
            res = {a[15:0], 16'b0};
            carry_reg = 1'b0;
            overflow_reg = 1'b0;
        end
        default: begin
            res = 33'b0;
            carry_reg = 1'b0;
            overflow_reg = 1'b0;
        end
    endcase

    r_reg = res[31:0];
    flag_reg = (aluc == SLT || aluc == SLTU) ? res[0] : 1'b0;
end

endmodule

