module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [15:0] SR;

    reg [3:0] cnt;

    reg start_cnt;

    reg [7:0] abs_dividend;

    reg [7:0] abs_divisor;

    reg [8:0] NEG_DIVISOR;

    reg [7:0] dividend_reg;

    reg [7:0] divisor_reg;

    reg dividend_sign;

    reg divisor_sign;


    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 1'b0;
            SR <= 16'b0;
            cnt <= 4'b0;
            start_cnt <= 1'b0;
            abs_dividend <= 8'b0;
            abs_divisor <= 8'b0;
            NEG_DIVISOR <= 9'b0;
            dividend_reg <= 8'b0;
            divisor_reg <= 8'b0;
            dividend_sign <= 1'b0;
            divisor_sign <= 1'b0;
        end else begin
            if (res_valid) begin
                res_valid <= 1'b0;
            end

            if (opn_valid && !res_valid && !start_cnt) begin

                dividend_reg <= dividend;
                divisor_reg <= divisor;
                dividend_sign <= sign ? dividend[7] : 1'b0;
                divisor_sign <= sign ? divisor[7] : 1'b0;

                if (sign) begin
                    abs_dividend <= dividend[7] ? (~dividend + 1) : dividend;
                    abs_divisor <= divisor[7] ? (~divisor + 1) : divisor;
                end else begin
                    abs_dividend <= dividend;
                    abs_divisor <= divisor;
                end

                NEG_DIVISOR <= -{1'b0, abs_divisor};

                SR <= {abs_dividend, 8'b0} << 1;

                cnt <= 4'd1;
                start_cnt <= 1'b1;
            end

            if (start_cnt) begin
                if (cnt == 4'd8) begin

                    start_cnt <= 1'b0;
                    cnt <= 4'd0;
                    res_valid <= 1'b1;


                    if (sign) begin

                        if (dividend_sign) begin
                            result[15:8] <= ~SR[15:8] + 1;
                        end else begin
                            result[15:8] <= SR[15:8];
                        end


                        if (dividend_sign ^ divisor_sign) begin
                            result[7:0] <= ~SR[7:0] + 1;
                        end else begin
                            result[7:0] <= SR[7:0];
                        end
                    end else begin
                        result <= SR;
                    end
                end else begin

                    reg [8:0] sub_result = SR[15:8] - NEG_DIVISOR;
                    reg [7:0] new_remainder = sub_result[7:0];
                    reg new_bit = sub_result[8] ? 1'b0 : 1'b1;

                    SR[15:8] <= sub_result[8] ? SR[15:8] : new_remainder;
                    SR[7:0] <= {SR[6:0], new_bit};
                    cnt <= cnt + 4'd1;
                end
            end
        end
    end

