always @(*) begin
    a_reg = A;
    b_reg = B;
end


always @(*) begin
    integer i;
    reg [15:0] temp_rem;
    reg [15:0] temp_quo;

    temp_rem = 16'd0;
    temp_quo = 16'd0;

    for (i = 15;
 i >= 0;
 i = i - 1) begin
        temp_rem = {temp_rem[14:0], a_reg[i]};
        if (temp_rem >= {8'd0, b_reg}) begin
            temp_rem = temp_rem - {8'd0, b_reg};
            temp_quo[i] = 1'b1;
        end else begin
            temp_quo[i] = 1'b0;
        end
    end

    result = temp_quo;
    odd = temp_rem;
end

