module fixed_point_adder #(
    parameter Q = 2,
    parameter N = 4
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);

    reg [N-1:0] res;
    reg a_sign, b_sign;
    reg [N-1:0] abs_a, abs_b;
    reg [N-1:0] sum;

    always @(*) begin
        a_sign = a[N-1];
        b_sign = b[N-1];
        abs_a = a_sign ? (~a + 1) : a;
        abs_b = b_sign ? (~b + 1) : b;
        sum = abs_a + abs_b;

        if (a_sign == b_sign) begin
            res = {a_sign, sum};
        end else begin
            if (abs_a > abs_b) begin
                res = {1'b1, abs_a - abs_b};
            end else if (abs_b > abs_a) begin
                res = {1'b0, abs_b - abs_a};
            end else begin
                res = {1'b0, {N-1{1'b0}}};
            end
        end

        c = res;
    end

endmodule

