module fixed_point_subtractor #(
    parameter Q = 4,
    parameter N = 8
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output wire [N-1:0] c
);

    reg [N-1:0] res;
    reg [N-2:0] mag_a, mag_b;
    reg [N-2:0] mag_diff, mag_sum;

    always @(*) begin
        mag_a = a[N-2:0];
        mag_b = b[N-2:0];

        if (a[N-1] == b[N-1]) begin

            mag_diff = mag_a - mag_b;
            if (mag_diff == 0) begin
                res = {1'b0, {(N-1){1'b0}}};
            end else begin
                res = {a[N-1], mag_diff};
            end
        end else begin

            mag_sum = mag_a + mag_b;
            if (mag_a > mag_b) begin
                res = {a[N-1], mag_a - mag_b};
            end else begin
                res = {~a[N-1], mag_b - mag_a};
            end
            if (mag_sum == 0) begin
                res[N-1] = 1'b0;
            end
        end
    end

    assign c = res;

endmodule

