module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

reg [2:0] counter;
reg a_sign, b_sign;
reg [7:0] a_exponent, b_exponent;
reg [22:0] a_mantissa, b_mantissa;
reg [23:0] a_mantissa_full, b_mantissa_full;
reg [47:0] product;
reg [47:0] product_shifted;
reg [9:0] exponent_sum;
reg shift;
reg [22:0] mantissa;
reg guard_bit, round_bit, sticky;
reg [22:0] mantissa_rounded;
reg mantissa_final;
reg sign;

always @(posedge clk) begin
    if (rst) begin
        counter <= 3'b0;
        z <= 32'b0;
        a_sign <= 1'b0;
        b_sign <= 1'b0;
        a_exponent <= 8'b0;
        b_exponent <= 8'b0;
        a_mantissa <= 23'b0;
        b_mantissa <= 23'b0;
        a_mantissa_full <= 24'b0;
        b_mantissa_full <= 24'b0;
        product <= 48'b0;
        product_shifted <= 48'b0;
        exponent_sum <= 10'b0;
        shift <= 1'b0;
        mantissa <= 23'b0;
        guard_bit <= 1'b0;
        round_bit <= 1'b0;
        sticky <= 1'b0;
        mantissa_rounded <= 23'b0;
        mantissa_final <= 1'b0;
        sign <= 1'b0;
    end else begin
        case (counter)
            3'b000: begin

                a_sign <= a[31];
                a_exponent <= a[30:23];
                a_mantissa <= a[22:0];
                b_sign <= b[31];
                b_exponent <= b[30:23];
                b_mantissa <= b[22:0];
                counter <= 3'b001;
            end
            3'b001: begin

                a_mantissa_full <= {1'b1, a_mantissa};
                b_mantissa_full <= {1'b1, b_mantissa};
                product <= a_mantissa_full * b_mantissa_full;
                counter <= 3'b010;
            end
            3'b010: begin

                if (product[47:46] >= 2'b10) begin
                    product_shifted <= product >> 1;
                    exponent_sum <= {1'b0, a_exponent} + {1'b0, b_exponent} - 10'd127 + 10'd1;
                    shift <= 1'b1;
                end else begin
                    product_shifted <= product;
                    exponent_sum <= {1'b0, a_exponent} + {1'b0, b_exponent} - 10'd127;
                    shift <= 1'b0;
                end

                if (shift) begin
                    mantissa <= product_shifted[46:24];
                    guard_bit <= product_shifted[23];
                    round_bit <= product_shifted[22];
                    sticky <= |product_shifted[21:0];
                end else begin
                    mantissa <= product_shifted[47:25];
                    guard_bit <= product_shifted[24];
                    round_bit <= product_shifted[23];
                    sticky <= |product_shifted[22:0];
                end
                counter <= 3'b011;
            end
            3'b011: begin

                sign <= a_sign ^ b_sign;
                if (guard_bit && (round_bit || sticky)) begin
                    mantissa_rounded <= mantissa + 1;
                    if (mantissa_rounded == 23'h7FFFFF) begin
                        mantissa_final <= 23'b0;
                        exponent_sum <= exponent_sum + 1;
                    end else begin
                        mantissa_final <= mantissa_rounded;
                    end
                end else begin
                    mantissa_final <= mantissa;
                end

                if ((a_exponent == 8'hFF && a_mantissa != 0) || 
                    (b_exponent == 8'hFF && b_mantissa != 0)) begin
                    z <= {1'b0, 8'hFF, 23'h1};
                end else if ((a_exponent == 8'hFF && a_mantissa == 0) || 
                            (b_exponent == 8'hFF && b_mantissa == 0)) begin
                    if ((a_exponent == 0 && a_mantissa != 0) || 
                        (b_exponent == 0 && b_mantissa != 0)) begin
                        z <= {1'b0, 8'hFF, 23'h1};
                    end else begin
                        z <= {sign, 8'hFF, 23'b0};
                    end
                end else if (exponent_sum >= 10'd255) begin
                    z <= {sign, 8'hFF, 23'b0};
                end else if (exponent_sum <= 10'd1) begin
                    z <= {sign, 31'b0};
                end else begin
                    z <= {sign, exponent_sum[7:0], mantissa_final};
                end
                counter <= 3'b000;
            end
        endcase
    end
end

endmodule

