            if (!FULL) begin
                stack_mem[SP-1] <= dataIn;
                SP <= SP - 1;
            end
        end
        else begin 
            if (!EMPTY) begin
                dataOut <= stack_mem[SP-1];
                stack_mem[SP-1] <= 4'b0;
                SP <= SP + 1;
            end
        end
    end
end


