module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

localparam S0 = 2'b00,
           S1 = 2'b01,
           S2 = 2'b10;

reg [1:0] state_reg, next_state;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n)
        state_reg <= S0;
    else
        state_reg <= next_state;
end

always @(*) begin
    case (state_reg)
        S0: next_state = (data_in == 1'b0) ? S1 : S0;
        S1: next_state = (data_in == 1'b1) ? S2 : S1;
        S2: next_state = (data_in == 1'b0) ? S0 : S2;
        default: next_state = S0;
    endcase
end

always @(*) begin
    if (state_reg == S2 && data_in == 1'b0)
        data_out = 1'b1;
    else
        data_out = 1'b0;
end

endmodule

