module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output [7:0] clock,
    output red,
    output yellow,
    output green
);

    parameter idle = 2'd0,
              s1_red = 2'd1,
              s2_yellow = 2'd2,
              s3_green = 2'd3;

    reg [1:0] state;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;
    reg r_red, r_yellow, r_green;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
        end else begin
            case (state)
                idle: state <= s1_red;
                s1_red: if (cnt == 8'd3) state <= s3_green;
                s3_green: if (cnt == 8'd3) state <= s2_yellow;
                s2_yellow: if (cnt == 8'd3) state <= s1_red;
                default: state <= idle;
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 8'd10;
        end else begin
            if (pass_request && p_green) begin
                cnt <= (cnt > 8'd10) ? 8'd10 : cnt;
            end else if (!p_green && p_green_prev) begin
                cnt <= 8'd60;
            end else if (!p_yellow && p_yellow_prev) begin
                cnt <= 8'd5;
            end else if (!p_red && p_red_prev) begin
                cnt <= 8'd10;
            end else begin
                cnt <= cnt - 1;
            end
        end
    end


    reg p_green_prev, p_yellow_prev, p_red_prev;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            p_green_prev <= 1'b0;
            p_yellow_prev <= 1'b0;
            p_red_prev <= 1'b0;
        end else begin
            p_green_prev <= p_green;
            p_yellow_prev <= p_yellow;
            p_red_prev <= p_red;
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            r_red <= 1'b0;
            r_yellow <= 1'b0;
            r_green <= 1'b0;
        end else begin
            r_red <= p_red;
            r_yellow <= p_yellow;
            r_green <= p_green;
        end
    end


    always @(*) begin
        case (state)
            idle: {p_red, p_yellow, p_green} = 3'b000;
            s1_red: {p_red, p_yellow, p_green} = 3'b100;
            s3_green: {p_red, p_yellow, p_green} = 3'b001;
            s2_yellow: {p_red, p_yellow, p_green} = 3'b010;
            default: {p_red, p_yellow, p_green} = 3'b000;
        endcase
    end

    assign red = r_red;
    assign yellow = r_yellow;
    assign green = r_green;
    assign clock = cnt;

endmodule

