module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [15:0] SR;
    reg [3:0] cnt;
    reg start_cnt;
    reg [7:0] abs_dividend, abs_divisor;
    reg [8:0] neg_divisor;
    reg dividend_sign, divisor_sign, quotient_sign, remainder_sign;

    wire [7:0] a_dividend = sign ? (dividend[7] ? -dividend : dividend) : dividend;
    wire [7:0] a_divisor = sign ? (divisor[7] ? -divisor : divisor) : divisor;

    always @(posedge clk) begin
        if (rst) begin
            SR <= 16'b0;
            cnt <= 4'b0;
            start_cnt <= 1'b0;
            res_valid <= 1'b0;
            abs_dividend <= 8'b0;
            abs_divisor <= 8'b0;
            neg_divisor <= 9'b0;
            dividend_sign <= 1'b0;
            divisor_sign <= 1'b0;
            quotient_sign <= 1'b0;
            remainder_sign <= 1'b0;
            result <= 16'b0;
        end else begin
            if (opn_valid && !res_valid) begin
                abs_dividend <= a_dividend;
                abs_divisor <= a_divisor;
                if (sign) begin
                    dividend_sign <= dividend[7];
                    divisor_sign <= divisor[7];
                    quotient_sign <= dividend[7] ^ divisor[7];
                    remainder_sign <= dividend[7];
                end else begin
                    dividend_sign <= 1'b0;
                    divisor_sign <= 1'b0;
                    quotient_sign <= 1'b0;
                    remainder_sign <= 1'b0;
                end
                SR <= {8'b0, a_dividend} << 1;
                neg_divisor <= -{1'b0, a_divisor};
                cnt <= 4'd1;
                start_cnt <= 1'b1;
                res_valid <= 1'b0;
            end else if (start_cnt) begin
                if (cnt == 4'd8) begin
                    start_cnt <= 1'b0;
                    cnt <= 4'b0;
                    res_valid <= 1'b1;
                    if (sign) begin
                        result[15:8] <= remainder_sign ? -SR[15:8] : SR[15:8];
                        result[7:0] <= quotient_sign ? -SR[7:0] : SR[7:0];
                    end else begin
                        result[15:8] <= SR[15:8];
                        result[7:0] <= SR[7:0];
                    end
                end else begin
                    wire [8:0] sub_result = {1'b0, SR[15:8]} - {1'b0, abs_divisor};
                    wire quotient_bit = ~sub_result[8];
                    wire [7:0] new_remainder = quotient_bit ? sub_result[7:0] : SR[15:8];
                    SR <= {SR[14:0], 1'b0};
                    SR[15:8] <= new_remainder;
                    SR[0] <= quotient_bit;
                    cnt <= cnt + 1;
                end
            end
            if (res_valid) res_valid <= 1'b0;
        end
    end

endmodule

