module fixed_point_adder #(parameter Q, N) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

reg [N-1:0] res;
wire sign_a = a[N-1];
wire sign_b = b[N-1];
wire [N-1:0] abs_a = sign_a ? (~a + 1) : a;
wire [N-1:0] abs_b = sign_b ? (~b + 1) : b;

always @(*) begin
    if (sign_a == sign_b) begin

        reg [N-1:0] sum = abs_a + abs_b;
        res = {sign_a, sum[N-2:0]};
    end else begin

        if (abs_a > abs_b) begin
            reg [N-1:0] diff = abs_a - abs_b;
            res = {sign_a, diff[N-2:0]};
        end else begin
            reg [N-1:0] diff = abs_b - abs_a;
            res = {sign_b, diff[N-2:0]};
        end
    end
end

assign c = res;

endmodule

