module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent, z_exponent;
    reg [22:0] a_mantissa, b_mantissa;
    reg [47:0] product;
    reg guard_bit, round_bit, sticky;
    reg [23:0] z_mantissa;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'b0;
            a_sign <= 0;
            b_sign <= 0;
            z_sign <= 0;
            a_exponent <= 0;
            b_exponent <= 0;
            z_exponent <= 0;
            a_mantissa <= 0;
            b_mantissa <= 0;
            product <= 48'b0;
            guard_bit <= 0;
            round_bit <= 0;
            sticky <= 0;
            z_mantissa <= 24'b0;
        end else begin
            case (counter)
                3'b000: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= a[22:0];
                    b_mantissa <= b[22:0];

                    if ((a_exponent == 8'hff && |a_mantissa) || (b_exponent == 8'hff && |b_mantissa)) begin

                        z_sign <= a_sign ^ b_sign;
                        z_exponent <= 8'hff;
                        z_mantissa <= 24'h400000;

                    end else if (a_exponent == 8'hff || b_exponent == 8'hff) begin

                        z_sign <= a_sign ^ b_sign;
                        z_exponent <= 8'hff;
                        z_mantissa <= 24'b0;
                    end else if ((a_exponent == 8'h00 && a_mantissa == 0) || (b_exponent == 8'h00 && b_mantissa == 0)) begin

                        z_sign <= a_sign ^ b_sign;
                        z_exponent <= 8'h00;
                        z_mantissa <= 24'b0;
                    end else begin

                        z_exponent <= a_exponent + b_exponent - 8'd127;
                        a_mantissa <= {1'b1, a_mantissa};
                        b_mantissa <= {1'b1, b_mantissa};
                        product <= a_mantissa * b_mantissa;
                        counter <= 3'b001;
                    end
                end

                3'b001: begin

                    integer i;
                    reg [5:0] leading_one;
                    reg [47:0] product_shifted;
                    reg [7:0] shift;

                    leading_one = 6'd47;
                    for (i = 47;
 i >= 0;
 i = i - 1) begin
                        if (product[i]) begin
                            leading_one = i;
                            break;
                        end
                    end

                    if (product == 48'b0) begin
                        z_exponent <= 8'h00;
                        z_mantissa <= 24'b0;
                    end else begin
                        shift = 47 - leading_one;
                        product_shifted = product << shift;
                        z_exponent <= z_exponent - shift;
                        guard_bit <= product_shifted[23];
                        round_bit <= product_shifted[22];
                        sticky <= |product_shifted[21:0];

                        if (guard_bit) begin
                            if (round_bit || sticky) begin
                                z_mantissa <= product_shifted[46:24] + 1;
                                if (z_mantissa[23]) begin
