module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [7:0] dividend_reg, divisor_reg;
    reg [7:0] abs_dividend, abs_divisor;
    reg [7:0] neg_divisor;
    reg [15:0] SR;

    reg [3:0] cnt;
    reg start_cnt;
    wire dividend_sign, divisor_sign, quotient_sign, remainder_sign;
    wire [8:0] sub_result;
    wire carry_out;
    wire [7:0] new_remainder;

    assign dividend_sign = sign ? dividend_reg[7] : 1'b0;
    assign divisor_sign = sign ? divisor_reg[7] : 1'b0;
    assign quotient_sign = dividend_sign ^ divisor_sign;
    assign remainder_sign = dividend_sign;

    assign sub_result = SR[15:8] - neg_divisor;
    assign carry_out = ~sub_result[8];
    assign new_remainder = sub_result[7:0];

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 1'b0;
            SR <= 16'b0;
            cnt <= 4'b0;
            start_cnt <= 1'b0;
            dividend_reg <= 8'b0;
            divisor_reg <= 8'b0;
            abs_dividend <= 8'b0;
            abs_divisor <= 8'b0;
            neg_divisor <= 8'b0;
        end else begin
            if (res_valid) begin
                res_valid <= 1'b0;
            end

            if (~res_valid) begin
                if (opn_valid) begin

                    dividend_reg <= dividend;
                    divisor_reg <= divisor;
                    abs_dividend <= sign ? (dividend[7] ? (~dividend + 1) : dividend) : dividend;
                    abs_divisor <= sign ? (divisor[7] ? (~divisor + 1) : divisor) : divisor;
                    neg_divisor <= ~abs_divisor + 1;

                    SR <= {abs_dividend, 1'b0} << 7;

                    cnt <= 4'd1;
                    start_cnt <= 1'b1;
                end

                if (start_cnt) begin
                    if (cnt == 4'd8) begin

                        if (sign) begin

                            if (quotient_sign)
                                result[7:0] <= ~SR[7:0] + 1;
                            else
                                result[7:0] <= SR[7:0];


                            if (remainder_sign)
                                result[15:8] <= ~SR[15:8] + 1;
                            else
                                result[15:8] <= SR[15:8];
                        end else begin
                            result <= SR;
                        end

                        res_valid <= 1'b1;
                        start_cnt <= 1'b0;
                        cnt <= 4'd0;
                    end else begin
                        if (carry_out) begin
                            SR <= {new_remainder, SR[7:0] >> 1, 1'b1};
                        end else begin
                            SR <= {SR[15:8] - abs_divisor, SR[7:0] >> 1, 1'b0};
                        end
                        cnt <= cnt + 1;
                    end
                end
            end
        end
    end

endmodule

