module div_16bit(
    input [15:0] A,
    input [7:0] B,
    output [15:0] result,
    output [15:0] odd
);

    reg [15:0] a_reg, b_reg;
    reg [15:0] result_reg;
    reg [15:0] odd_reg;


    always @(*) begin
        a_reg = A;
        b_reg = B;
    end


    always @(*) begin
        reg [15:0] rem;
        reg [15:0] quo;
        integer i;

        rem = 0;
        quo = 0;

        for (i = 15;
 i >= 0;
 i = i - 1) begin
            rem = (rem << 1) | ((a_reg >> i) & 1);
            if (rem >= b_reg) begin
                rem = rem - b_reg;
                quo[i] = 1;
            end
        end

        result_reg = quo;
        odd_reg = rem;
    end

    assign result = result_reg;
    assign odd = odd_reg;

endmodule

