module cla_16bit (
    input [16:1] A,
    input [16:1] B,
    input C_in,
    output [16:1] S,
    output C_out,
    output G_group,
    output P_group
);

wire [16:1] P, G;
wire [16:1] C;
wire [16:1] P_prefix, G_prefix;

assign P = A ^ B;
assign G = A & B;

assign P_group = &P;
assign P_prefix[1] = P[1];
assign G_prefix[1] = G[1];

genvar i;
generate
    for (i = 2;
 i <= 16;
 i = i + 1) begin : prefix
        assign P_prefix[i] = P[i] & P_prefix[i-1];
        assign G_prefix[i] = G[i] | (P[i] & G_prefix[i-1]);
    end
endgenerate

assign G_group = G_prefix[16];
assign C_out = (P_group & C_in) | G_group;

assign C[1] = G[1] | (P[1] & C_in);
generate
    for (i = 2;
 i <= 16;
 i = i + 1) begin : carry
        assign C[i] = G_prefix[i] | (P_prefix[i] & C[i-1]);
    end
endgenerate

assign S = P ^ C[16:1];

endmodule

