        valid_out <= 1'b0;

        if (valid_in) begin

            reg [9:0] next_sum = sum_reg + data_in;
            reg [2:0] next_count = count_reg + 1;

            if (next_count == 3'd4) begin

                data_out <= next_sum;
                valid_out <= 1'b1;
                sum_reg <= 10'b0;
                count_reg <= 3'b0;
            end else begin
                sum_reg <= next_sum;
                count_reg <= next_count;
            end
        end
    end
end

endmodule

