module fixed_point_adder #(
    parameter Q = 3,
    parameter N = 8
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

reg [N-1:0] res;
wire a_sign = a[N-1];
wire b_sign = b[N-1];
wire [N-1:0] a_mag = a_sign ? (~a + 1) : a;
wire [N-1:0] b_mag = b_sign ? (~b + 1) : b;

wire same_sign = (a_sign == b_sign);
wire a_large = (a_mag > b_mag);
wire [N-1:0] sub_res = a_large ? (a_mag - b_mag) : (b_mag - a_mag);
wire sub_sign = a_large ? 1'b0 : (b_sign ? 1'b1 : 1'b0);

always @(*) begin
    if (same_sign) begin

        wire [N-1:0] sum_mag = a_mag + b_mag;
        res = {a_sign, sum_mag[N-2:0]};
    end else begin

        res = {sub_sign, sub_res[N-2:0]};
    end
end

assign c = res;

endmodule

