module fixed_point_subtractor #(
    parameter Q = 8,
    parameter N = 16
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

reg [N-1:0] res;

wire sign_a = a[N-1];
wire sign_b = b[N-1];

wire [N-1:0] abs_a = sign_a ? (~a + 1) : a;
wire [N-1:0] abs_b = sign_b ? (~b + 1) : b;

reg [N-1:0] res_magnitude;
reg res_sign;

always @(*) begin
    if (sign_a == sign_b) begin

        res_magnitude = a - b;
        res_sign = sign_a;
    end else begin

        if (abs_a > abs_b) begin
            res_magnitude = abs_a - abs_b;
            res_sign = sign_a;
        end else begin
            res_magnitude = abs_b - abs_a;
            res_sign = sign_b;
        end
    end


    if (res_magnitude == 0) begin
        res_sign = 1'b0;
    end
end

assign res = {res_sign, res_magnitude};
assign c = res;

endmodule

