module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent, z_exponent;
    reg [23:0] a_mantissa, b_mantissa;
    reg [48:0] product;
    reg guard_bit, round_bit, sticky;
    reg [22:0] z_mantissa;
    reg [7:0] z_exponent_adj;
    reg overflow;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'b0;
            a_sign <= 1'b0;
            b_sign <= 1'b0;
            a_exponent <= 8'b0;
            b_exponent <= 8'b0;
            a_mantissa <= 24'b0;
            b_mantissa <= 24'b0;
            product <= 49'b0;
            guard_bit <= 1'b0;
            round_bit <= 1'b0;
            sticky <= 1'b0;
            z_mantissa <= 23'b0;
            z_exponent_adj <= 8'b0;
            overflow <= 1'b0;
        end else begin
            case (counter)
                3'd0: begin
                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= (a[30:23] == 8'b0) ? {1'b0, a[22:0]} : {1'b1, a[22:0]};
                    b_mantissa <= (b[30:23] == 8'b0) ? {1'b0, b[22:0]} : {1'b1, b[22:0]};
                    counter <= 3'd1;
                end
                3'd1: begin
                    if ((a[30:23] == 8'hff && a[22:0] != 0) || (b[30:23] == 8'hff && b[22:0] != 0)) begin
                        z <= {a_sign ^ b_sign, 8'hff, 1'b0, 22'b0};
                        counter <= 3'd0;
                    end else if ((a[30:23] == 8'hff && a[22:0] == 0) || (b[30:23] == 8'hff && b[22:0] == 0)) begin
                        if ((a[30:23] == 8'hff && a[22:0] == 0) && (b[30:23] == 8'b0)) begin
                            z <= {a_sign ^ b_sign, 8'hff, 1'b0, 22'b0};
                        end else begin
                            z <= {a_sign ^ b_sign, 8'hff, 23'b0};
                        end
                        counter <= 3'd0;
                    end else if ((a[30:23] == 8'b0 && a_mantissa == 24'b0) && (b[30:23] == 8'b0 && b_mantissa == 24'b0)) begin
                        z <= {a_sign ^ b_sign, 31'b0};
                        counter <= 3'd0;
                    end else begin
                        product <= a_mantissa * b_mantissa;
                        counter <= 3'd2;
                    end
                end
                3'd2: begin
                    if (product[48]) begin
                        product <= product >> 1;
                        z_exponent_adj <= a_exponent + b_exponent + 8'd1;
                    end else begin
                        z_exponent_adj <= a_exponent + b_exponent;
                    end
                    counter <= 3'd3;
                end
                3'd3: begin
                    guard_bit <= product[47];
                    round_bit <= product[46];
                    sticky <= |product[45:0];
                    if (guard_bit && (round_bit || sticky || product[47])) begin
                        product[23:0] = product[23:0] + 1;
                        overflow <= (product[23:0] == 24'b0);
                    end
                    z_mantissa <= product[23:1];
                    counter <= 3'd4;
                end
                3'd4: begin
                    if (overflow) z_exponent_adj <= z_exponent_adj + 8'd1;
                    if (z_exponent_adj >= 8'd255) begin
                        z <= {a_sign ^ b_sign, 8'hff, 23'b0};
                    end else if (z_exponent_adj <= 8'd1) begin
                        z <= {a_sign ^ b_sign, 31'b0};
                    end else begin
                        z <= {a_sign ^ b_sign, z_exponent_adj - 8'd127, z_mantissa};
                    end
                    counter <= 3'd0;
                end
                default: counter <= 3'd0;
            endcase
        end
    end

endmodule

