);


    reg [3:0] waddr_bin, raddr_bin;
    wire [3:0] wptr, rptr;


    reg [3:0] rptr_sync1, rptr_sync2;
    wire [3:0] rptr_sync;
    reg [3:0] wptr_sync1, wptr_sync2;
    wire [3:0] wptr_sync;


    function [3:0] bin2gray(input [3:0] bin);
        bin2gray = bin ^ (bin >> 1);
    endfunction

    assign wptr = bin2gray(waddr_bin);
    assign rptr = bin2gray(raddr_bin);


    dual_port_RAM #(
        .WIDTH(WIDTH),
        .DEPTH(DEPTH)
    ) ram (
        .wclk(wclk),
        .wenc(winc && !wfull),
        .waddr(waddr_bin),
        .wdata(wdata),
        .rclk(rclk),
        .renc(rinc && !rempty),
        .raddr(raddr_bin),
        .rdata(rdata)
    );


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            rptr_sync1 <= 4'b0;
            rptr_sync2 <= 4'b0;
        end else begin
            rptr_sync1 <= rptr;
            rptr_sync2 <= rptr_sync1;
        end
    end
    assign rptr_sync = rptr_sync2;


    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            wptr_sync1 <= 4'b0;
            wptr_sync2 <= 4'b0;
        end else begin
            wptr_sync1 <= wptr;
            wptr_sync2 <= wptr_sync1;
        end
    end
    assign wptr_sync = wptr_sync2;


    assign rempty = (rptr == rptr_sync);
    assign wfull = (wptr[3] != wptr_sync[3]) && (wptr[2:0] == wptr_sync[2:0]);


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn)
            waddr_bin <= 4'b0;
        else if (winc && !wfull)
            waddr_bin <= waddr_bin + 1;
