module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);


    localparam S0 = 2'b00;
    localparam S1 = 2'b01;
    localparam S2 = 2'b10;

    reg [1:0] current_state;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            current_state <= S0;
            data_out <= 1'b0;
        end else begin
            case (current_state)
                S0: begin
                    if (data_in) begin
                        current_state <= S1;
                    end else begin
                        current_state <= S0;
                    end
                    data_out <= 1'b0;
                end
                S1: begin
                    if (!data_in) begin
                        current_state <= S2;
                    end else begin
                        current_state <= S1;
                    end
                    data_out <= 1'b0;
                end
                S2: begin
                    current_state <= S0;
                    data_out <= (data_in == 1'b0) ? 1'b1 : 1'b0;
                end
                default: begin
                    current_state <= S0;
                    data_out <= 1'b0;
                end
            endcase
        end
    end

endmodule

