module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output [7:0] clock,
    output red,
    output yellow,
    output green
);

parameter idle = 2'b00;
parameter s1_red = 2'b01;
parameter s2_yellow = 2'b10;
parameter s3_green = 2'b11;

reg [1:0] state;
reg [7:0] cnt;
reg p_red, p_yellow, p_green;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= idle;
    end else begin
        case (state)
            idle: state <= s1_red;
            s1_red: if (cnt == 8'd0) state <= s3_green;
            s3_green: if (cnt == 8'd0) state <= s2_yellow;
            s2_yellow: if (cnt == 8'd0) state <= s1_red;
            default: state <= idle;
        endcase
    end
end

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        cnt <= 8'd10;
    end else begin
        if (pass_request && green) begin
            if (cnt > 8'd10) begin
                cnt <= 8'd10;
            end
        end else if (green == 1'b0 && p_green == 1'b1) begin
            cnt <= 8'd60;
        end else if (yellow == 1'b0 && p_yellow == 1'b1) begin
            cnt <= 8'd5;
        end else if (red == 1'b0 && p_red == 1'b1) begin
            cnt <= 8'd10;
        end else begin
            cnt <= cnt - 1'b1;
        end
    end
end

assign clock = cnt;

assign red = (state == s1_red);
assign yellow = (state == s2_yellow);
assign green = (state == s3_green);

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        p_red <= 0;
        p_yellow <= 0;
        p_green <= 0;
    end else begin
        p_red <= red;
        p_yellow <= yellow;
        p_green <= green;
    end
end

endmodule

