module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output carry,
    output negative,
    output overflow,
    output flag
);

    parameter ADD = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND = 6'b100100;
    parameter OR = 6'b100101;
    parameter XOR = 6'b100110;
    parameter NOR = 6'b100111;
    parameter SLT = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL = 6'b000000;
    parameter SRL = 6'b000010;
    parameter SRA = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI = 6'b001111;

    reg [32:0] add_result, sub_result, addu_result, subu_result;
    wire [31:0] slt_result, sltu_result;
    wire [31:0] shift_amount;


    assign zero = (r == 32'b0);
    assign negative = r[31];


    assign flag = (aluc == SLT || aluc == SLTU) ? 1'b1 : 1'bz;


    wire carry_add = add_result[32];
    wire overflow_add = (a[31] == b[31]) && (add_result[31] != a[31]);

    wire carry_sub = sub_result[32];
    wire overflow_sub = (a[31] != b[31]) && (sub_result[31] != a[31]);

    wire carry_addu = addu_result[32];
    wire carry_subu = subu_result[32];


    always @(*) begin
        case(aluc)
            ADD: begin
                {carry_add, r} = {1'b0, a} + {1'b0, b};
                overflow = overflow_add;
            end
            ADDU: begin
                {carry_addu, r} = {1'b0, a} + {1'b0, b};
                overflow = 1'b0;
            end
            SUB: begin
                {carry_sub, r} = {1'b0, a} - {1'b0, b};
                overflow = overflow_sub;
            end
            SUBU: begin
                {carry_subu, r} = {1'b0, a} - {1'b0, b};
                overflow = 1'b0;
            end
            AND: r = a & b;
            OR: r = a | b;
            XOR: r = a ^ b;
            NOR: r = ~(a | b);
            SLT: r = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;
            SLTU: r = (a < b) ? 32'd1 : 32'd0;
            SLL: r = a << a[4:0];
            SRL: r = a >> a[4:0];
            SRA: r = $signed(a) >>> a[4:0];
            SLLV: r = a << a[4:0];
            SRLV: r = a >> a[4:0];
            SRAV: r = $signed(a) >>> a[4:0];
            LUI: r = {a[31:16], 16'b0};
            default: r = 32'bz;
        endcase
    end

    assign carry = (aluc == ADD) ? carry_add :
                   (aluc == ADDU) ? carry_addu :
                   (aluc == SUB) ? carry_sub :
                   (aluc == SUBU) ? carry_subu :
                   (aluc == SLL || aluc == SRL || aluc == SRA ||
                    aluc == SLLV || aluc == SRLV || aluc == SRAV) ? 1'b0 :
                   1'b0;

endmodule

