module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [15:0] SR;
    reg [3:0] cnt;
    reg start_cnt;
    reg [7:0] abs_dividend, abs_divisor;
    reg sign_quotient, sign_remainder;
    reg [8:0] NEG_DIVISOR;

    reg res_valid_reg;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            SR <= 0;
            cnt <= 0;
            start_cnt <= 0;
            abs_dividend <= 0;
            abs_divisor <= 0;
            sign_quotient <= 0;
            sign_remainder <= 0;
            NEG_DIVISOR <= 0;
        end else begin
            if (opn_valid && !res_valid) begin

                if (sign) begin
                    abs_dividend <= dividend[7] ? -dividend : dividend;
                    abs_divisor <= divisor[7] ? -divisor : divisor;
                    sign_quotient <= dividend[7] ^ divisor[7];
                    sign_remainder <= dividend[7];
                end else begin
                    abs_dividend <= dividend;
                    abs_divisor <= divisor;
                    sign_quotient <= 0;
                    sign_remainder <= 0;
                end
                NEG_DIVISOR <= ~{1'b0, abs_divisor} + 1;

                SR <= {8'b0, abs_dividend, 1'b0};

                cnt <= 1;
                start_cnt <= 1;
                res_valid <= 0;
            end else if (start_cnt && cnt < 8) begin

                reg [8:0] sub_result = SR[15:8] - NEG_DIVISOR[7:0];
                if (sub_result[8]) begin 
                    SR <= {sub_result[7:0], SR[7:1]};
                end else begin 
                    SR <= {sub_result, SR[7:1] | 1'b1};
                end
                cnt <= cnt + 1;
            end else if (start_cnt && cnt == 8) begin

                reg [7:0] rem = SR[15:8];
                reg [7:0] quo = SR[7:0];
                reg [7:0] rem_signed = sign_remainder ? -rem : rem;
                reg [7:0] quo_signed = sign_quotient ? -quo : quo;
                result <= {rem_signed, quo_signed};
                res_valid <= 1;
                start_cnt <= 0;
                cnt <= 0;
            end

            if (opn_valid && !res_valid) begin
                res_valid <= 0;
            end
        end
    end

endmodule

