module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);

reg [15:0] a_reg;
reg [7:0] b_reg;

always @(*) begin
    a_reg = A;
    b_reg = B;
end

always @(*) begin
    reg [15:0] div = a_reg;
    reg [15:0] rem = 16'b0;
    result = 16'b0;

    for (int i = 15;
 i >= 0;
 i = i - 1) begin
        rem = {rem[14:0], div[15]};
        div = {div[14:0], 1'b0};
        if (rem >= {8'b0, b_reg}) begin
            result[i] = 1'b1;
            rem = rem - {8'b0, b_reg};
        end else begin
            result[i] = 1'b0;
        end
    end

    odd = rem;
end

endmodule

