    input rst_n,
    input start,
    input [15:0] ain,
    input [15:0] bin,
    output [31:0] yout,
    output done
);

reg [15:0] areg, breg;
reg [4:0] i;
reg [31:0] yout_r;
reg done_r;

assign yout = yout_r;
assign done = done_r;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        i <= 5'd0;
        areg <= 16'd0;
        breg <= 16'd0;
        yout_r <= 32'd0;
        done_r <= 1'b0;
    end else begin

        if (start) begin
            if (i < 5'd17)
                i <= i + 1'd1;
        end else
            i <= 5'd0;


        if (start && (i == 5'd0)) begin
            areg <= ain;
            breg <= bin;
        end


        if (start && (i >= 5'd1) && (i <= 5'd16)) begin
            if (areg[i-1])
                yout_r <= yout_r + (breg << (i-1));
        end


        if (i == 5'd16)
            done_r <= 1'b1;
        else if (i == 5'd17)
            done_r <= 1'b0;
        else
            done_r <= done_r;
    end
end

endmodule

