    input [4:1] A,
    input [4:1] B,
    input C_in,
    output [4:1] S,
    output P_group,
    output G_group,
    output C_out
);
    wire [4:1] P, G;
    wire [5:1] C;

    assign C[1] = C_in;


    assign P[1] = A[1] ^ B[1];
    assign G[1] = A[1] & B[1];
    assign P[2] = A[2] ^ B[2];
    assign G[2] = A[2] & B[2];
    assign P[3] = A[3] ^ B[3];
    assign G[3] = A[3] & B[3];
    assign P[4] = A[4] ^ B[4];
    assign G[4] = A[4] & B[4];


    assign C[2] = G[2] | (P[2] & C[1]);
    assign C[3] = G[3] | (P[3] & C[2]);
    assign C[4] = G[4] | (P[4] & C[3]);


    assign P_group = &P;
    assign G_group = G[4] | (P[4] & G[3]) | (P[4] & P[3] & G[2]) | (P[4] & P[3] & P[2] & G[1]);


    assign S[1] = P[1] ^ C[1];
    assign S[2] = P[2] ^ C[2];
    assign S[3] = P[3] ^ C[3];
    assign S[4] = P[4] ^ C[4];


    assign C_out = G_group | (P_group & C_in);
endmodule

