module accu (
    input clk,
    input rst_n,
    input [7:0] data_in,
    input valid_in,
    output reg [9:0] data_out,
    output reg valid_out
);

reg [9:0] accumulator_reg;
reg [1:0] count_reg;

wire [9:0] sum_next = valid_in ? accumulator_reg + data_in : accumulator_reg;
wire [1:0] count_next = valid_in ? count_reg + 1 : count_reg;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        accumulator_reg <= 10'b0;
        count_reg <= 2'b0;
    end else begin
        accumulator_reg <= sum_next;
        count_reg <= count_next;
    end
end

always @(*) begin
    if (count_reg == 2'b11 && valid_in) begin
        data_out = sum_next;
        valid_out = 1'b1;
    end else begin
        data_out = 10'b0;
        valid_out = 1'b0;
    end
end

endmodule

