module fixed_point_adder #(
    parameter Q = 2, 
    parameter N = 4  
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

reg [N-1:0] res;

always @(*) begin
    if (a[N-1] == b[N-1]) begin

        res = a + b;
    end else begin

        reg [N-1:0] a_abs = a[N-1] ? (~a + 1) : a;
        reg [N-1:0] b_abs = b[N-1] ? (~b + 1) : b;
        reg [N-1:0] difference;

        if (a_abs > b_abs) begin
            difference = a_abs - b_abs;
            res = {1'b0, difference[N-2:0]};

        end else if (b_abs > a_abs) begin
            difference = b_abs - a_abs;
            res = {1'b1, difference[N-2:0]};

        end else begin
            res = 0;
        end
    end
    c = res;
end

endmodule

