module fixed_point_subtractor #(
    parameter Q = 4,
    parameter N = 8
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

reg [N-1:0] res;
reg a_sign, b_sign;
reg [N-1:0] a_abs, b_abs;
reg [N-1:0] sum_abs;
reg sum_sign;

always @(*) begin
    a_sign = a[N-1];
    b_sign = b[N-1];

    if (a_sign == b_sign) begin

        res = a - b;
        if (res == 0)
            res[N-1] = 0;

        else
            res[N-1] = a_sign;

    end else begin

        a_abs = a_sign ? (~a + 1) : a;
        b_abs = b_sign ? (~b + 1) : b;
        sum_abs = a_abs + b_abs;

        if (a_abs > b_abs)
            sum_sign = a_sign;
        else
            sum_sign = b_sign;


        res = sum_sign ? (~sum_abs + 1) : sum_abs;


        if (sum_abs == 0)
            res[N-1] = 0;
        else
            res[N-1] = sum_sign;
    end

    c = res;
end

endmodule

