module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg [31:0] a_reg, b_reg;
    reg a_sign, b_sign;
    reg [7:0] a_exponent, b_exponent;
    reg [23:0] a_mantissa, b_mantissa;
    reg [49:0] product;
    reg [22:0] mantissa_rounded;
    reg [9:0] exponent_rounded;
    reg sign;
    reg guard_bit, round_bit, sticky;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'b0;
        end else begin
            case (counter)
                3'b000: begin

                    a_reg <= a;
                    b_reg <= b;
                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= (a[30:23] == 8'b0) ? {1'b0, a[22:0]} : {1'b1, a[22:0]};
                    b_mantissa <= (b[30:23] == 8'b0) ? {1'b0, b[22:0]} : {1'b1, b[22:0]};
                    counter <= counter + 1;
                end
                3'b001: begin

                    if ((a_exponent == 8'hff && |a_mantissa) || (b_exponent == 8'hff && |b_mantissa)) begin

                        z <= 32'h7fc00000;
                    end else if ((a_exponent == 8'hff) || (b_exponent == 8'hff)) begin

                        z <= {a_sign ^ b_sign, 8'hff, 23'b0};
                    end else if ((a_mantissa == 0 && a_exponent == 0) && (b_mantissa == 0 && b_exponent == 0)) begin

                        z <= {a_sign ^ b_sign, 31'b0};
                    end else if ((a_mantissa == 0 && a_exponent == 0) || (b_mantissa == 0 && b_exponent == 0)) begin

                        z <= {a_sign ^ b_sign, 31'b0};
                    end else begin
                        product <= a_mantissa * b_mantissa;
                        exponent_rounded <= a_exponent + b_exponent - 127;
                        sign <= a_sign ^ b_sign;
                        counter <= counter + 1;
                    end
                end
                3'b010: begin

                    if (product[47]) begin
                        product <= product >> 1;
                        exponent_rounded <= exponent_rounded + 1;
                    end
                    mantissa_rounded <= product[46:24];
                    guard_bit <= product[23];
                    round_bit <= product[22];
                    sticky <= |product[21:0];
                    counter <= counter + 1;
                end
                3'b011: begin

                    if (guard_bit) begin
                        if (round_bit || sticky) begin
                            mantissa_rounded <= mantissa_rounded + 1;
                        end else if (mantissa_rounded[0]) begin
                            mantissa_rounded <= mantissa_rounded + 1;
                        end
                    end
                    if (mantissa_rounded == 23'h7fffff + 1) begin
                        mantissa_rounded <= 23'b0;
                        exponent_rounded <= exponent_rounded + 1;
                    end
                    counter <= counter + 1;
                end
                3'b100: begin

                    if (exponent_rounded >= 8'hff) begin
                        z <= {sign, 8'hff, 23'b0};
                    end else if (exponent_rounded <= 8'h00) begin
                        z <= {sign, 31'b0};
                    end else begin
                        z <= {sign, exponent_rounded, mantissa_rounded};
                    end
                    counter <= 3'b0;
                end
                default: counter <= 3'b0;
            endcase
        end
    end

endmodule

