module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

    localparam IDLE = 2'b00;
    localparam S1   = 2'b01;
    localparam S2   = 2'b10;

    reg [1:0] state, next_state;


    always @(posedge clk or negedge rst_n) begin
        if (~rst_n)
            state <= IDLE;
        else
            state <= next_state;
    end


    always @(*) begin
        case (state)
            IDLE: next_state = data_in ? IDLE : S1;
            S1:   next_state = data_in ? S2 : IDLE;
            S2:   next_state = IDLE;
            default: next_state = IDLE;
        endcase
    end


    always @(posedge clk or negedge rst_n) begin
        if (~rst_n)
            data_out <= 1'b0;
        else
            data_out <= (state == S2) && (data_in == 0);
    end

endmodule

