module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);


    parameter idle = 2'b00,
              s1_red = 2'b01,
              s2_yellow = 2'b10,
              s3_green = 2'b11;

    reg [7:0] cnt;
    reg [1:0] state;
    reg p_red, p_yellow, p_green;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
        end else begin
            case (state)
                idle: state <= s1_red;
                s1_red: if (cnt == 8'd0) state <= s3_green;
                s3_green: if (cnt == 8'd0) state <= s2_yellow;
                s2_yellow: if (cnt == 8'd0) state <= s1_red;
                default: state <= idle;
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 8'd10;
        end else begin
            if (pass_request && green) begin
                cnt <= 8'd10;
            end else if (green) begin
                if (p_green) cnt <= 8'd60;
                else cnt <= cnt - 1;
            end else if (yellow) begin
                if (p_yellow) cnt <= 8'd5;
                else cnt <= cnt - 1;
            end else if (red) begin
                if (p_red) cnt <= 8'd10;
                else cnt <= cnt - 1;
            end else begin
                cnt <= cnt - 1;
            end
        end
    end


    assign clock = cnt;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            p_red <= 1'b0;
            p_yellow <= 1'b0;
            p_green <= 1'b0;
        end else begin
            p_red <= red;
            p_yellow <= yellow;
            p_green <= green;
        end
    end


    always @(*) begin
        case (state)
            s1_red: {red, yellow, green} = 3'b100;
            s3_green: {red, yellow, green} = 3'b001;
            s2_yellow: {red, yellow, green} = 3'b010;
            default: {red, yellow, green} = 3'b000;
        endcase
    end

endmodule

