                delayed_data <= {data_reg, data_in};
                delayed_valid <= 1'b1;
                data_lock <= 1'b0;
            end
        end else if (data_lock) begin
            data_lock <= 1'b1;

        end


        if (delayed_valid) begin
            data_out <= delayed_data;
            valid_out <= 1'b1;
            delayed_valid <= 1'b0;
        end else begin
            valid_out <= 1'b0;
        end
    end
