module alu (
    input [31:0] a, b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output reg carry,
    output negative,
    output reg overflow,
    output flag
);

    parameter ADD  = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB  = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND  = 6'b100100;
    parameter OR   = 6'b100101;
    parameter XOR  = 6'b100110;
    parameter NOR  = 6'b100111;
    parameter SLT  = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL  = 6'b000000;
    parameter SRL  = 6'b000010;
    parameter SRA  = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI  = 6'b001111;

    reg [31:0] res;
    reg [32:0] res_full;

    assign zero = (r == 32'b0);
    assign negative = r[31];
    assign flag = (aluc == SLT || aluc == SLTU) ? (res == 32'b1) : 1'b0;

    always @(*) begin
        case (aluc)
            ADD: begin
                res_full = {1'b0, a} + {1'b0, b};
                res = res_full[31:0];
                carry = res_full[32];
                overflow = (a[31] == b[31]) && (res[31] != a[31]);
            end
            ADDU: begin
                res_full = {1'b0, a} + {1'b0, b};
                res = res_full[31:0];
                carry = res_full[32];
                overflow = 1'b0;
            end
            SUB: begin
                res_full = {1'b0, a} - {1'b0, b};
                res = res_full[31:0];
                carry = res_full[32];
                overflow = (a[31] != b[31]) && (res[31] != a[31]);
            end
            SUBU: begin
                res_full = {1'b0, a} - {1'b0, b};
                res = res_full[31:0];
                carry = res_full[32];
                overflow = 1'b0;
            end
            AND: res = a & b;
            OR: res = a | b;
            XOR: res = a ^ b;
            NOR: res = ~(a | b);
            SLT: res = ($signed(a) < $signed(b)) ? 32'b1 : 32'b0;
            SLTU: res = (a < b) ? 32'b1 : 32'b0;
            SLL: res = a << a[4:0];
            SRL: res = a >> a[4:0];
            SRA: res = $signed(a) >>> a[4:0];
            SLLV: res = a << b[4:0];
            SRLV: res = a >> b[4:0];
            SRAV: res = $signed(a) >>> b[4:0];
            LUI: res = {a[31:16], 16'b0};
            default: res = 32'bz;
        endcase
        r = res;
    end

endmodule

