    if (rst) begin
        res_valid <= 1'b0;
        SR <= 16'b0;
        cnt <= 4'b0;
        start_cnt <= 1'b0;
        NEG_DIVISOR <= 8'b0;
        dividend_abs <= 8'b0;
        divisor_abs <= 8'b0;
        dividend_sign <= 1'b0;
        divisor_sign <= 1'b0;
    end else begin
        if (res_valid) begin
            if (!opn_valid) begin
                res_valid <= 1'b0;
            end
        end else if (!start_cnt && opn_valid && !res_valid) begin

            dividend_sign <= sign & dividend[7];
            divisor_sign <= sign & divisor[7];
            dividend_abs <= sign ? (~dividend + 1) : dividend;
            divisor_abs <= sign ? (~divisor + 1) : divisor;
            NEG_DIVISOR <= -divisor_abs;
