                start_cnt <= 1'b0;
                result <= {SR[15:8], SR[7:0]};
                if (sign) begin
                    if (dividend_sign ^ divisor_sign)
                        result[7:0] <= -result[7:0];

                    if (dividend_sign)
                        result[15:8] <= -result[15:8];

                end
                res_valid <= 1'b1;
            end
        end
    end
