        assign P[i] = A[i] ^ B[i];
        assign S[i] = P[i] ^ C[i];
        assign C[i+1] = G[i] | (P[i] & C[i]);
    end
endgenerate

assign P_group = &P;
assign G_group = G[4] | (P[4] & G[3]) | (P[4] & P[3] & G[2]) | (P[4] & P[3] & P[2] & G[1]);
