module fixed_point_adder #(
    parameter Q = 4,
    parameter N = 8
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);

    reg [N-1:0] res;
    wire a_sign = a[N-1];
    wire [N-2:0] a_mag = a[N-2:0];
    wire b_sign = b[N-1];
    wire [N-2:0] b_mag = b[N-2:0];

