module fixed_point_subtractor #(
    parameter Q = 4,
    parameter N = 8
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);

always @(*) begin
    reg sign_a, sign_b;
    reg [N-1:0] a_abs, b_abs;
    reg [N:0] sum_abs;
    reg res_sign;
    reg [N-1:0] temp_res;

    sign_a = a[N-1];
    sign_b = b[N-1];

    if (sign_a == sign_b) begin
        temp_res = a - b;
        res_sign = sign_a;
    end else begin
        a_abs = sign_a ? (-a) : a;
        b_abs = sign_b ? (-b) : b;
        sum_abs = a_abs + b_abs;

        if (sum_abs == 0) begin
            res_sign = 0;
        end else if (a_abs > b_abs) begin
            res_sign = 0;
        end else begin
            res_sign = 1;
        end

        temp_res = {res_sign, sum_abs[N-1:0]};
    end

    if (temp_res == 0) begin
        temp_res[N-1] = 1'b0;
    end

    c = temp_res;
end

endmodule

