module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [8:0] a_exponent, b_exponent, z_exponent;
    reg [22:0] a_mantissa, b_mantissa;
    reg [47:0] product;
    reg guard_bit, round_bit, sticky;
    reg [23:0] mantissa_part;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'b0;
        end else begin
            case (counter)
                3'b000: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= {1'b0, a[30:23]};
                    b_exponent <= {1'b0, b[30:23]};
                    a_mantissa <= (a[30:23] == 8'b0) ? {1'b0, a[22:0]} : {1'b1, a[22:0]};
                    b_mantissa <= (b[30:23] == 8'b0) ? {1'b0, b[22:0]} : {1'b1, b[22:0]};
                    counter <= counter + 1;
                end

                3'b001: begin

                    if ((a_exponent == 9'b111111110 && b_exponent == 9'b111111110) || 
                        (a_exponent == 9'b111111110) || (b_exponent == 9'b111111110)) begin
                        z <= {1'b0, 8'b11111111, 23'h000001};
                    end else if (a_exponent == 9'b111111111 || b_exponent == 9'b111111111) begin
                        if (a_mantissa == 24'b0) begin
                            z <= {a_sign ^ b_sign, 8'hFF, 23'h000001};
                        end else if (b_mantissa == 24'b0) begin
                            z <= {a_sign ^ b_sign, 8'hFF, 23'h000001};
                        end else begin
                            z <= {a_sign ^ b_sign, 8'hFF, 23'h000000};
                        end
                    end else if (a_mantissa == 24'b0 || b_mantissa == 24'b0) begin
                        z <= {a_sign ^ b_sign, 31'b0};
                    end else begin
                        product <= a_mantissa * b_mantissa;
                        z_exponent <= a_exponent + b_exponent - 9'd127;
                        counter <= counter + 1;
                    end
                end

                3'b010: begin

                    if (product == 48'b0) begin
                        z <= {a_sign ^ b_sign, 31'b0};
                    end else begin
                        integer leading_one;
                        leading_one = 47;
                        while (product[leading_one] == 1'b0 && leading_one >= 0) begin
                            leading_one <= leading_one - 1;
                        end
                        reg [47:0] norm_product = product << (47 - leading_one);
                        reg [7:0] shift = 47 - leading_one;
                        z_exponent <= z_exponent + shift;
                        mantissa_part = norm_product[47:24];
                        guard_bit = norm_product[23];
                        round_bit = norm_product[22];
                        sticky = |norm_product[21:0];
                        if (guard_bit && (round_bit || sticky)) begin
                            mantissa_part = mantissa_part + 1;
                            if (mantissa_part == 24'h1000000) begin
                                mantissa_part = 24'h800000;
                                z_exponent <= z_exponent + 1;
                            end
                        end
                        if (z_exponent >= 9'b100000000) begin
                            z <= {a_sign ^ b_sign, 8'hFF, 23'b0};
                        end else if (z_exponent[8] == 1'b1) begin
                            z <= {a_sign ^ b_sign, 31'b0};
                        end else begin
                            z <= {a_sign ^ b_sign, z_exponent[7:0], mantissa_part[22:0]};
                        end
                    end
                end

                default: begin
                    counter <= 3'b0;
                end
            endcase
        end
    end

endmodule

