        stack_mem[0] <= 4'b0;
        stack_mem[1] <= 4'b0;
        stack_mem[2] <= 4'b0;
        stack_mem[3] <= 4'b0;
        SP <= 3'd4;
    end else if (EN) begin
        if (RW == 1'b0) begin 
            if (!FULL) begin
                stack_mem[SP-1] <= dataIn;
                SP <= SP - 1;
            end
        end else begin 
            if (!EMPTY) begin
                dataOut <= stack_mem[SP];
                stack_mem[SP] <= 4'b0;
                SP <= SP + 1;
            end
        end
    end
end

