module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

    localparam S0 = 2'b00;
    localparam S1 = 2'b01;
    localparam S2 = 2'b10;

    reg [1:0] state;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            state <= S0;
            data_out <= 1'b0;
        end else begin
            case (state)
                S0: state <= data_in ? S0 : S1;
                S1: state <= data_in ? S2 : S0;
                S2: state <= S0;
            endcase

            data_out <= (state == S2) && (data_in == 1'b0) ? 1'b1 : 1'b0;
        end
    end

endmodule

