module width_8to16 (
    input clk,
    input rst_n,
    input valid_in,
    input [7:0] data_in,
    output reg valid_out,
    output reg [15:0] data_out
);

reg [7:0] data_lock;
reg first_received;
reg [15:0] pending_data;
reg pending_valid;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        data_lock <= 8'b0;
        first_received <= 1'b0;
        pending_data <= 16'b0;
        pending_valid <= 1'b0;
        data_out <= 16'b0;
        valid_out <= 1'b0;
    end
    else begin
        pending_valid <= 1'b0;

        if (valid_in && !first_received) begin
            data_lock <= data_in;
            first_received <= 1'b1;
        end
        else if (valid_in && first_received) begin
            pending_data <= {data_lock, data_in};
            pending_valid <= 1'b1;
            first_received <= 1'b0;
        end

        data_out <= pending_data;
        valid_out <= pending_valid;
    end
end

endmodule

