        reg [7:0] new_shift_reg;
        reg [3:0] new_cnt;

        new_shift_reg = shift_reg;
        new_cnt = cnt;

        if (din_valid) begin
            new_shift_reg = {din_serial, shift_reg[7:1]};
            new_cnt = (cnt == 4'd7) ? 4'd0 : cnt + 4'd1;
        end

        dout_parallel <= new_shift_reg;
        dout_valid <= (din_valid && cnt == 4'd7) ? 1'b1 : 1'b0;

        shift_reg <= new_shift_reg;
        cnt <= new_cnt;
    end
end

