module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output reg zero,
    output reg carry,
    output reg negative,
    output reg overflow,
    output reg flag
);

    parameter ADD = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND = 6'b100100;
    parameter OR = 6'b100101;
    parameter XOR = 6'b100110;
    parameter NOR = 6'b100111;
    parameter SLT = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL = 6'b000000;
    parameter SRL = 6'b000010;
    parameter SRA = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI = 6'b001111;

    reg [31:0] r_reg;
    reg carry_reg, overflow_reg;

    always @(*) begin
        case (aluc)
            ADD: begin
                wire [32:0] sum = {1'b0, a} + {1'b0, b};
                r_reg = sum[31:0];
                carry_reg = sum[32];
                overflow_reg = (a[31] == b[31]) && (sum[31] != a[31]);
            end
            ADDU: begin
                r_reg = a + b;
                carry_reg = 0;
                overflow_reg = 0;
            end
            SUB: begin
                wire [32:0] diff = {1'b0, a} + {1'b0, ~b} + 33'd1;
                r_reg = diff[31:0];
                carry_reg = diff[32];
                overflow_reg = (a[31] != b[31]) && (diff[31] != a[31]);
            end
            SUBU: begin
                r_reg = a - b;
                carry_reg = 0;
                overflow_reg = 0;
            end
            AND: begin
                r_reg = a & b;
                carry_reg = 0;
                overflow_reg = 0;
            end
            OR: begin
                r_reg = a | b;
                carry_reg = 0;
                overflow_reg = 0;
            end
            XOR: begin
                r_reg = a ^ b;
                carry_reg = 0;
                overflow_reg = 0;
            end
            NOR: begin
                r_reg = ~(a | b);
                carry_reg = 0;
                overflow_reg = 0;
            end
            SLT: begin
                r_reg = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;
                carry_reg = 0;
                overflow_reg = 0;
            end
            SLTU: begin
                r_reg = (a < b) ? 32'd1 : 32'd0;
                carry_reg = 0;
                overflow_reg = 0;
            end
            SLL: begin
                r_reg = b << a[4:0];
                carry_reg = 0;
                overflow_reg = 0;
            end
            SRL: begin
                r_reg = b >> a[4:0];
                carry_reg = 0;
                overflow_reg = 0;
            end
            SRA: begin
                r_reg = $signed(b) >>> a[4:0];
                carry_reg = 0;
                overflow_reg = 0;
            end
            SLLV: begin
                r_reg = b << a[4:0];
                carry_reg = 0;
                overflow_reg = 0;
            end
            SRLV: begin
                r_reg = b >> a[4:0];
                carry_reg = 0;
                overflow_reg = 0;
            end
            SRAV: begin
                r_reg = $signed(b) >>> a[4:0];
                carry_reg = 0;
                overflow_reg = 0;
            end
            LUI: begin
                r_reg = {a[15:0], 16'b0};
                carry_reg = 0;
                overflow_reg = 0;
            end
            default: begin
                r_reg = 32'bz;
                carry_reg = 0;
                overflow_reg = 0;
            end
        endcase

        r = r_reg;
        zero = (r_reg == 32'd0);
        negative = r_reg[31];
        carry = carry_reg;
        overflow = overflow_reg;
        flag = (aluc == SLT || aluc == SLTU) ? r_reg[0] : 1'bz;
    end

endmodule

