module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [15:0] SR;

    reg [3:0] cnt;

    reg start_cnt;

    reg [7:0] abs_dividend;

    reg [7:0] abs_divisor;

    reg [7:0] neg_divisor;

    reg [7:0] quotient;

    reg [7:0] remainder;

    reg dividend_sign;

    reg divisor_sign;

    reg q_sign;

    reg r_sign;


    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            SR <= 0;
            cnt <= 0;
            start_cnt <= 0;
            abs_dividend <= 0;
            abs_divisor <= 0;
            neg_divisor <= 0;
            quotient <= 0;
            remainder <= 0;
            dividend_sign <= 0;
            divisor_sign <= 0;
            q_sign <= 0;
            r_sign <= 0;
        end else begin
            if (opn_valid && !res_valid) begin

                if (sign) begin
                    dividend_sign <= dividend[7];
                    divisor_sign <= divisor[7];
                    abs_dividend <= dividend[7] ? -dividend : dividend;
                    abs_divisor <= divisor[7] ? -divisor : divisor;
                end else begin
                    dividend_sign <= 0;
                    divisor_sign <= 0;
                    abs_dividend <= dividend;
                    abs_divisor <= divisor;
                end
                neg_divisor <= -abs_divisor;

                SR <= {abs_dividend, 1'b0} << 8;

                cnt <= 4'd1;
                start_cnt <= 1;
                res_valid <= 0;
            end else if (start_cnt) begin
                if (cnt == 8) begin

                    start_cnt <= 0;
                    cnt <= 0;

                    q_sign <= dividend_sign ^ divisor_sign;
                    r_sign <= dividend_sign;

                    quotient <= q_sign ? -quotient : quotient;
                    remainder <= r_sign ? -remainder : remainder;
                    result <= {remainder, quotient};
                    res_valid <= 1;
                end else begin

                    if (sign) begin
                        quotient <= (SR[7:0] << 1) | ((SR[15:8] - neg_divisor) >> 8);
                        remainder <= (SR[15:8] - neg_divisor) & 8'hFF;
                    end else begin

                        quotient <= (SR[7:0] << 1) | ((SR[15:8] - neg_divisor) >> 8);
                        remainder <= (SR[15:8] - neg_divisor) & 8'hFF;
                    end
                    SR <= {remainder, quotient};
                    cnt <= cnt + 1;
                end
            end else begin
                res_valid <= 0;
            end
        end
    end

endmodule

