module accu (
    input clk,
    input rst_n,
    input [7:0] data_in,
    input valid_in,
    output reg valid_out,
    output reg [9:0] data_out
);

reg [1:0] counter;
reg [9:0] sum_reg;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        counter <= 2'b00;
        sum_reg <= 10'b0;
        valid_out <= 1'b0;
        data_out <= 10'b0;
    end else begin
        valid_out <= 1'b0;

        if (valid_in) begin
            if (counter < 2'b11) begin
                sum_reg <= sum_reg + data_in;

                counter <= counter + 1;

            end else begin

                sum_reg <= 10'b0;
                counter <= 2'b00;
                valid_out <= 1'b1;
                data_out <= sum_reg + data_in;

            end
        end
    end
end

endmodule

