module fixed_point_adder #(
    parameter Q = 8,
    parameter N = 16
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);
    reg a_sign, b_sign;
    reg [N-1:0] abs_a, abs_b;
    reg same_sign;
    reg [N-1:0] sum, diff;
    reg result_sign;

    always @* begin
        a_sign = a[N-1];
        b_sign = b[N-1];
        abs_a = a_sign ? (~a + 1) : a;
        abs_b = b_sign ? (~b + 1) : b;
        same_sign = (a_sign == b_sign);

        if (same_sign) begin
            sum = abs_a + abs_b;
            c = sum;
        end else begin
            if (abs_a > abs_b) begin
                diff = abs_a - abs_b;
                result_sign = 1'b0;
            end else if (abs_b > abs_a) begin
                diff = abs_b - abs_a;
                result_sign = 1'b1;
            end else begin
                diff = 0;
                result_sign = 1'b0;
            end
            c = {result_sign, diff[N-2:0]};
        end
    end
endmodule

