module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg [7:0] a_exponent, b_exponent;
    reg [23:0] a_mantissa, b_mantissa;
    reg a_sign, b_sign, z_sign;
    reg [47:0] product;
    reg [23:0] z_mantissa;
    reg [9:0] z_exponent;
    reg guard_bit, round_bit, sticky;
    reg is_nan, is_inf, is_zero;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 0;
            z <= 0;
            a_exponent <= 0;
            b_exponent <= 0;
            a_mantissa <= 0;
            b_mantissa <= 0;
            a_sign <= 0;
            b_sign <= 0;
            z_sign <= 0;
            product <= 0;
            z_mantissa <= 0;
            z_exponent <= 0;
            guard_bit <= 0;
            round_bit <= 0;
            sticky <= 0;
            is_nan <= 0;
            is_inf <= 0;
            is_zero <= 0;
        end else begin
            case (counter)
                0: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];


                    a_mantissa <= (a_exponent == 0) ? {1'b0, a[22:0]} : {1'b1, a[22:0]};
                    b_mantissa <= (b_exponent == 0) ? {1'b0, b[22:0]} : {1'b1, b[22:0]};


                    is_nan <= (a_exponent == 8'hff && |a[22:0]) || (b_exponent == 8'hff && |b[22:0]);
                    is_inf <= (a_exponent == 8'hff && !(|a[22:0])) || (b_exponent == 8'hff && !(|b[22:0]));
                    is_zero <= (a_exponent == 0 && !(|a[22:0])) && (b_exponent == 0 && !(|b[22:0]));

                    counter <= 1;
                end
                1: begin

                    product <= a_mantissa * b_mantissa;


                    z_exponent <= a_exponent + b_exponent + 9'd128;



                    if (product[47]) begin 
                        z_mantissa <= product[46:23];
                        z_exponent <= z_exponent + 9'd1;
                    end else begin
                        z_mantissa <= product[45:22];
                    end


                    guard_bit <= product[22];
                    round_bit <= product[21];
                    sticky <= |product[20:0];


                    if (guard_bit) begin
                        if (round_bit || sticky || z_mantissa[0]) begin
                            z_mantissa <= z_mantissa + 1;
                        end
                    end


                    if (z_mantissa[23]) begin
                        z_mantissa <= 24'b0;
                        z_exponent <= z_exponent + 9'd1;
                    end

                    counter <= 2;
