module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);


    localparam IDLE      = 2'b00;
    localparam STATE_1   = 2'b01;
    localparam STATE_2   = 2'b10;

    reg [1:0] state, next_state;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            data_out <= 1'b0;
        end else begin
            state <= next_state;

            case (state)
                STATE_2: data_out <= (data_in == 1'b0) ? 1'b1 : 1'b0;
                default: data_out <= 1'b0;
            endcase
        end
    end


    always @(*) begin
        case (state)
            IDLE: begin
                next_state = (data_in == 1'b0) ? STATE_1 : IDLE;
            end
            STATE_1: begin
                next_state = (data_in == 1'b1) ? STATE_2 : IDLE;
            end
            STATE_2: begin
                next_state = (data_in == 1'b0) ? IDLE : IDLE;
            end
            default: next_state = IDLE;
        endcase
    end

endmodule

