module traffic_light(
    input rst_n,
    input clk,
    input pass_request,
    output [7:0] clock,
    output red,
    output yellow,
    output green
);

    parameter idle = 2'b00,
              s1_red = 2'b01,
              s2_yellow = 2'b10,
              s3_green = 2'b11;

    reg [7:0] cnt;
    reg [1:0] state;
    reg p_red, p_yellow, p_green;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
        end else begin
            case (state)
                idle: begin
                    state <= s1_red;
                    p_red <= 1;
                    p_yellow <= 0;
                    p_green <= 0;
                end
                s1_red: begin
                    if (cnt == 0) begin
                        state <= s3_green;
                        p_red <= 0;
                        p_yellow <= 0;
                        p_green <= 1;
                    end else begin
                        state <= s1_red;
                        p_red <= 1;
                        p_yellow <= 0;
                        p_green <= 0;
                    end
                end
                s3_green: begin
                    if (cnt == 0) begin
                        state <= s2_yellow;
                        p_red <= 0;
                        p_yellow <= 1;
                        p_green <= 0;
                    end else begin
                        state <= s3_green;
                        p_red <= 0;
                        p_yellow <= 0;
                        p_green <= 1;
                    end
                end
                s2_yellow: begin
                    if (cnt == 0) begin
                        state <= s1_red;
                        p_red <= 1;
                        p_yellow <= 0;
                        p_green <= 0;
                    end else begin
                        state <= s2_yellow;
                        p_red <= 0;
                        p_yellow <= 1;
                        p_green <= 0;
                    end
                end
                default: begin
                    state <= idle;
                    p_red <= 0;
                    p_yellow <= 0;
                    p_green <= 0;
                end
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 10;
        end else begin
            if (pass_request && p_green) begin
                if (cnt > 10) begin
                    cnt <= 10;
                end else begin
                    cnt <= cnt;
                end
            end else begin
                if (cnt == 0) begin
                    case (state)
                        s1_red: cnt <= 10;
                        s3_green: cnt <= 60;
                        s2_yellow: cnt <= 5;
                        default: cnt <= 10;
                    endcase
                end else begin
                    cnt <= cnt - 1;
                end
            end
        end
    end

    assign clock = cnt;
    assign red = p_red;
    assign yellow = p_yellow;
    assign green = p_green;

endmodule

