module width_8to16 (
    input clk,
    input rst_n,
    input valid_in,
    input [7:0] data_in,
    output reg valid_out,
    output reg [15:0] data_out
);

reg [7:0] data_lock;
reg has_data;
reg [15:0] data_out_reg;
reg next_valid;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        data_lock <= 8'b0;
        has_data <= 1'b0;
        data_out <= 16'b0;
        valid_out <= 1'b0;
        next_valid <= 1'b0;
    end else begin

        next_valid <= 1'b0;

        if (valid_in) begin
            if (has_data) begin

                data_out_reg <= {data_lock, data_in};
                next_valid <= 1'b1;
                has_data <= 1'b0;
            end else begin

                data_lock <= data_in;
                has_data <= 1'b1;
            end
        end


        valid_out <= next_valid;
        if (next_valid) begin
            data_out <= data_out_reg;
        end
    end
end

endmodule

