module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output [15:0] result
);

reg [15:0] SR;
reg [7:0] divisor_abs;
reg [15:0] NEG_DIVISOR;
reg [3:0] cnt;
reg start_cnt;
reg res_valid_reg;
reg sign_dividend_reg;
reg sign_divisor_reg;
reg [15:0] result_reg;

wire [7:0] actual_remainder = sign ? (sign_dividend_reg ? -SR[15:8] : SR[15:8]) : SR[15:8];
wire [7:0] actual_quotient = sign ? ((sign_dividend_reg ^ sign_divisor_reg) ? -SR[7:0] : SR[7:0]) : SR[7:0];

assign result = result_reg;

always @(posedge clk) begin
    if (rst) begin
        res_valid_reg <= 1'b0;
        res_valid <= 1'b0;
        SR <= 16'b0;
        cnt <= 4'b0;
        start_cnt <= 1'b0;
        divisor_abs <= 8'b0;
        NEG_DIVISOR <= 16'b0;
        sign_dividend_reg <= 1'b0;
        sign_divisor_reg <= 1'b0;
        result_reg <= 16'b0;
    end else begin
        res_valid <= res_valid_reg;

        if (opn_valid && !res_valid_reg) begin
            sign_dividend_reg <= sign ? dividend[7] : 1'b0;
            sign_divisor_reg <= sign ? divisor[7] : 1'b0;
            divisor_abs <= sign ? (divisor[7] ? -divisor : divisor) : divisor;
            NEG_DIVISOR <= -{{8{1'b0}}, divisor_abs};
            SR <= {dividend_abs, 8'b0} << 1;
            cnt <= 4'd1;
            start_cnt <= 1'b1;
            res_valid_reg <= 1'b0;
        end else if (start_cnt) begin
            if (cnt == 4'd8) begin
                result_reg <= {actual_remainder, actual_quotient};
                res_valid_reg <= 1'b1;
                start_cnt <= 1'b0;
                cnt <= 4'b0;
            end else begin

                reg [7:0] current_remainder = SR[15:8];
                reg [7:0] sub_result = current_remainder - divisor_abs;
                reg carry_out = sub_result[7];


                reg [7:0] new_remainder = carry_out ? current_remainder : sub_result;
                reg quotient_bit = carry_out ? 1'b0 : 1'b1;


                SR <= {new_remainder, SR[7:1], quotient_bit};
                cnt <= cnt + 1;
            end
        end
    end
end

endmodule

