module cla_bit (
    input A,
    input B,
    output G,
    output P
);
    assign G = A & B;
    assign P = A ^ B;
endmodule

module cla_4bit (
    input [4:1] A,
    input [4:1] B,
    input C_in,
    output [4:1] S,
    output C_out,
    output G_group,
    output P_group
);
    wire [4:1] G, P;
    wire [4:1] C;

    cla_bit bit1 (.A(A[1]), .B(B[1]), .G(G[1]), .P(P[1]));
    cla_bit bit2 (.A(A[2]), .B(B[2]), .G(G[2]), .P(P[2]));
    cla_bit bit3 (.A(A[3]), .B(B[3]), .G(G[3]), .P(P[3]));
    cla_bit bit4 (.A(A[4]), .B(B[4]), .G(G[4]), .P(P[4]));

    assign C[1] = G[1] | (P[1] & C_in);
    assign C[2] = G[2] | (P[2] & G[1]) | (P[2] & P[1] & C_in);
    assign C[3] = G[3] | (P[3] & G[2]) | (P[3] & P[2] & G[1]) | (P[3] & P[2] & P[1] & C_in);
    assign C[4] = G[4] | (P[4] & G[3]) | (P[4] & P[3] & G[2]) | (P[4] & P[3] & P[2] & G[1]) | (P[4] & P[3] & P[2] & P[1] & C_in);

    assign S[1] = P[1] ^ C_in;
    assign S[2] = P[2] ^ C[1];
    assign S[3] = P[3] ^ C[2];
    assign S[4] = P[4] ^ C[3];

    assign G_group = G[4] | (P[4] & G[3]) | (P[4] & P[3] & G[2]) | (P[4] & P[3] & P[2] & G[1]);
    assign P_group = P[4] & P[3] & P[2] & P[1];
    assign C_out = G_group | (P_group & C_in);
endmodule

