module fixed_point_adder #(
    parameter Q = 2,
    parameter N = 8
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

    reg [N-1:0] res;

    always @(*) begin
        reg a_sign, b_sign;
        reg [N-2:0] a_mag, b_mag;
        reg [N-1:0] sum, diff;

        a_sign = a[N-1];
        b_sign = b[N-1];


        a_mag = a_sign ? (~a[N-2:0] + 1) : a[N-2:0];
        b_mag = b_sign ? (~b[N-2:0] + 1) : b[N-2:0];

        if (a_sign == b_sign) begin

            sum = {a_sign, a_mag} + {b_sign, b_mag};
            res = sum;
        end else begin

            if (a_mag > b_mag) begin
                diff = {a_sign, a_mag} - {b_sign, b_mag};
                res = diff;
            end else if (b_mag > a_mag) begin
                diff = {b_sign, b_mag} - {a_sign, a_mag};
                res = diff;
            end else begin

                res = 0;
            end
        end

        c = res;
    end

endmodule

