module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

reg [2:0] counter;
reg [9:0] a_exponent, b_exponent, z_exponent;
reg a_sign, b_sign, z_sign;
reg [23:0] a_mantissa, b_mantissa, z_mantissa;
reg [48:0] product;

reg guard_bit, round_bit, sticky;

always @(posedge clk) begin
    if (rst) begin
        counter <= 3'b0;
        z <= 32'b0;
        a_exponent <= 0;
        b_exponent <= 0;
        a_mantissa <= 0;
        b_mantissa <= 0;
        z_exponent <= 0;
        z_sign <= 0;
        product <= 0;
        guard_bit <= 0;
        round_bit <= 0;
        sticky <= 0;
    end else begin
        case (counter)
            3'b000: begin 
                a_sign <= a[31];
                b_sign <= b[31];
                a_exponent <= {2'b00, a[30:23]};

                b_exponent <= {2'b00, b[30:23]};
                a_mantissa <= {1'b1, a[22:0]};
                b_mantissa <= {1'b1, b[22:0]};
                counter <= 3'b001;
            end
            3'b001: begin 
                if ((a_exponent == 10'h3FF && a_mantissa != 0) || 
                    (b_exponent == 10'h3FF && b_mantissa != 0)) begin
                    z_sign <= a_sign ^ b_sign;
                    z_exponent <= 10'h3FF;
                    z_mantissa <= 24'h000001;
                end else if ((a_exponent == 10'h3FF && a_mantissa == 0) ||
                            (b_exponent == 10'h3FF && b_mantissa == 0)) begin

                    z_sign <= a_sign ^ b_sign;
                    z_exponent <= 10'h3FF;
                    z_mantissa <= 0;
                end else if ((a_exponent == 0 && a_mantissa == 0) ||
                            (b_exponent == 0 && b_mantissa == 0)) begin
                    z_sign <= a_sign ^ b_sign;
                    z_exponent <= 0;
                    z_mantissa <= 0;
                end else begin
                    z_sign <= a_sign ^ b_sign;
                    z_exponent <= a_exponent + b_exponent - 10'd127;
                    counter <= 3'b010;
                end
            end
            3'b010: begin 
                product <= a_mantissa * b_mantissa;
                counter <= 3'b011;
            end
            3'b011: begin 
                if (product[48]) begin 
                    z_mantissa <= product[47:24];

                    guard_bit <= product[23];
                    round_bit <= product[22];
                    sticky <= |product[21:0];
                    z_exponent <= z_exponent - 1;
                end else begin
                    z_mantissa <= product[46:23];
                    guard_bit <= product[22];
                    round_bit <= product[21];
                    sticky <= |product[20:0];
                end
                counter <= 3'b100;
            end
            3'b100: begin 
                if (guard_bit && (round_bit || sticky)) begin
                    z_mantissa <= z_mantissa + 1;
                    if (z_mantissa == 24'hFFFFFF) begin
                        z_exponent <= z_exponent + 1;
                        z_mantissa <= 24'h0;
                    end
                end
                counter <= 3'b101;
            end
            3'b101: begin 
                if (z_exponent >= 10'd255) begin 
                    z_exponent <= 10'd255;
                    z_mantissa <= 0;
                end else if (z_exponent == 0 && z_mantissa == 0) begin 
                    z_exponent <= 0;
                    z_mantissa <= 0;
                end
                z <= {z_sign, z_exponent[7:0], z_mantissa[22:0]};
                counter <= 3'b000;
            end
            default: counter <= 3'b000;
        endcase
    end
end

endmodule

