module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output red,
    output yellow,
    output green
);

    parameter idle = 2'b00;
    parameter s1_red = 2'b01;
    parameter s2_yellow = 2'b10;
    parameter s3_green = 2'b11;

    reg [1:0] state, next_state;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            state <= idle;
        else
            state <= next_state;
    end


    always @(*) begin
        case (state)
            idle: next_state = s1_red;
            s1_red: next_state = (cnt == 3) ? s3_green : s1_red;
            s3_green: next_state = (cnt == 3) ? s2_yellow : s3_green;
            s2_yellow: next_state = (cnt == 3) ? s1_red : s2_yellow;
            default: next_state = idle;
        endcase
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            cnt <= 8'd10;
        else begin
            if (pass_request && green)
                cnt <= 8'd10;
            else if (!green && p_green)
                cnt <= 8'd60;
            else if (!yellow && p_yellow)
                cnt <= 8'd5;
            else if (!red && p_red)
                cnt <= 8'd10;
            else
                cnt <= cnt - 1;
        end
    end

    assign clock = cnt;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
        end else begin
            p_red <= red;
            p_yellow <= yellow;
            p_green <= green;
        end
    end


    assign red = (state == s1_red) || (state == s3_green) || (state == s2_yellow && cnt >= 3);
    assign yellow = (state == s2_yellow);
    assign green = (state == s3_green);

endmodule

