module alu (
    input [31:0] a, b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero, carry, negative, overflow, flag
);


parameter ADD = 6'b100000;
parameter ADDU = 6'b100001;
parameter SUB = 6'b100010;
parameter SUBU = 6'b100011;
parameter AND = 6'b100100;
parameter OR = 6'b100101;
parameter XOR = 6'b100110;
parameter NOR = 6'b100111;
parameter SLT = 6'b101010;
parameter SLTU = 6'b101011;
parameter SLL = 6'b000000;
parameter SRL = 6'b000010;
parameter SRA = 6'b000011;
parameter SLLV = 6'b000100;
parameter SRLV = 6'b000110;
parameter SRAV = 6'b000111;
parameter LUI = 6'b001111;


reg [32:0] sum_add, sum_sub;
reg [32:0] sum_addu, sum_subu;
reg [31:0] res;
reg c_add, c_sub, c_addu, c_subu;
reg ov_add, ov_sub, ov_addu, ov_subu;

always @(*) begin
    case (aluc)
        ADD: begin
            res = a + b;
            c_add = res[32];

            ov_add = (a[31] == b[31]) && (res[31] != a[31]);

        end
        ADDU: begin
            res = a + b;
            c_addu = res[32];
            ov_addu = 1'b0;

        end
        SUB: begin
            res = a - b;
            c_sub = res[32];

            ov_sub = (a[31] != b[31]) && (res[31] != a[31]);

        end
        SUBU: begin
            res = a - b;
            c_subu = res[32];
            ov_subu = 1'b0;
        end
        AND: res = a & b;
        OR: res = a | b;
        XOR: res = a ^ b;
        NOR: res = ~(a | b);
        SLT: res = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;
        SLTU: res = (a < b) ? 32'd1 : 32'd0;
        SLL: res = a << b[4:0];

        SRL: res = a >> b[4:0];
        SRA: res = $signed(a) >>> b[4:0];
        SLLV: res = b << a[4:0];

        SRLV: res = b >> a[4:0];
        SRAV: res = $signed(b) >>> a[4:0];
        LUI: res = {a[15:0], 16'b0};
        default: res = 32'bz;
    endcase
end

assign r = res;


assign zero = (res == 32'b0);
assign negative = res[31];
assign carry = (aluc == ADD) ? c_add :
               (aluc == ADDU) ? c_addu :
               (aluc == SUB) ? c_sub :
               (aluc == SUBU) ? c_subu :
               1'b0;

assign overflow = (aluc == ADD) ? ov_add :
                 (aluc == SUB) ? ov_sub :
                 1'b0;

assign flag = (aluc == SLT || aluc == SLTU) ? res[0] : 1'bz;

endmodule

