module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output [15:0] result
);

    reg [15:0] sr;
    reg [3:0] cnt;
    reg start_cnt;
    reg [7:0] dividend_abs, divisor_abs, neg_divisor_abs;

    always @(posedge clk) begin
        if (rst) begin
            sr <= 16'b0;
            cnt <= 4'b0;
            start_cnt <= 1'b0;
            res_valid <= 1'b0;
            dividend_abs <= 8'b0;
            divisor_abs <= 8'b0;
            neg_divisor_abs <= 8'b0;
        end else begin
            if (res_valid) begin
                if (opn_valid && !res_valid) begin
                    res_valid <= 1'b0;
                    start_cnt <= 1'b1;
                    cnt <= 4'b1;
                    if (sign) begin
                        dividend_abs <= dividend[7] ? (-dividend) : dividend;
                        divisor_abs <= divisor[7] ? (-divisor) : divisor;
                    end else begin
                        dividend_abs <= dividend;
                        divisor_abs <= divisor;
                    end
                    neg_divisor_abs <= -divisor_abs;
                    sr <= {dividend_abs, 8'b0} << 1;
                end
            end else begin
                if (start_cnt) begin
                    if (cnt == 4'd8) begin
                        start_cnt <= 1'b0;
                        res_valid <= 1'b1;
                    end else begin
                        if (sr[15:8] >= divisor_abs) begin
                            sr <= { (sr[15:8] - divisor_abs), sr[7:0], 1'b1 };
                        end else begin
                            sr <= { sr[15:8], sr[7:0], 1'b0 };
                        end
                        cnt <= cnt + 1;
                    end
                end else begin
                    if (opn_valid) begin
                        res_valid <= 1'b0;
                        start_cnt <= 1'b1;
                        cnt <= 4'b1;
                        if (sign) begin
                            dividend_abs <= dividend[7] ? (-dividend) : dividend;
                            divisor_abs <= divisor[7] ? (-divisor) : divisor;
                        end else begin
                            dividend_abs <= dividend;
                            divisor_abs <= divisor;
                        end
                        neg_divisor_abs <= -divisor_abs;
                        sr <= {dividend_abs, 8'b0} << 1;
                    end
                end
            end
        end
    end

    assign result = res_valid ? sr : 16'b0;

endmodule

