module accu (
    input clk,
    input rst_n,
    input [7:0] data_in,
    input valid_in,
    output reg valid_out,
    output reg [9:0] data_out
);

    reg [1:0] counter;
    reg [9:0] accumulator;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            counter <= 2'b00;
            accumulator <= 10'b0;
            data_out <= 10'b0;
            valid_out <= 1'b0;
        end else begin
            if (valid_in) begin
                accumulator <= accumulator + {2'b00, data_in};
                counter <= counter + 1'b1;

                if (counter == 2'b11) begin
                    data_out <= accumulator + {2'b00, data_in};
                    valid_out <= 1'b1;
                end else begin
                    data_out <= 10'b0;
                    valid_out <= 1'b0;
                end
            end else begin
                data_out <= 10'b0;
                valid_out <= 1'b0;
            end
        end
    end

endmodule

