module fixed_point_adder #(
    parameter Q = 4,
    parameter N = 8
) (
    input  [N-1:0] a,
    input  [N-1:0] b,
    output [N-1:0] c
);

    wire sign_a = a[N-1];
    wire sign_b = b[N-1];


    wire [N-2:0] a_mag = sign_a ? (~a[N-2:0] + 1) : a[N-2:0];
    wire [N-2:0] b_mag = sign_b ? (~b[N-2:0] + 1) : b[N-2:0];


    wire same_sign = (sign_a == sign_b);
    wire [N-1:0] sum_mag = a_mag + b_mag;
    wire overflow = sum_mag[N-1];
    wire [N-2:0] sum_mag_truncated = sum_mag[N-2:0];
    wire [N-1:0] same_case = {overflow ? 1'b1 : sign_a, sum_mag_truncated};


    wire [N-2:0] max_mag = (a_mag > b_mag) ? a_mag : b_mag;
    wire [N-2:0] min_mag = (a_mag > b_mag) ? b_mag : a_mag;
    wire [N-2:0] diff_mag = max_mag - min_mag;
    wire diff_sign = (a_mag > b_mag) ? sign_a : sign_b;
    wire [N-1:0] diff_case = {diff_sign, diff_mag};


    assign c = same_sign ? same_case : diff_case;

endmodule

