module fixed_point_subtractor #(
    parameter Q = 2,  
    parameter N = 8   
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output wire [N-1:0] c
);

    reg [N-1:0] res;
    wire sign_a = a[N-1];
    wire sign_b = b[N-1];
    wire same_sign = (sign_a == sign_b);


    wire [N-1:0] abs_a = sign_a ? (~a + 1) : a;
    wire [N-1:0] abs_b = sign_b ? (~b + 1) : b;
    wire sum_sign = (abs_a > abs_b) ? sign_a : sign_b;

    always @(*) begin
        if (same_sign) begin

            res = a - b;
        end else begin

            res = {sum_sign, (abs_a > abs_b) ? abs_a[N-2:0] : abs_b[N-2:0]};
        end


        if (res == 0)
            res = 0;
    end

    assign c = res;

