module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg [7:0] a_exponent, b_exponent, z_exponent;
    reg [22:0] a_mantissa, b_mantissa, z_mantissa;
    reg a_sign, b_sign, z_sign;
    reg [49:0] product;
    reg guard_bit, round_bit, sticky;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'b0;
        end else begin
            case (counter)
                3'b000: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= (|a[30:23]) ? {a[22:0]} : {1'b0, a[22:0]};
                    b_mantissa <= (|b[30:23]) ? {b[22:0]} : {1'b0, b[22:0]};
                    counter <= counter + 1;
                end
                3'b001: begin

                    if ((a_exponent == 8'hFF && a_mantissa != 23'b0) ||
                        (b_exponent == 8'hFF && b_mantissa != 23'b0)) begin
                        z <= 32'h7FC00000;

                    end else if (a_exponent == 8'hFF && b_exponent != 8'hFF) begin
                        if (b_mantissa == 23'b0) z <= 32'h7FC00000;

                        else begin
                            z_exponent <= a_exponent;
                            z_sign <= a_sign ^ b_sign;
                            z_mantissa <= 23'b0;
                        end
                    end else if (b_exponent == 8'hFF && a_exponent != 8'hFF) begin
                        if (a_mantissa == 23'b0) z <= 32'h7FC00000;

                        else begin
                            z_exponent <= b_exponent;
                            z_sign <= a_sign ^ b_sign;
                            z_mantissa <= 23'b0;
                        end
                    end else if (a_mantissa == 23'b0 || b_mantissa == 23'b0) begin
                        z_exponent <= 24'b0;
                        z_mantissa <= 23'b0;
                        z_sign <= a_sign ^ b_sign;
                    end else begin
                        product <= {1'b1, a_mantissa} * {1'b1, b_mantissa};
                    end
                    counter <= counter + 1;
                end
                3'b010: begin

                    z_exponent <= a_exponent + b_exponent - 127;
                    if (product[49:48] >= 2) begin
                        product <= product >> 1;
                        z_exponent <= z_exponent + 1;
                    end
                    counter <= counter + 1;
                end
                3'b011: begin

                    {guard_bit, round_bit, sticky} <= {product[22], product[21], |product[20:0]};
                    z_mantissa <= product[48:25];

                    if (guard_bit & (round_bit | sticky)) begin
                        z_mantissa <= z_mantissa + 1;
                    end else if (guard_bit & ~round_bit & ~sticky & z_mantissa[0]) begin
                        z_mantissa <= z_mantissa + 1;
                    end
                    if (z_mantissa == 24'h1000000) begin
                        z_mantissa <= 23'h0;
                        z_exponent <= z_exponent + 1;
                    end
                    counter <= counter + 1;
                end
                3'b100: begin

                    if (z_exponent >= 8'hFF) begin
                        z_exponent <= 8'hFF;
                        z_mantissa <= 23'b0;
                    end else if (z_exponent <= 1) begin
                        z_exponent <= 8'h0;
                        z_mantissa <= z_mantissa >> (1 - z_exponent);
                    end
                    z <= {z_sign, z_exponent, z_mantissa[22:0]};
                    counter <= 3'b0;
                end
                default: counter <= 3'b0;
            endcase
        end
    end

endmodule

