module sub_64bit (
    input [63:0] A,
    input [63:0] B,
    output [63:0] result,
    output overflow
);

    wire signed [63:0] signed_A = $signed(A);
    wire signed [63:0] signed_B = $signed(B);
    wire signed [63:0] signed_result = signed_A - signed_B;

    assign result = signed_result;


    wire positive_overflow = (A[63] == 1'b0 && B[63] == 1'b1 && result[63] == 1'b1);
    wire negative_overflow = (A[63] == 1'b1 && B[63] == 1'b0 && result[63] == 1'b0);

    assign overflow = positive_overflow | negative_overflow;

endmodule

